// Generated by tools/eng/build_eng.py from tools/eng/ (comparative.json, texts/, research/) and assets/eng/img/credits.json.
window.EngData = {"comparative":{"year":2027,"source":"Prescribed Material for the Leaving Certificate English Examination in 2027 (Department of Education circular, 27 February 2025): https://www.curriculumonline.ie/getmedia/ee4aa8b9-06c6-4091-974b-ea444dbae0af/Prescribed-Material-for-the-Leaving-Certificate-English-Examination-2027.pdf","rules":["At Higher Level you study three texts for the comparative, from the prescribed list, in the modes set for your year.","For 2027 the Higher Level modes are Theme or Issue, Cultural Context, and General Vision and Viewpoint. All three are on the 2027 paper: you answer on one.","A single 70-mark question needs at least two of your texts; a 30 + 40 question needs one text in part (a) and the two others in part (b).","A Shakespeare play must be one of your Higher Level texts: as your single text or as one of your comparative texts. If Othello is in your comparative, your single text has to be another text.","A film can be one of your texts, and it should be discussed as a film: what we see and hear, not just what happens. You may refer to only one film in all your Paper 2 answers.","You can't reuse your single text in the comparative. Using a text that isn't prescribed, or the wrong combination, costs a third of a 70-mark answer."],"marks":{"total":70,"split":[30,40],"criteria":[{"code":"P","name":"Clarity of purpose","pct":30,"of70":21,"what":"Engagement with the set task: relevance, focus, originality, freshness, evidence of critical literacy, clear aim, understanding of genre.","do":"Answer the exact question asked, in the mode asked, from your first sentence to your last.","comp":"For the comparative: understanding of the mode, focus on the exact task set, and effective comparison within the mode."},{"code":"C","name":"Coherence of delivery","pct":30,"of70":21,"what":"Ability to sustain the response over the entire answer: continuity of argument, sequencing, management of ideas, choice of reference, use of examples, engagement with texts, control of register and shape.","do":"Build every paragraph the same way (PACE) and compare the texts inside each paragraph, never one text after another.","comp":"For the comparative: a sustained comparative focus, ideas managed and sequenced, apt use of examples."},{"code":"L","name":"Efficiency of language use","pct":30,"of70":21,"what":"Management and control of language to achieve clear communication: vocabulary, syntax, sentence patterns, punctuation appropriate to the register, use of lively interesting phrasing, energy, style, fluency.","do":"Use the language of comparison (similarly, in contrast, to a far greater extent) and the words of the mode.","comp":"For the comparative: fluency, quality of expression, and the use of comparative language."},{"code":"M","name":"Accuracy of mechanics","pct":10,"of70":7,"what":"Spelling and grammar: appropriate levels of accuracy in spelling and grammatical patterns appropriate to the register.","do":"Spell the titles, authors and characters right, every time.","comp":"For the comparative: accuracy of mechanics, the same as in any answer: spelling, grammar and punctuation, and the titles and names spelt right."}],"note":"These are the SEC's criteria for assessment, used for every answer on both English papers.","primacy":"Your marks for Coherence (C) and Language (L) can never be higher than your mark for Purpose (P). If you don't answer the question asked, in the mode asked, nothing else can make up for it.","single":"A single 70-mark question is marked on each criterion separately: P out of 21, C out of 21, L out of 21, M out of 7.","splitText":"A two-part question gets one mark for each part, judged against all four criteria together: part (a) out of 30, on one text; part (b) out of 40, comparing two other texts.","grades":[["H1","63–70"],["H2","56–62"],["H3","49–55"],["H4","42–48"],["H5","35–41"],["H6","28–34"],["H7","21–27"],["H8","0–20"]],"reward":["Comparing and/or contrasting: similarities and differences, in both content and style.","Describing and analysing the texts in the light of the mode.","Making connections between similar aspects of the texts, and recognising differences.","Showing that similarities and differences need to be qualified (to what extent?).","Grounding your answer in key moments: you don't have to cover the whole text.","Showing awareness of yourself as a reader: your reactions, responses and involvement.","The quality of the comparative writing and apt reference to the texts."],"rewardSource":"From the \"General\" note printed before the comparative in every SEC marking scheme, 2012–2026, and the instructions under each question."},"modes":[{"id":"theme","name":"Theme or Issue","short":"Theme","what":"A theme is a big idea a text keeps returning to, like power, freedom or courage. You compare how each text presents it, how it develops through key moments, and what each text finally says about it.","ask":["How is the theme introduced at the start?","Which characters carry it, and how do they change?","Which key moments develop it?","Is it resolved at the end, and how?","What is the writer's (or director's) view of it?","Which text explores it most powerfully, and why?"],"hook":"Theme: the big idea. Ask what each text SAYS about it, not just that it's there.","words":["explores","presents","develops","challenges","is central to","comes to a head","is resolved","endures","corrupts","liberates","confines","defiance","complicity","moral courage","manipulation","injustice"],"topics":["Power and control","Freedom and entrapment","Courage and silence"],"official":{"quote":"Comparing texts on a prescribed theme(s). These would have to be themes which were pervasive and central to the texts chosen for study.","src":"Department of Education, Guidelines for Teachers of English (Leaving Certificate), Approaches to the Comparative Study of Texts"}},{"id":"cc","name":"Cultural Context","short":"Cultural context","what":"The world of the text: the society its characters live in, its values, rules and power structures, and how that world shapes their lives and choices.","ask":["Who holds power, and how do they use it?","What does this society value: money, status, reputation, faith?","What roles do men and women have? What is marriage for?","What part do religion, the law and institutions play?","Do characters conform or rebel, and what does it cost them?","Would you want to live in this world?"],"hook":"Cultural context: the WORLD of the text. Who has power, what's valued, what's allowed.","words":["patriarchal","hierarchical","rigid","insular","repressive","oppressive","conformity","status","respectability","reputation","institution","authority","hypocrisy","complicity","power structures","social class"],"topics":["Power and authority","Class, money and status","Gender roles and marriage","Religion and the Church","Family and community","Law, institutions and justice","Race and the outsider"],"official":{"quote":"Compare texts focusing on social rituals, values, and attitudes. This is not to be seen as a sociological study of the texts. It means taking some perspectives which enable the students to understand the kind of values and structures with which people contend.","src":"Department of Education, Guidelines for Teachers of English (Leaving Certificate), Approaches to the Comparative Study of Texts"}},{"id":"gvv","name":"General Vision and Viewpoint","short":"Vision and viewpoint","what":"The text's outlook on life: is it bleak, hopeful or somewhere between? You trace the light and dark moments, especially the opening and the ending, and say what view of people and society the text leaves you with, and how the writer or director shapes that view.","ask":["What is the outlook at the opening?","Which moments are light, and which are dark?","Does the outlook change, and when?","How does it end, and what does the ending say about people?","How does the writer (or director: music, light, camera, voiceover) shape your view?","Is the vision bleak, hopeful or mixed overall?"],"hook":"Vision: the VIEW OF LIFE. Track light vs dark, and judge it on the ending.","words":["bleak","hopeful","optimistic","pessimistic","redemptive","tragic","uplifting","harrowing","poignant","bittersweet","ambiguous","cathartic","cynical","life-affirming","resolution","outlook"],"topics":["The opening","Light and dark moments","The ending","View of human nature"],"official":{"quote":"The broad outlook of the authors of the texts and/or of the texts themselves as interpreted and understood by the reader.","src":"SEC marking schemes (2012, 2017, 2019)","also":"Compare texts from the standpoint of the view they offer on life. Is it optimistic or pessimistic? What aspects of life do they concentrate on and why? (Guidelines for Teachers of English)"}}],"structure":{"time":"About 65 minutes for the 70-mark question (Paper 2 is 3 hours 20 minutes).","length":"Aim for an introduction, 4 or 5 comparative paragraphs and a conclusion: roughly 1,000 to 1,300 words.","parts":[{"name":"Introduction","what":"Answer the question in your first sentence. Name the three texts with their authors or director, and the mode. Say briefly where your answer is going.","avoid":"Don't open with 'In this essay I will'. Don't retell the plots."},{"name":"Comparative paragraphs","what":"One aspect of the question per paragraph. Compare the texts inside every paragraph using PACE, so each paragraph is a mini-essay that answers the question.","avoid":"Don't write one paragraph per text: that's three separate essays, not a comparison."},{"name":"Conclusion","what":"Answer the question again in light of everything you've shown. Name the most important similarity or difference. Give your own response: which text affected you most, and why.","avoid":"Don't add a new point you haven't argued."}],"pace":[{"k":"P","name":"Point","what":"A comparative topic sentence that answers the question and names this paragraph's aspect.","eg":"In all three texts, power lies with those who can control others, but only in Othello is it seized through words alone."},{"k":"A","name":"Anchor","what":"Anchor the point in a key moment from your first text: what happens, a short quote or detail, and what it shows.","eg":"In Sive, Mena agrees to the match because Seán Dóta's money will rid her house of Sive."},{"k":"C","name":"Compare","what":"Link to your second and third texts with a comparative phrase, each anchored in a key moment: alike, different, or the same to a greater or lesser degree.","eg":"Similarly, in The Shawshank Redemption, Warden Norton's power rests on money: the prisoners' labour fills his safe. In contrast, Iago holds no high rank, yet he controls Othello completely through words."},{"k":"E","name":"Evaluate","what":"Say what the comparison shows and tie it back to the question: which text goes furthest, and what it leaves you thinking.","eg":"Of the three, Othello offers the bleakest view of power, because Iago needs nothing but Othello's trust to destroy him."}],"hook":"PACE yourself: Point, Anchor, Compare, Evaluate. Every paragraph, every time."},"language":[{"id":"same","name":"Showing similarity","items":["Similarly,","Likewise,","In the same way,","This is echoed in","mirrors","parallels","Both … and …","Much like","also","shares this"]},{"id":"differ","name":"Showing difference","items":["In contrast,","However,","Whereas","Conversely,","On the other hand,","Unlike","stands in stark contrast to","could not be more different","differs sharply"]},{"id":"degree","name":"Showing degree","items":["to a far greater extent","to a lesser degree","less overtly","more subtly","more explicitly","goes further than","is far bleaker","Although both …, only …","While …, …"]},{"id":"moment","name":"Bringing in a key moment","items":["This is crystallised in the moment when","A key moment that captures this is when","Nowhere is this clearer than when","This comes to a head when","We see this most vividly when","This is captured in the scene where"]},{"id":"judge","name":"Evaluating","items":["Ultimately,","This leaves the reader with","This leaves the viewer with","As a result, the vision becomes","This matters because","Of the three texts,","It is this that makes","For me, the most powerful"]}],"sources":[{"name":"Assessment Arrangements 2027 (Department of Education and Youth, September 2026)","url":"https://assets.gov.ie/static/documents/54a1450c/FINAL_v2_English_Assessment_Arrangements_2027.pdf"},{"name":"The 2027 prescribed material circular","url":"https://www.curriculumonline.ie/getmedia/ee4aa8b9-06c6-4091-974b-ea444dbae0af/Prescribed-Material-for-the-Leaving-Certificate-English-Examination-2027.pdf"},{"name":"SEC marking scheme, English Higher Level 2026 (copy)","url":"https://exam-papers.stikleaf.com/markingschemes/2026/lc/2/LC002ALP000EV.pdf"},{"name":"Leaving Certificate English syllabus","url":"https://www.curriculumonline.ie/getmedia/3bb84cb3-59af-4ab3-8965-61656bddc5d7/SCSEC14_English_Syllabus.pdf"},{"name":"Guidelines for Teachers of English","url":"https://www.curriculumonline.ie/getmedia/75b6e39e-876e-4ea8-9d2f-8b9108853787/SCSEC14_English_guidelines.pdf"}],"paper":{"source":{"name":"Assessment Arrangements for Junior Cycle and Leaving Certificate Examinations 2027 (Department of Education and Youth, September 2026)","url":"https://assets.gov.ie/static/documents/54a1450c/FINAL_v2_English_Assessment_Arrangements_2027.pdf"},"time":"Paper 2, Higher Level: 3 hours 20 minutes, 200 marks.","sections":[{"name":"Single Text","marks":60,"what":"Othello (or your other single text): answer one of two questions. No change for 2027."},{"name":"Comparative Study","marks":70,"what":"For 2027, questions on all three modes are on the paper: you answer on one mode. You pick one of the two questions on that mode; each is either a single 70-mark question or a question in two parts (30 + 40)."},{"name":"Poetry","marks":70,"what":"Unseen poem (20): one of two questions. Prescribed poetry (50): for 2027, one of five questions (one extra)."}],"seventy":"A single 70-mark question: refer to at least two texts. It is marked by the same criteria whether you use two texts or three.","split":"A two-part question: part (a) (30 marks) on one text, part (b) (40 marks) on two other texts. Part (b) doesn't have to link back to part (a)."},"current":"For 2027 you sit the current Leaving Certificate English syllabus: the revised Senior Cycle English specification hasn't started yet.","upgrades":[{"plain":"shows","exam":["highlights","exposes","lays bare"],"eg":"The ending of Sive exposes the cruelty of a world that sells its girls."},{"plain":"is about","exam":["explores","examines","grapples with"],"eg":"Small Things Like These explores the cost of keeping quiet."},{"plain":"is like / stands for","exam":["symbolises","represents","embodies"],"eg":"The poster in Andy's cell symbolises hope hidden in plain sight."},{"plain":"sums up","exam":["encapsulates","epitomises","crystallises"],"eg":"Brooks's carving encapsulates the despair of a man who has lost his place in the world."},{"plain":"sad, depressing","exam":["bleak","desolate","harrowing"],"eg":"The closing scene of Sive is unrelentingly bleak."},{"plain":"happy ending","exam":["an uplifting resolution","a hopeful close","a note of redemption"],"eg":"The Shawshank Redemption ends on an uplifting resolution."},{"plain":"gets worse","exam":["darkens","deteriorates","spirals"],"eg":"Othello's world darkens once Iago's poison takes hold."},{"plain":"gets better","exam":["the outlook brightens","hope emerges","light breaks through"],"eg":"In the final pages the outlook brightens as Bill brings Sarah home."},{"plain":"shocking","exam":["harrowing","disturbing","unsettling"],"eg":"The murder of Desdemona is deeply harrowing."},{"plain":"mean, cruel people","exam":["callous","ruthless","tyrannical"],"eg":"Warden Norton is ruthless behind his Bible-quoting piety."},{"plain":"rich people are in charge","exam":["wealth confers power","money dictates who matters"],"eg":"In Sive, money dictates who matters and who is sold."},{"plain":"poor","exam":["impoverished","poverty-stricken","deprived"],"eg":"The Glavins' impoverished household is soured by want."},{"plain":"the people in charge","exam":["those in authority","the powerful","the establishment"],"eg":"In Small Things Like These, the establishment is the Church."},{"plain":"follows the rules","exam":["conforms","obeys the norms","toes the line"],"eg":"Most of New Ross conforms, keeping its eyes down."},{"plain":"breaks the rules","exam":["defies","rebels against","challenges"],"eg":"Bill finally defies the silence of the town."},{"plain":"the same as","exam":["mirrors","echoes","parallels"],"eg":"Red's release mirrors Brooks's, until Red chooses hope."},{"plain":"different from","exam":["in stark contrast to","diverges from","unlike"],"eg":"In stark contrast to Sive, Shawshank lets hope win."},{"plain":"more","exam":["to a far greater extent","more powerfully","more starkly"],"eg":"Othello presents jealousy more powerfully than any other text."},{"plain":"a bit","exam":["to a limited extent","partially","only fleetingly"],"eg":"Hope appears only fleetingly in Sive."},{"plain":"at the start","exam":["from the outset","in the opening scenes","initially"],"eg":"From the outset, Iago's hatred is clear."},{"plain":"at the end","exam":["in the closing scene","ultimately","by the end"],"eg":"Ultimately, Othello dies on a kiss."},{"plain":"an important moment","exam":["a pivotal moment","a turning point","a key moment"],"eg":"The temptation scene is the pivotal moment of the play."},{"plain":"the main character","exam":["the protagonist","the central character"],"eg":"The protagonist of Small Things Like These is Bill Furlong."},{"plain":"the bad guy","exam":["the antagonist","the villain","the manipulator"],"eg":"Iago is the play's arch-manipulator."},{"plain":"the world of the story","exam":["the cultural context","the society depicted","the world of the text"],"eg":"The society depicted in Sive is ruled by land and money."},{"plain":"I think","exam":["I would argue that","it is evident that","clearly"],"eg":"It is evident that power in Shawshank rests on fear."},{"plain":"I liked it","exam":["I found it compelling","it moved me deeply","it struck me"],"eg":"I found Bill's quiet courage deeply moving."},{"plain":"makes you feel sorry for","exam":["evokes sympathy for","elicits pity for","draws us to"],"eg":"Sive's helplessness evokes sympathy for her from the first scene."},{"plain":"says","exam":["asserts","insists","declares"],"eg":"Red insists that hope is a dangerous thing."},{"plain":"a lot","exam":["profoundly","deeply","greatly"],"eg":"Andy's escape profoundly shapes my view of the film."},{"plain":"because","exam":["since","as a result of","owing to"],"eg":"Desdemona dies as a result of Iago's lies."}]},"order":["sive","othello","shawshank","stlt"],"texts":{"sive":{"id":"sive","title":"Sive","author":"John B. Keane","kind":"drama","made":"1959","setting":"The Glavins' poor farmhouse kitchen in remote rural Co. Kerry, in the 1950s.","gist":"Sive, a schoolgirl born outside marriage whose mother is dead, lives with her uncle Mike, his bitter wife Mena and her grandmother Nanna. When the matchmaker Thomasheen Seán Rua offers Mike and Mena £200 to marry her to Seán Dóta, an elderly farmer, they force the match on her and cut her off from Liam Scuab, the young man she loves, while Thomasheen burns Liam's letter offering her escape. On the eve of the wedding Sive runs out across the bog and drowns herself.","people":[{"name":"Sive","who":"A gentle schoolgirl born outside marriage; her mother, Mike's sister, is dead, and she loves Liam Scuab.","group":"The Glavin house","tag":"The girl","wants":"To stay at school and to be with Liam.","end":"She drowns in a bog hole on the night before the wedding.","face":{"file":"sive-s-nanna.jpg","x":0.5,"y":0.45,"zoom":4.5,"ar":0.6672,"from":"Gaiety Theatre, Dublin, 2024"},"pos":[320,500],"trait":"Gentle, shy and trusting","check":{"like":["kind","sweet","quiet","innocent","nice","soft","naive","young","timid","nervous","scared","afraid","good","pure","vulnerable","helpless","loving","lonely","sad","clever","bright"],"want":["school","educat","study","studies","learn","liam","love","free","escape","happy","exams","teacher"]}},{"name":"Mena Glavin","who":"Mike's hard, bitter and childless wife, shaped by a poor upbringing; she drives the match for the money.","group":"The Glavin house","tag":"Mike's wife","wants":"The £200, and Sive and Nanna out of her house.","end":"Liam turns on her over Sive's body.","pos":[440,290],"trait":"Hard, bitter and greedy","check":{"like":["mean","cruel","nasty","harsh","cold","jealous","selfish","spite","angry","ruthless","evil","heartless","money","grasp","scheming","manipul","bitch","horrible","resent","wicked"],"want":["money","cash","pound","200","rid","gone","out","house","home","match","sell","rich","wealth","marry","married","away","leave"]},"face":{"file":"faces/sive-mena.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Abbey Theatre, Dublin, 2014"}},{"name":"Mike Glavin","who":"Sive's uncle, a small farmer who knows the match is wrong but is too weak to stop it.","group":"The Glavin house","tag":"Sive's uncle","wants":"Peace in the house, and the money; he knows the match is wrong.","end":"Left dazed, thinking of the priest and holy ground.","pos":[200,290],"trait":"Weak, torn and guilty","check":{"like":["coward","spineless","soft","conflict","ashamed","guilt","quiet","unsure","divided","tempt","greedy","pushover","henpeck","torn","dominated","scared","afraid"],"want":["peace","quiet","money","cash","pound","200","calm","easy","happy","match","rich"]},"face":{"file":"faces/sive-mike.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Abbey Theatre, Dublin, 2014"}},{"name":"Nanna Glavin","who":"Mike's mother and Sive's grandmother; sharp-tongued and pipe-smoking, she is Sive's only defender in the house.","group":"The Glavin house","tag":"Mike's mother, Sive's grandmother","wants":"To protect Sive from the match.","end":"She grieves beside Sive's body.","face":{"file":"sive-s-nanna.jpg","x":0.69,"y":0.2,"zoom":4,"ar":0.6672,"from":"Gaiety Theatre, Dublin, 2024"},"pos":[200,90],"trait":"Sharp-tongued, sly and fiercely protective","check":{"like":["witty","clever","funny","cheeky","tough","strong","loyal","caring","loving","kind","brave","stubborn","feisty","old","protect","defend","sharp","sly","sneaky","smart"],"want":["protect","save","help","stop","defend","safe","escape","prevent","match","free"]}},{"name":"Thomasheen Seán Rua","who":"The local matchmaker: cunning, persuasive and driven by his own payment.","group":"The match","tag":"The matchmaker","wants":"His fee for making the match.","end":"He slips away when Sive is found.","pos":[720,100],"trait":"Cunning, smooth-talking and money-mad","check":{"like":["sly","clever","sneaky","greedy","liar","lying","manipul","persuas","charm","scheming","crafty","devious","slimy","sleazy","fake","selfish","talker","dishonest"],"want":["money","cash","pay","paid","profit","commission","match","deal","rich","fee","reward"]},"face":{"file":"faces/sive-thomasheen.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Abbey Theatre, Dublin, 2014"}},{"name":"Seán Dóta","who":"An elderly, well-off bachelor farmer who will pay to marry Sive.","group":"The match","tag":"The old farmer","wants":"A young wife, bought with his money.","end":"He slips away when Sive is found.","pos":[660,470],"trait":"Old, rich and lecherous","check":{"like":["creepy","dirty","gross","pervert","lonely","wealthy","money","ugly","pathetic","desperate","lust","old","rich","disgusting","sleazy"],"want":["marry","marriage","wife","young","girl","bride","woman"]},"face":{"file":"faces/sive-sean-dota.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Abbey Theatre, Dublin, 2014"}},{"name":"Liam Scuab","who":"The young man who loves Sive; a cousin of her father, so Mike hates him.","group":"On Sive's side","tag":"Sive's sweetheart","wants":"To marry Sive and take her away.","end":"He carries her drowned body home.","pos":[80,500],"trait":"Young, honest and loyal","check":{"like":["kind","good","brave","loving","caring","decent","true","faithful","romantic","determined","passionate","nice","honest","loyal","young","strong"],"want":["marry","marriage","love","escape","save","rescue","together","away","elope","wife","england"]},"face":{"file":"faces/sive-liam.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Druid Theatre, 2003"}},{"name":"Pats Bocock","who":"A travelling man whose blunt sayings expose the greed behind the match; he carries Liam's escape plan to Nanna.","group":"The travellers","tag":"A travelling man","wants":"To show up the greed behind the match; he carries Liam's letter.","end":"He saw a girl crossing the bog that night.","pos":[910,290],"trait":"Blunt, wise and fearless","check":{"like":["honest","truthful","clever","bold","brave","outsider","wander","poor","funny","sharp","mysterious","insight","wise","blunt","fearless"],"want":["expose","truth","greed","help","letter","warn","mock","shame","reveal","stop","show"]},"face":{"file":"faces/sive-pats.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Abbey Theatre, Dublin, 2014"}},{"name":"Carthalawn","who":"Pats's son, whose mocking and cursing songs comment on the action like a chorus.","group":"The travellers","tag":"Pats's son, the singer","wants":"To mock the greedy in his songs.","end":"He sings the lament that ends the play.","pos":[910,500],"trait":"Mocking; he sings the hard truth","check":{"like":["song","sing","singer","music","curse","funny","cheeky","mock","honest","truth","loud","wild","strange","chorus","rude"],"want":["mock","sing","song","curse","shame","greed","expose","truth","laugh","punish"]},"face":{"file":"faces/sive-carthalawn.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Abbey Theatre, Dublin, 2014"}}],"moments":[{"id":"sive-1","title":"Nanna and Mena at war","where":"Act 1, Scene 1","when":"opening","what":"The play opens in a poorly furnished kitchen where Nanna, hiding her pipe, and her daughter-in-law Mena trade insults, with Nanna mocking Mena's poor background and her childlessness. When Sive comes in from school, Mena resents that she is still being educated instead of contributing to the house.","why":"It sets up a poor, bitter household where the women fight over status and space, and where Sive has no protector with real power.","modes":["cc","gvv"],"quote":"","sure":true,"tell":["A kitchen in rural Kerry, in the 1950s. Not much furniture. Not much money. And two women who can't stand each other.","Nanna, the old grandmother, hides her pipe and mocks Mena for being poor and childless. Mena gives it straight back.","Then Sive walks in from school, and Mena's resentment finds a new target: why is this girl still at her books when she could be earning?"],"chain":{"happens":"Nanna and Mena trade insults in the bare kitchen, and Mena resents Sive still being at school.","shows":"Poverty has made the house bitter, and a girl is valued only for what she can bring in.","leads":"Mena wants Sive out of the house, so the match will tempt her."}},{"id":"sive-2","title":"Thomasheen's offer","where":"Act 1, Scene 1","when":"opening","what":"The matchmaker Thomasheen Seán Rua tells Mena in secret that Seán Dóta, an elderly farmer, wants to marry Sive and will pay Mike and Mena £200, and will take Nanna into his house as well. Mena, tempted by the money and the chance to be rid of both Sive and Nanna, agrees to work on Mike.","why":"Marriage is shown as a cash bargain in which Sive is effectively sold by the adults around her.","modes":["theme","cc"],"quote":"the grass of twenty cows","sure":true,"tell":["Enter the matchmaker. Thomasheen Seán Rua has a deal, and he tells it to Mena in secret.","Seán Dóta, an old farmer with land, wants to marry Sive. He'll pay £200. He'll even take Nanna off their hands.","For Mena that means money, and a house with neither Sive nor Nanna in it. She agrees to work on Mike."],"chain":{"happens":"Thomasheen offers £200 if Sive marries the old farmer Seán Dóta.","shows":"Marriage is a bargain, and a girl is something to be sold.","leads":"Mena agrees to work on Mike, and the match is set in motion."}},{"id":"sive-3","title":"Mike throws Liam out","where":"Act 1, Scene 1","when":"opening","what":"Mike at first refuses the match angrily, horrified at giving a schoolgirl to an old man. Later he catches Liam Scuab on a secret visit to Sive and orders him away, blaming Liam's cousin, Sive's father, for leaving her mother pregnant and unmarried; the scene ends with Mike calling for Mena.","why":"Mike's hatred of Liam's family and his fear that Sive will repeat her mother's 'shame' begin to push him towards the match.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["At first Mike says no. Angrily. A schoolgirl and an old man? He knows it's wrong.","But then he catches Liam Scuab, the young man who loves Sive, visiting her in secret, and he orders him away.","Old wounds: Mike blames Liam's cousin, Sive's father, for what happened to her mother. And the scene ends with Mike calling for Mena."],"chain":{"happens":"Mike refuses the match at first, then throws Liam out, blaming Liam's family.","shows":"Mike knows it's wrong, but old grudges and weakness win.","leads":"Sive loses her protector, and Liam is shut out."}},{"id":"sive-4","title":"Seán Dóta comes courting","where":"Act 1, Scene 2","when":"middle","what":"Thomasheen brings Seán Dóta to the house; Seán acts bashful and sings a foolish song, but when he is sent to walk Sive to a neighbour's house he makes a grab at her. In the same scene Thomasheen brushes aside Mike's doubts, dismissing love as something people like them cannot afford and telling how poverty after his father's suicide cost him his own chance of marriage.","why":"Love is dismissed as a luxury of the better-off, and Sive is left exposed to a predatory old man by the adults meant to protect her.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Seán Dóta comes courting. He's bashful, he sings a foolish song, and when he's sent to walk Sive to a neighbour's house, he grabs at her.","Meanwhile Thomasheen sweeps away Mike's doubts. Love? People like them can't afford it.","And he says why: after his father's suicide, poverty cost him his own chance to marry. In this world, money decides who gets to love."],"chain":{"happens":"Seán Dóta courts Sive clumsily and grabs at her; Thomasheen says love is for people who can afford it.","shows":"Money decides who gets to love, and Sive is prey.","leads":"Mike's doubts are brushed aside and the match moves closer."}},{"id":"sive-5","title":"The travelling men","where":"Act 1, Scene 3","when":"middle","what":"Nanna welcomes the travelling men Pats Bocock and his son Carthalawn, but Mena and Thomasheen refuse them food and money and resent Carthalawn's mocking songs. When the travellers tell Nanna about the match and she challenges Mena and Thomasheen, they bully her and threaten her with the county home.","why":"It shows who holds power in the house, how the old and the poor are treated, and introduces the travellers as the play's truth-telling chorus.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Two travelling men come to the door: Pats Bocock and his son Carthalawn, who sings.","Nanna welcomes them. Mena and Thomasheen give them nothing, and squirm at Carthalawn's mocking songs.","When the travellers tell Nanna about the match and she challenges them, Mena and Thomasheen turn on her: keep quiet, or it's the county home."],"chain":{"happens":"The travellers arrive; Nanna welcomes them, and Mena and Thomasheen bully her.","shows":"The outsiders see the truth and say it; the weak are silenced.","leads":"Nanna is threatened with the county home and loses her voice."}},{"id":"sive-6","title":"Mena tells Sive the truth","where":"Act 1, Scene 3","when":"middle","what":"Putting on a motherly air, Mena tries to tempt Sive with all that Seán Dóta can offer; when Sive refuses, Mena cruelly tells her the truth about her birth and says she will leave school and no longer sleep beside Nanna. Mena also reveals the poverty and desperation that drove her into her own marriage.","why":"Sive's birth is used as a weapon: in this society a girl born outside marriage is told her only way to respectability is a husband.","modes":["theme","cc","gvv"],"quote":"You will have no name till you take a husband.","sure":true,"tell":["Now Mena works on Sive herself, all motherly sweetness: think of everything Seán Dóta can give you.","Sive refuses. So Mena tells her the truth about her birth, cruelly, and that she'll leave school and no longer sleep beside Nanna.","But we also see where Mena's hardness comes from: the poverty and desperation that pushed her into her own marriage."],"chain":{"happens":"Mena tells Sive the truth about her birth and says she'll leave school.","shows":"Shame is a weapon, and Mena passes on her own hard life.","leads":"Sive is crushed, and cut off from Nanna and from school."}},{"id":"sive-7","title":"Liam's plea","where":"Act 2, Scene 1","when":"middle","what":"Having heard about the match, Liam comes to the house and begs Mike and Mena not to give Sive to Seán Dóta, even offering to keep away from her; they send him off. Mena then lies to Sive that Liam came only to wish her joy and has left her for good.","why":"The one person who speaks up openly is driven away, and Mena's lie cuts Sive off from her only hope.","modes":["theme","cc"],"quote":"","sure":true,"tell":["Liam hears about the match and comes to beg: don't give her to Seán Dóta. He'll even keep away from her himself.","Mike and Mena send him off.","Then Mena lies to Sive. Liam only came to wish her joy, she says. He's gone for good."],"chain":{"happens":"Liam begs them not to give Sive away; Mena lies to Sive that he's gone.","shows":"Love is powerless against money and lies.","leads":"Sive believes Liam has left her for good."}},{"id":"sive-8","title":"Nanna pleads with Mike","where":"Act 2, Scene 1","when":"middle","what":"As Mike gets ready to see the priest about the wedding, Nanna begs him to stop the match, warning that Sive's dead mother will curse it. Mike insists it is for the best but cannot look his mother in the face, and justifies himself by blaming Liam's family for what happened to his sister.","why":"Mike knows the match is wrong but chooses money, his wife and respectability over his conscience.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Mike is getting ready to see the priest about the wedding, and Nanna begs him to stop it.","Sive's dead mother, she warns, will curse this match.","Mike says it's for the best, but he can't look his mother in the face. So he blames Liam's family instead."],"chain":{"happens":"Nanna begs Mike to stop the match, and he can't look her in the face.","shows":"Conscience against greed, and Mike is too weak to act.","leads":"The wedding goes ahead."}},{"id":"sive-9","title":"The letter is burned","where":"Act 2, Scene 2","when":"climax","what":"On the day before the wedding, Pats brings Nanna a letter from Liam telling Sive to slip out that night so they can be married in secret; Mike finds out about it and, told it is only Liam's farewell, promises to pass it to Sive unopened. Thomasheen spots it, insists that Mike open it and, once the plan is exposed, burns it, while Mike, uneasy, does nothing to let Sive know.","why":"Sive's last chance of escape is destroyed by the matchmaker, while the uncle who could save her stays silent.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["The day before the wedding. Pats brings Nanna a letter from Liam: Sive should slip out tonight, and they'll marry in secret.","Mike finds out. Told it's only Liam's farewell, he promises to pass it to Sive unopened.","Thomasheen makes him open it, then burns it. And Mike, uneasy, does nothing. One small silence, and the last way out is gone."],"chain":{"happens":"Thomasheen burns Liam's letter, and Mike does nothing.","shows":"One small silence destroys the last hope of escape.","leads":"Sive never learns of Liam's plan."}},{"id":"sive-10","title":"The eve of the wedding","where":"Act 2, Scene 2","when":"climax","what":"Mena and Sive come home from buying wedding clothes with Seán Dóta's money, and a miserable Sive goes to her room while the men drink with Seán. Pats and Carthalawn arrive on a traditional wedding visit and provoke Seán and Thomasheen: Pats says that men of money like Seán will be the new lords of the land, and Carthalawn sings that Seán will soon be travelling by hearse.","why":"The celebration is hollow, and the travellers' songs tell the truth about greed and foreshadow a death, though the hearse will be for Sive.","modes":["cc","gvv"],"quote":"","sure":true,"tell":["The eve of the wedding. Sive comes home with clothes bought with Seán Dóta's money and goes to her room, miserable. The men drink.","Then Pats and Carthalawn arrive on a wedding visit, and they haven't come to celebrate.","Pats says men of money like Seán will be the new lords of the land. Carthalawn sings that Seán will soon be travelling by hearse."],"chain":{"happens":"On the wedding eve Pats and Carthalawn mock Seán Dóta in song.","shows":"The travellers judge the greed of the house and foreshadow death.","leads":"Sive, alone and miserable, slips out that night."}},{"id":"sive-11","title":"Sive is found drowned","where":"Act 2, Scene 2","when":"climax","what":"Mena discovers that Sive has stolen out of the house, and Pats admits he glimpsed a girl crossing the bog. Liam carries in Sive's body: she has drowned in a bog hole, a death the household takes to be suicide, and as Thomasheen and Seán Dóta slip away, Liam turns furiously on Mena.","why":"Sive's only escape from the match is death, and those who profited from it run from the consequences.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Mena finds that Sive is gone. Pats admits he saw a girl crossing the bog in the dark.","Then Liam carries her in. Sive has drowned in a bog hole, and the house takes it to be suicide.","Thomasheen and Seán Dóta slip away. Liam turns on Mena."],"chain":{"happens":"Sive drowns in a bog hole, and Liam carries her in.","shows":"The tragic price of a world that sells its girls.","leads":"Thomasheen and Seán Dóta slip away, and Liam turns on Mena."}},{"id":"sive-12","title":"Holy ground and a lament","where":"Act 2, Scene 2","when":"ending","what":"Mike, dazed, thinks first of fetching the priest and of whether Sive can be buried in holy ground. The play closes with Carthalawn's song mourning Sive and Nanna grieving beside her body.","why":"The ending condemns a society that cares more for respectability than for a girl's life, and leaves grief rather than justice.","modes":["cc","gvv"],"quote":"","sure":true,"tell":["Mike, dazed, thinks first of the priest, and of whether Sive can be buried in holy ground.","The play ends with a song: Carthalawn mourns Sive, and Nanna grieves beside her body.","No one is punished. No one is saved. That's what makes it so bleak."],"chain":{"happens":"Mike thinks of the priest and holy ground; Carthalawn's lament ends the play.","shows":"Respectability still comes first, and the vision is bleak.","leads":"No justice and no change: the play ends in grief."}}],"modes":{"theme":{"themes":[{"name":"Power and control","points":["Power in Sive lies with whoever controls money and the household: once Thomasheen offers £200, it is Mena, not Mike, who drives the match and works on her husband until he gives in [sive-2] [sive-3].","Sive herself has no say at all: her schooling, her bedroom and her marriage are all decided for her, and Mena announces each decision rather than asking [sive-6].","Control is kept through lies and destroyed words: Mena tells Sive that Liam has left her for good, and Thomasheen burns Liam's letter so that Sive never learns of his plan [sive-7] [sive-9].","The powerful bully the weak into silence: when Nanna challenges the match, Mena and Thomasheen threaten her with the county home [sive-5]."]},{"name":"Freedom and entrapment","points":["Sive is trapped by the circumstances of her birth: Mena tells her she will have no name until she takes a husband, so marriage to Seán Dóta is presented as her only way out [sive-6].","Mena is trapped too: she married to escape a desperately poor home and now shares a house with a mother-in-law who taunts her, which helps explain her hunger to be rid of both Sive and Nanna [sive-1] [sive-6].","Liam offers a real escape, but his letter is burned before Sive can read it [sive-9], so the only freedom left to her is death in the bog [sive-11]."]},{"name":"Courage and silence","points":["Mike's silence makes him complicit: he cannot look his mother in the face when he says the match is for the best [sive-8], and after Thomasheen burns Liam's letter he does nothing to warn Sive [sive-9].","Liam is the one character who speaks out openly, pleading with Mike and Mena to stop the match [sive-7] and condemning Mena over Sive's body [sive-11].","Courage comes from the margins: old Nanna confronts Mena and Thomasheen despite their threats [sive-5], and the travelling man Pats carries Liam's escape plan into the house [sive-9].","Sive objects to the match but is too isolated to act on it, so her death becomes a silent protest against the life chosen for her [sive-6] [sive-11]."]}]},"cc":{"aspects":[{"name":"Power and authority","points":["Authority in Sive belongs to the adults who control money and land, not to the young: Seán Dóta's wealth buys him a bride, and the matchmaker Thomasheen brokers the deal for his own gain [sive-2].","Mike is the man of the house in name only; Mena and Thomasheen steer him by playing on his love of money and his hatred of Liam's family [sive-3] [sive-4].","Old age brings a loss of authority: Nanna lives in her son's house on sufferance and can be silenced with threats of the county home [sive-5]."]},{"name":"Class, money and status","points":["Poverty drives the tragedy: Mena married to escape a desperately poor home and resents the cost of Sive's schooling, so £200 is an offer she will not refuse [sive-2] [sive-6].","A man's worth is measured in land and cattle: Thomasheen sells Seán Dóta as a man with the grass of twenty cows, and his age is brushed aside [sive-2].","Thomasheen treats love as something the poor cannot afford, rooted in his own story of a marriage lost to poverty after his father's suicide [sive-4].","Travelling people sit at the bottom of the social ladder, refused food and money by Mena and Thomasheen, yet Pats and Carthalawn see most clearly, warning that men of money like Seán will be the new lords of the land [sive-5] [sive-10]."]},{"name":"Gender roles and marriage","points":["Marriage is a bargain arranged by others, not a choice: a matchmaker, an aunt and an uncle settle Sive's future for cash while she is still at school [sive-2].","A woman's standing depends on a husband: Mena tells Sive she has no name until she marries, and the shame of her birth falls entirely on her and her dead mother [sive-6].","A girl's education is resented as a waste: Mena begrudges Sive's schooling and ends it once the match is made [sive-1] [sive-6].","Young women are left unprotected from men's desire: Seán Dóta makes a grab at Sive on the walk, yet the adults press ahead with the match [sive-4]."]},{"name":"Religion and the Church","points":["The Church appears as a source of rules and respectability rather than protection: Mike goes to the priest to arrange the wedding, and no priest or nun ever steps in to protect Sive [sive-8].","Catholic shame about sex outside marriage shapes everyone's view of Sive: Mike fears she will follow her mother's example, and Mena uses her birth against her [sive-3] [sive-6].","Mike's first thought at Sive's death is whether she can be buried in holy ground, since the Church then refused consecrated burial to suicides: respectability comes before grief [sive-12].","Faith is voiced most sincerely by the young lover, not the authorities: Liam warns Mike and Mena that a day will come when they must answer for what they are doing [sive-7]."]},{"name":"Family and community","points":["The family home is a battleground rather than a refuge: Nanna and Mena are bound together by marriage and trade insults from the first scene [sive-1].","Family history is held against the young: Mike hates Liam because Liam's cousin fathered Sive and left her mother, so one generation's wrongs fall on the next [sive-3].","Old community customs survive in Nanna's hospitality to the travelling men, which Mena and Thomasheen reject [sive-5]; the travellers act as the community's voice, carrying news of the match and singing the truth about it [sive-10].","The family's concern for its name outlasts Sive herself: Mike worries about the priest and burial while Nanna alone simply grieves [sive-12]."]},{"name":"Law, institutions and justice","points":["Law and the state are almost absent: no guard, court or official appears, and a private bargain made in a kitchen decides Sive's life [sive-2].","The one state institution mentioned, the county home, is used as a threat to frighten Nanna into silence [sive-5].","There is no justice at the end: Thomasheen and Seán Dóta slip away unpunished, and the only judgement comes from Liam's fury and Carthalawn's song [sive-11] [sive-12]."]}]},"gvv":{"opening":"The play opens in a cramped, poor kitchen full of insults and resentment, where Sive is treated as a burden. The only hints of hope are her schooling and her secret love for Liam.","ending":"Sive drowns in a bog hole on the eve of the wedding; the matchmaker and the bridegroom slip away, Mike worries about holy ground, and the play closes on a lament and Nanna's grief. The outlook is bleak: innocence is destroyed by greed and no one is brought to account.","outlook":"bleak","points":["Moments of light are brief: Liam's secret visit shows young love [sive-3] and the travellers' songs bring humour [sive-5], but both are soon crushed by the adults' greed.","The dark moments grow steadily harsher, from Mena's cruel revelation about Sive's birth [sive-6] to the burning of Liam's letter [sive-9], so the audience feels the trap closing.","Keane raises false hope near the end, as Liam's escape plan and Mike's doubts suggest Sive might be saved, which makes her death all the more shocking [sive-9] [sive-11].","The ending suggests that a society ruled by money and respectability destroys its most innocent members: Mike's first thought is holy ground, not his niece [sive-12].","The play leaves the audience angry at Mena and Thomasheen and full of pity for Sive and Nanna, though Mena's own story of poverty makes even her partly pitiable [sive-6] [sive-12].","Goodness exists in Liam, Nanna and the travelling men, but it is powerless against money, which deepens the bleakness [sive-7] [sive-11]."]}},"links":[["Nanna Glavin","Mike Glavin","his mother"],["Mike Glavin","Mena Glavin","married"],["Mike Glavin","Sive","her uncle"],["Nanna Glavin","Sive","her grandmother"],["Mena Glavin","Sive","wants her gone"],["Liam Scuab","Sive","loves her"],["Mike Glavin","Liam Scuab","throws him out"],["Thomasheen Seán Rua","Mena Glavin","makes the deal"],["Thomasheen Seán Rua","Seán Dóta","matchmaker for"],["Seán Dóta","Sive","will pay to marry her"],["Pats Bocock","Carthalawn","father and son"],["Pats Bocock","Nanna Glavin","brings Liam's letter"],["Thomasheen Seán Rua","Liam Scuab","burns his letter"]]},"othello":{"id":"othello","title":"Othello","author":"William Shakespeare","kind":"drama","made":"c. 1603","setting":"Venice, then the island of Cyprus, a Venetian military outpost, in the late sixteenth century during Venice's wars with the Ottoman Turks.","gist":"Othello, a celebrated Black general in the service of Venice, secretly marries Desdemona, a senator's daughter. His ensign Iago, consumed by resentment, uses lies, hints and a lost handkerchief to convince him that she is having an affair with his lieutenant Cassio. Othello murders Desdemona, learns the truth from Iago's wife Emilia, and kills himself.","people":[{"name":"Othello","who":"A celebrated general, a Black African ('the Moor'), who serves the Venetian state and secretly marries Desdemona.","group":"The couple","tag":"The general, \"the Moor\"","wants":"Desdemona's love, and his honour as a soldier.","end":"He kills Desdemona, then himself.","face":{"file":"othello-f-iago.jpg","x":0.32,"y":0.52,"zoom":3,"ar":0.5625,"from":"Othello, film, 1995"},"pos":[370,250],"trait":"Noble and proud, then wildly jealous","check":{"like":["brave","honour","respect","strong","soldier","leader","confident","trusting","gullible","naive","insecure","angry","violent","passion","loving","eloquent","jealous","noble","proud"],"want":["desdemona","love","wife","honour","respect","reputation","name","trust","proof","truth","loyal"]}},{"name":"Desdemona","who":"Brabantio's daughter, who marries Othello without her father's consent and stays loyal to him even as he kills her.","group":"The couple","tag":"Othello's wife","wants":"To be with Othello; she stays loyal to him.","end":"Othello smothers her; she dies protecting him.","face":{"file":"othello-f-desdemona.jpg","x":0.42,"y":0.3,"zoom":3,"ar":0.5625,"from":"Othello, film, 1995"},"pos":[670,250],"trait":"Brave, loving and loyal","check":{"like":["kind","gentle","innocent","faithful","true","sweet","strong","independent","honest","pure","good","devoted","defiant","brave","loving","loyal"],"want":["othello","husband","love","together","marriage","marry","loved","trust","cassio","help"]}},{"name":"Iago","who":"Othello's ensign ('ancient'), passed over for promotion, who is trusted as 'honest Iago' while he plots to destroy Othello.","group":"The plotter","tag":"Othello's ensign","wants":"Revenge on Othello for promoting Cassio.","end":"Exposed and arrested, he refuses to explain.","face":{"file":"othello-f-iago.jpg","x":0.71,"y":0.47,"zoom":2.6,"ar":0.5625,"from":"Othello, film, 1995"},"pos":[370,480],"trait":"Two-faced, clever and cruel","check":{"like":["evil","manipul","liar","lying","deceit","jealous","sneaky","cunning","sly","villain","scheming","smart","fake","bitter","resent","racist","sinister","devil","clever","cruel"],"want":["revenge","destroy","ruin","power","promot","lieutenant","position","rank","hate","downfall"]}},{"name":"Cassio","who":"Othello's young lieutenant, a Florentine gentleman whom Iago resents and frames as Desdemona's lover.","group":"Iago's pawns","tag":"Othello's lieutenant","wants":"To win back his place.","end":"He is left in charge of Cyprus.","pos":[110,330],"trait":"Charming and loyal, but weak with drink","check":{"like":["polite","gentleman","handsome","drunk","drink","honest","good","loyal","reckless","naive","trusting","kind","smooth","charming","weak"],"want":["job","position","rank","lieutenant","place","reinstat","back","forgiv","favour","reputation"]},"face":{"file":"faces/othello-cassio.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Othello, film, 1995"}},{"name":"Emilia","who":"Iago's wife and Desdemona's attendant, who finally exposes her husband and is killed by him.","group":"The plotter","tag":"Iago's wife, Desdemona's attendant","wants":"To serve Desdemona, and to please Iago.","end":"She exposes Iago, and he kills her.","pos":[670,480],"trait":"Worldly and blunt; brave at the end","check":{"like":["honest","loyal","outspoken","strong","bold","cynical","realistic","practical","fearless","clever","sharp","brave","blunt","worldly"],"want":["husband","help","serve","loyal","please","love","truth","justice"]},"face":{"file":"faces/othello-emilia.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Shakespeare's Globe, London, 2018"}},{"name":"Roderigo","who":"A rich, foolish Venetian who wants Desdemona and is used and cheated by Iago.","group":"Iago's pawns","tag":"A rich, foolish Venetian","wants":"Desdemona.","end":"Iago kills him.","pos":[120,505],"trait":"Gullible and lovesick","check":{"like":["foolish","fool","stupid","naive","rich","desperate","weak","idiot","dumb","jealous","gullible","lovesick"],"want":["desdemona","love","marry","wife","win"]},"face":{"file":"faces/othello-roderigo.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Shakespeare's Globe, London, 2018"}},{"name":"Brabantio","who":"A Venetian senator, Desdemona's father, who accuses Othello of winning her by witchcraft.","group":"Venice","tag":"Desdemona's father","wants":"His daughter back.","end":"He dies of grief (we hear at the end).","pos":[820,110],"trait":"Proud and outraged","check":{"like":["angry","racist","protective","controlling","stubborn","furious","upset","powerful","important","strict","proud","outraged"],"want":["desdemona","daughter","back","home","revenge","justice","punish"]},"face":{"file":"faces/othello-brabantio.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Othello, film, 1995"}},{"name":"Bianca","who":"A courtesan in Cyprus who is in love with Cassio.","group":"Iago's pawns","tag":"Cassio's lover in Cyprus","wants":"Cassio's love.","end":"Iago tries to blame her when Cassio is wounded.","pos":[90,110],"trait":"Devoted and jealous","check":{"like":["loving","love","passion","insecure","emotional","loyal","possess","suspicious","jealous","devoted"],"want":["cassio","love","marry","attention","faithful"]},"face":{"file":"faces/othello-bianca.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Orson Welles's Othello, film, 1952"}},{"name":"Lodovico","who":"A Venetian nobleman, Brabantio's kinsman, who brings orders from Venice and takes charge at the end.","group":"Venice","tag":"Brabantio's kinsman","wants":"To carry out Venice's orders.","end":"He takes charge at the end.","pos":[880,330],"trait":"Calm and dutiful","check":{"like":["loyal","fair","sensible","noble","respectable","honest","steady","official","proper","polite","shocked","calm","dutiful"],"want":["order","venice","duty","letter","justice","punish","recall","command","message","charge","control"]},"face":{"file":"faces/othello-lodovico.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Othello, film, 1995"}},{"name":"The Duke of Venice","who":"Head of the Venetian state, who hears Brabantio's complaint and sends Othello to defend Cyprus.","group":"Venice","tag":"The ruler of Venice","wants":"Othello to defend Cyprus.","end":"He accepts the marriage.","pos":[520,70],"trait":"Practical and fair","check":{"like":["wise","sensible","reasonable","calm","just","leader","powerful","busy","respect","logical","practical","fair"],"want":["cyprus","defend","war","turk","fight","army","protect","safe","battle"]},"face":{"file":"faces/othello-duke.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Othello, film, 1995"}}],"moments":[{"id":"othello-1","title":"Iago's hatred and the night alarm","where":"Act 1, Scene 1","when":"opening","what":"On a Venetian street at night, Iago tells Roderigo that he hates Othello for promoting Cassio over him. The two wake Brabantio with crude, racist shouts to tell him that his daughter Desdemona has gone off with Othello.","why":"It reveals Iago's hidden hatred and two-faced nature, and the racism Othello faces in Venice, before Othello even appears.","modes":["theme","cc","gvv"],"quote":"I am not what I am.","sure":true,"tell":["Venice, at night. Iago is furious: Othello has promoted Cassio over him.","So he and Roderigo wake Desdemona's father, Brabantio, shouting crude, racist images into the dark: your daughter has run off with Othello.","In the very first scene, Iago tells us exactly what he is. Or rather, what he isn't."],"chain":{"happens":"Passed over for Cassio, Iago wakes Brabantio with crude, racist shouts.","shows":"Iago's hidden hatred, and the racism Othello faces in Venice.","leads":"Brabantio accuses Othello of witchcraft."}},{"id":"othello-2","title":"Before the Senate","where":"Act 1, Scene 3","when":"opening","what":"Brabantio accuses Othello of winning Desdemona by witchcraft, but before the Duke and senators Othello calmly explains that she fell in love with him through the stories of his life, and Desdemona declares that her duty now lies with her husband. The Duke, who needs Othello to defend Cyprus against the Turks, accepts the marriage, while Brabantio warns Othello that she deceived her father and may deceive him.","why":"Othello is at the height of his dignity and public respect, and Brabantio's warning plants a seed that Iago will later use.","modes":["theme","cc","gvv"],"quote":"She loved me for the dangers I had passed, / And I loved her that she did pity them.","sure":true,"tell":["Brabantio drags Othello before the Duke and the senators. The charge: he won Desdemona by witchcraft.","Othello answers calmly. No magic. She fell in love with the stories of his life. And Desdemona backs him: her duty now is to her husband.","Venice needs its general against the Turks, so the Duke accepts the marriage. But Brabantio leaves a warning behind: she deceived her father, and she may deceive you."],"chain":{"happens":"Before the Senate, Othello explains that Desdemona fell in love with his stories.","shows":"Othello is noble, but an outsider who needs Venice's approval.","leads":"The marriage stands, but Brabantio's warning plants doubt."}},{"id":"othello-3","title":"Reunion in Cyprus","where":"Act 2, Scene 1","when":"opening","what":"A storm wrecks the Turkish fleet, and Othello lands safely in Cyprus to a joyful reunion with Desdemona. Watching them, Iago vows in an aside to spoil their harmony.","why":"This is the high point of love and happiness in the play, already threatened by Iago's watching presence.","modes":["theme","gvv"],"quote":"If it were now to die, / 'Twere now to be most happy","sure":true,"tell":["A storm wrecks the Turkish fleet. The war is over before it starts.","Othello lands in Cyprus and finds Desdemona there. It's the happiest moment in the play.","And Iago is watching. In an aside, he promises to wreck it."],"chain":{"happens":"Othello and Desdemona are joyfully reunited in Cyprus, and Iago vows to ruin it.","shows":"Love at its height, with evil watching.","leads":"Iago begins his plot."}},{"id":"othello-4","title":"Cassio's disgrace","where":"Act 2, Scene 3","when":"middle","what":"During a night of celebration, Iago gets Cassio drunk and has Roderigo provoke him into a brawl in which Cassio wounds Montano, the former governor of Cyprus; Othello dismisses Cassio as his lieutenant. Iago then advises Cassio to ask Desdemona to plead for him, and in soliloquy explains how he will use her kindness to destroy them all.","why":"Iago shows he can wreck a man's reputation in one night, while Othello keeps calling him 'honest', and he openly states his plan to trap everyone.","modes":["theme","cc","gvv"],"quote":"So will I turn her virtue into pitch, / And out of her own goodness make the net / That shall enmesh them all.","sure":true,"tell":["A night of celebration. Iago gets Cassio drunk and has Roderigo provoke a brawl, and Cassio wounds Montano, the old governor of Cyprus.","Othello dismisses Cassio as his lieutenant.","Then Iago gives Cassio some friendly advice: ask Desdemona to plead for you. And alone, he tells us the plan. Her goodness will be the net that catches them all."],"chain":{"happens":"Iago gets Cassio drunk, and Othello dismisses him.","shows":"Iago controls people through their weaknesses.","leads":"Cassio asks Desdemona for help: the trap Iago needs."}},{"id":"othello-5","title":"The temptation scene","where":"Act 3, Scene 3","when":"middle","what":"Using hints, pauses and pretended reluctance, Iago persuades Othello that Desdemona is having an affair with Cassio; Othello's peace of mind collapses and he demands 'ocular proof'. By the end of the scene Othello kneels to vow revenge, and he makes Iago his lieutenant.","why":"It is the turning point of the play: within one scene Othello moves from love and trust to a vow of murderous revenge.","modes":["theme","cc","gvv"],"quote":"O, beware, my lord, of jealousy; / It is the green-eyed monster which doth mock / The meat it feeds on","sure":true,"tell":["This is the scene where everything turns. Iago never says Desdemona is unfaithful. He hints. He pauses. He pretends he'd rather not say.","And that's enough. Othello's peace of mind collapses, and he demands proof.","By the end, Othello kneels to swear revenge, and he makes Iago his lieutenant."],"chain":{"happens":"Iago hints that Desdemona is unfaithful, and Othello demands proof.","shows":"How easily jealousy is planted in an outsider's insecurity.","leads":"Othello vows revenge and makes Iago his lieutenant."}},{"id":"othello-6","title":"The handkerchief","where":"Act 3, Scenes 3–4","when":"middle","what":"When Othello pushes away the handkerchief that was his first gift to Desdemona and it falls unnoticed, Emilia picks it up and gives it to Iago, who plans to leave it in Cassio's lodging. In the next scene Othello demands to see it, and Desdemona, frightened, insists it is not lost, while Emilia, who knows where it went, says nothing.","why":"A small object becomes false 'proof', and Emilia's silence allows the lie to grow.","modes":["theme","cc"],"quote":"I know not, madam.","sure":true,"tell":["A tiny thing. Othello pushes away a handkerchief, his first gift to Desdemona, and it falls.","Emilia picks it up and gives it to her husband, Iago, who plans to leave it in Cassio's lodging.","When Othello demands to see it, Desdemona, frightened, insists it isn't lost. Emilia knows exactly where it is, and says nothing."],"chain":{"happens":"The handkerchief falls, and Emilia gives it to Iago.","shows":"A small object becomes 'proof', and Emilia stays silent.","leads":"Iago plants it in Cassio's lodging."}},{"id":"othello-7","title":"The public blow","where":"Act 4, Scene 1","when":"middle","what":"Iago drives Othello into a fit, then has him hide and watch Cassio laughing about Bianca, which Othello believes is about Desdemona. When Lodovico arrives from Venice with orders recalling Othello and putting Cassio in charge of Cyprus, Othello strikes Desdemona in front of him.","why":"Othello's private jealousy breaks out as public violence, and the shocked visitor from Venice shows how far the 'noble Moor' has fallen.","modes":["theme","cc","gvv"],"quote":"Is this the noble Moor whom our full senate / Call all in all sufficient?","sure":true,"tell":["Iago drives Othello into a fit, then has him hide and watch Cassio laughing. Cassio is joking about Bianca. Othello thinks it's about Desdemona.","Then Lodovico arrives from Venice with orders: Othello is recalled, and Cassio is to govern Cyprus.","And in front of him, Othello strikes Desdemona. Venice watches its noble general fall apart."],"chain":{"happens":"Othello strikes Desdemona in front of Lodovico.","shows":"The noble general has fallen apart, in public.","leads":"Venice sees how Othello has changed, and Desdemona is humiliated."}},{"id":"othello-8","title":"'That cunning whore of Venice'","where":"Act 4, Scene 2","when":"middle","what":"Othello questions Emilia, who swears that Desdemona is faithful, then treats his wife as a prostitute and Emilia as a brothel-keeper. Afterwards Emilia rages that some 'villain' must have slandered Desdemona, not realising it is her own husband, and Desdemona kneels to Iago to ask how she can win Othello back.","why":"Desdemona is condemned without a fair hearing, and Emilia comes close to the truth while dramatic irony shows the audience the real villain standing beside her.","modes":["theme","cc","gvv"],"quote":"I took you for that cunning whore of Venice / That married with Othello.","sure":true,"tell":["Othello questions Emilia. She swears Desdemona is faithful. He doesn't listen.","He treats his wife as a prostitute, and Emilia as the woman who keeps the brothel.","Afterwards Emilia rages that some villain has slandered Desdemona, not knowing it's her own husband. And Desdemona kneels to Iago, of all people, to ask how she can win Othello back."],"chain":{"happens":"Othello treats Desdemona as a whore, and she kneels to Iago for help.","shows":"Women are judged by men's suspicions; Desdemona is innocent.","leads":"Emilia suspects a villain: the first crack in Iago's plot."}},{"id":"othello-9","title":"The willow scene","where":"Act 4, Scene 3","when":"middle","what":"Preparing for bed as Othello has ordered, Desdemona remembers her mother's maid Barbary, who was abandoned by her lover, and sings her sad 'willow' song. She asks Emilia whether women really betray their husbands, and Emilia replies that when wives go wrong it is their husbands' fault.","why":"This quiet, intimate scene exposes women's powerlessness in marriage and gives Emilia a voice that points ahead to her final defiance.","modes":["theme","cc","gvv"],"quote":"Let husbands know / Their wives have sense like them","sure":true,"tell":["Night. Othello has ordered Desdemona to bed.","She remembers her mother's maid, Barbary, abandoned by the man she loved, and sings Barbary's sad song: the willow song.","Do women really betray their husbands, she asks? Emilia's answer: when wives go wrong, it's their husbands' fault."],"chain":{"happens":"Desdemona sings the willow song, and Emilia blames husbands when wives go wrong.","shows":"A foreboding of death, and a sharp view of how men treat women.","leads":"The night of the murder."}},{"id":"othello-10","title":"The murder of Desdemona","where":"Act 5, Scene 2","when":"climax","what":"Othello enters the bedroom where Desdemona sleeps, convinced he is carrying out justice rather than revenge; ignoring her pleas to be banished or allowed to live one more night, he smothers her. Reviving briefly, she tells Emilia that nobody but herself is to blame.","why":"Othello dresses up murder as justice and sacrifice, and Desdemona's last words show her loyalty even in death.","modes":["theme","cc","gvv"],"quote":"Put out the light, and then put out the light","sure":true,"tell":["Othello comes into the bedroom where Desdemona sleeps. He's convinced this is justice, not revenge.","She begs to be banished. Then to live one more night. He smothers her.","She revives for a moment, just long enough to protect him. Nobody did this, she says. I did it myself."],"chain":{"happens":"Othello smothers Desdemona, and with her last words she protects him.","shows":"Jealousy destroys love; Desdemona is loyal to the end.","leads":"Emilia arrives, and the truth begins to come out."}},{"id":"othello-11","title":"Emilia speaks out","where":"Act 5, Scene 2","when":"climax","what":"Learning that it was Iago who accused Desdemona, Emilia defies Othello's sword and her husband's orders to be silent and go home, and reveals that she found the handkerchief and gave it to Iago. Iago stabs her and flees, and she dies asking to be laid beside her mistress.","why":"Emilia's courage breaks Iago's control, but the truth comes too late and costs her life.","modes":["theme","cc","gvv"],"quote":"'Tis proper I obey him, but not now.","sure":true,"tell":["Emilia learns it was Iago who accused Desdemona. And she will not be quiet.","Othello has a sword. Iago orders her home. She speaks anyway: she found the handkerchief, and she gave it to Iago.","Iago stabs her and runs. She dies asking to be laid beside her mistress."],"chain":{"happens":"Emilia reveals the truth about the handkerchief, and Iago kills her.","shows":"Courage and truth from the least powerful person on stage.","leads":"Iago is exposed."}},{"id":"othello-12","title":"Othello's last speech","where":"Act 5, Scene 2","when":"ending","what":"The captured Iago refuses to explain himself, and Lodovico strips Othello of his command and makes Cassio ruler of Cyprus. Othello asks to be remembered as 'one that loved not wisely but too well', stabs himself and dies on a kiss beside Desdemona, and Lodovico leaves Iago's punishment, including torture, to Cassio.","why":"Venice restores order, but the loss is total, and Iago's silence leaves his evil unexplained.","modes":["theme","cc","gvv"],"quote":"Speak of me as I am; nothing extenuate, / Nor set down aught in malice","sure":true,"tell":["Iago is caught, and refuses to explain himself.","Lodovico strips Othello of his command and gives Cyprus to Cassio. Othello asks to be remembered as one who loved not wisely but too well.","Then he stabs himself and dies on a kiss beside Desdemona. Iago's punishment, torture included, is left to Cassio."],"chain":{"happens":"Othello asks to be remembered as one who loved too well, and kills himself.","shows":"A tragic fall, with a last glimpse of his old nobility.","leads":"Cassio rules Cyprus, and Iago is left to be punished."}}],"modes":{"theme":{"themes":[{"name":"Power and control","points":["Iago has no high rank, yet he becomes the most powerful figure in the play by controlling what others believe: in the temptation scene he works through hints, pauses and pretended reluctance until Othello demands 'ocular proof' [othello-5].","At the start Othello's power rests on calm self-control: accused of witchcraft before the Senate, he answers with quiet dignity and wins the Duke's support [othello-2].","As Iago's grip tightens, Othello loses control of himself, falling into a fit and then striking Desdemona in front of Lodovico, who asks, 'Is this the noble Moor...?' [othello-7].","Final authority belongs to the Venetian state, which recalls Othello by letter [othello-7] and at the end strips him of his command, so that 'Cassio rules in Cyprus' [othello-12]."]},{"name":"Freedom and entrapment","points":["Desdemona shows unusual freedom in choosing her own husband and defending that choice before the Senate [othello-2], yet by the willow scene she is isolated and obedient, trapped in a marriage with no one to turn to [othello-9].","Iago describes his plot as a trap, planning to make out of Desdemona's goodness 'the net / That shall enmesh them all' [othello-4].","Othello becomes a prisoner of jealousy: once Iago's suggestions take hold he cannot go back to trusting Desdemona, and he bids 'Farewell the tranquil mind!' [othello-5].","Cyprus, a military outpost far from Venice, cuts the characters off from home and from the Senate, leaving Iago free to work once the Turkish threat has passed [othello-3]."]},{"name":"Courage and silence","points":["Emilia's early silence makes her complicit: she gives the handkerchief to Iago and, when Desdemona wonders where it could be, answers 'I know not, madam' [othello-6]; even when she swears to Othello that Desdemona is faithful, she says nothing about it [othello-8].","Her final courage is complete: ignoring Othello's sword and her husband's order to hold her peace, she says it is proper to obey him 'but not now', and she dies for telling the truth [othello-11].","Desdemona speaks boldly before the Senate [othello-2], but once accused she can only protest her innocence and submit, and her dying words, 'Nobody; I myself', shield the husband who has killed her [othello-10].","Iago's last act of power is silence: 'From this time forth I never will speak word' [othello-12]."]}]},"cc":{"aspects":[{"name":"Power and authority","points":["Venice is ruled by the Duke and Senate, who act as judges in Brabantio's complaint and, needing Othello against the Turks, accept his marriage [othello-2].","Military rank shapes relationships: Iago's resentment at being passed over for lieutenant drives the plot [othello-1], and Othello strips Cassio of his post at once after the brawl [othello-4].","Even a great general's power depends on Venice: Lodovico's letter recalls Othello [othello-7], and at the end his power and command are taken from him [othello-12]."]},{"name":"Class, money and status","points":["Iago resents that Cassio, a 'great arithmetician' who has never led men in battle, has been promoted above him, and complains that promotion goes by favour rather than by long service [othello-1].","Reputation is a man's most valuable possession: after his disgrace Cassio cries 'Reputation, reputation, reputation!' and says he has lost 'the immortal part' of himself [othello-4].","Money cannot buy sense: Roderigo, rich but foolish, is told by Iago to 'Put money in thy purse' and keeps paying him in the hope of winning Desdemona [othello-2]."]},{"name":"Gender roles and marriage","points":["Women are treated as property: Iago wakes Brabantio by shouting 'thieves!' and telling him to look to his house, his daughter and his bags [othello-1].","Desdemona challenges the expectation of daughterly obedience, telling the Senate she sees 'a divided duty' and must put her husband before her father [othello-2].","Marriage gives wives no protection: Othello treats Desdemona as 'that cunning whore of Venice' [othello-8], and Emilia argues that husbands' unkindness causes wives' faults, insisting 'Let husbands know / Their wives have sense like them' [othello-9].","Both wives die at their husbands' hands: Othello smothers Desdemona [othello-10] and Iago stabs Emilia for refusing to obey him [othello-11]."]},{"name":"Religion and the Church","points":["Venice is a Christian state at war with the Muslim Ottoman Turks, and Othello, a baptised Christian, stops the brawl by asking 'Are we turned Turks...?' [othello-4].","Iago uses religious language for evil, calling his plan 'Divinity of hell' and boasting that devils tempt people 'with heavenly shows' [othello-4].","Othello treats the murder as a religious sacrifice, asking Desdemona if she has prayed because he would not 'kill thy soul' [othello-10].","No church or priest appears in the play; religion is a language of heaven and hell, as when Emilia calls Desdemona 'the more angel' and Othello 'the blacker devil' [othello-11]."]},{"name":"Family and community","points":["A daughter's duty passes from father to husband: Desdemona tells Brabantio that she owes him her life and education, but that her husband now comes first [othello-2].","The broken family is never mended: Brabantio disowns Desdemona, and in the final scene we learn that grief over her marriage has killed him [othello-12].","On Cyprus the community is a military garrison, and Iago uses its night of celebration to get Cassio drunk and disgraced [othello-4].","Far from home, Desdemona's only real companion is Emilia, and their late-night conversation is the play's one scene of female friendship [othello-9]."]},{"name":"Law, institutions and justice","points":["Venice offers a fair hearing: the Duke lets Othello and Desdemona speak before dismissing Brabantio's charge of witchcraft [othello-2].","Othello abandons fair justice: acting on false evidence as judge and executioner, he insists 'It is the cause' and ignores Desdemona's plea, 'Kill me tomorrow: let me live tonight!' [othello-10].","Justice returns only when it is too late: Lodovico removes Othello from command, makes Cassio governor and leaves Iago's punishment, including torture, to him [othello-12]."]},{"name":"Race and the outsider","points":["Othello is a Black African in white Venice, and racist language greets him from the first scene, when Iago calls him 'an old black ram' [othello-1].","Venice values Othello as a soldier but sees his marriage as unnatural: Brabantio claims only witchcraft could explain it, and even the Duke's praise, 'far more fair than black', judges him by his colour [othello-2].","Iago turns Othello's outsider status into self-doubt: alone, Othello wonders whether Desdemona has strayed 'for I am black' and lacks the polished manners of Venetian gentlemen [othello-5].","In his final speech Othello sees himself as both Venice's loyal servant and its enemy, comparing himself to a 'turban'd Turk' he once killed for beating a Venetian and slandering the state [othello-12]."]}]},"gvv":{"opening":"The play opens in darkness, at night, with Iago's hatred and racist insults, but Othello's calm dignity and his love for Desdemona, defended before the Senate, suggest that goodness may win out.","ending":"By the end Desdemona, Emilia, Roderigo and Othello are dead and Iago refuses to explain himself; Venice restores order, but the waste of so much love and goodness leaves a bleak outlook.","outlook":"bleak","points":["Light and dark shape the play: the joy of the Cyprus reunion, when Othello says he could die 'most happy' [othello-3], is destroyed in the final scene, where he puts out the light before putting out Desdemona's life [othello-10].","Evil is almost unexplained: Iago's motives shift from scene to scene, and when he is finally asked why, he refuses to speak [othello-12], leaving the disturbing sense that cruelty needs no good reason.","Dramatic irony makes the audience feel helpless: Iago reveals his plan to us in soliloquy while Othello keeps calling him 'honest Iago' [othello-4], and later Emilia curses an unknown 'villain' to her own husband's face [othello-8].","Goodness is real but cannot save itself: Desdemona stays loyal to the end [othello-10], and Emilia dies defending her mistress's honour [othello-11].","The ending says society can restore order but cannot undo harm: Venice punishes Iago and appoints Cassio, but Lodovico makes Iago look on 'the tragic loading of this bed' [othello-12].","The play leaves us with pity rather than hope, as Othello asks to be remembered as 'one that loved not wisely but too well' and then kills himself [othello-12]."]}},"links":[["Othello","Desdemona","married in secret"],["Iago","Emilia","married"],["Emilia","Desdemona","her attendant"],["Iago","Othello","his ensign; hates him"],["Othello","Cassio","made him lieutenant"],["Iago","Cassio","frames him"],["Iago","Roderigo","uses and cheats him"],["Cassio","Bianca","his lover"],["Brabantio","Desdemona","her father"],["The Duke of Venice","Othello","sends him to Cyprus"],["Lodovico","Brabantio","his kinsman"],["Lodovico","Othello","brings Venice's orders"]]},"shawshank":{"id":"shawshank","title":"The Shawshank Redemption","author":"Frank Darabont","kind":"film","made":"1994","setting":"Shawshank, a fictional state prison in Maine, USA, from 1947 to 1966, with a final journey to the Pacific coast of Mexico in 1967.","gist":"Andy Dufresne, a banker wrongly convicted of murdering his wife and her lover, is sent to Shawshank prison, where he becomes friends with Red, a long-serving prisoner who narrates the film. Over nearly twenty years Andy survives brutality and a corrupt, Bible-quoting warden, keeps hope alive, and finally escapes and exposes the warden; Red, released on parole, follows him to Mexico. Frank Darabont wrote and directed the film from Stephen King's novella 'Rita Hayworth and Shawshank Redemption'.","people":[{"name":"Andy Dufresne","who":"A quiet, educated banker sentenced to two life sentences for murdering his wife and her lover, a crime he did not commit.","group":"Andy and Red","tag":"The banker, innocent","wants":"Freedom, and to keep hope alive.","end":"He escapes to Zihuatanejo.","face":{"file":"shawshank-f-wall.jpg","x":0.44,"y":0.21,"zoom":6,"ar":0.5625,"from":"The Shawshank Redemption, film, 1994"},"pos":[370,300],"trait":"Quiet, clever and patient","check":{"like":["calm","smart","intelligent","determined","hopeful","hope","strong","reserved","resilient","educated","mysterious","innocent","brave","stubborn","kind","quiet","clever","patient"],"want":["free","freedom","escape","out","hope","zihuatanejo","mexico","beach","justice","innocen","library","live"]}},{"name":"Ellis 'Red' Redding","who":"A long-serving prisoner who can smuggle in almost anything; Andy's closest friend and the film's narrator.","group":"Andy and Red","tag":"The narrator, who gets things","wants":"Parole; later, to see Andy again.","end":"He breaks parole and joins Andy on the beach.","face":{"file":"shawshank-f-wall.jpg","x":0.72,"y":0.13,"zoom":7,"ar":0.5625,"from":"The Shawshank Redemption, film, 1994"},"pos":[670,300],"trait":"Wry and worn down, then hopeful","check":{"like":["funny","sarcastic","tired","cynical","realistic","hopeless","wise","loyal","friend","experienced","institution","honest","kind","practical"],"want":["parole","free","out","andy","release","hope","friend","mexico","zihuatanejo","beach"]}},{"name":"Warden Samuel Norton","who":"The Bible-quoting warden who secretly grows rich through corruption and uses Andy to hide his money.","group":"In charge","tag":"The warden","wants":"Money and control.","end":"Exposed, he shoots himself.","face":{"file":"shawshank-f-hole.jpg","x":0.54,"y":0.32,"zoom":5,"ar":0.5625,"from":"The Shawshank Redemption, film, 1994"},"pos":[300,80],"trait":"Holy on the outside, corrupt inside","check":{"like":["hypocrit","religious","bible","greedy","evil","cruel","fake","corrupt","liar","power","control","ruthless","sinister","cold","holy"],"want":["money","cash","rich","power","control","order","wealth","profit"]}},{"name":"Captain Byron Hadley","who":"The brutal captain of the guards, who rules the prisoners through violence.","group":"In charge","tag":"Captain of the guards","wants":"Order, through fear.","end":"Arrested.","pos":[90,230],"trait":"Brutal and violent","check":{"like":["cruel","aggressive","angry","harsh","evil","mean","bully","scary","vicious","tough","rough","sadist","brutal","violent"],"want":["order","control","power","fear","discipline","obey","money","respect","rules"]},"face":{"file":"faces/shawshank-hadley.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"The Shawshank Redemption, film, 1994"}},{"name":"Brooks Hatlen","who":"The elderly prison librarian, inside for about fifty years, who cannot cope when he is released.","group":"Red's crew","tag":"The old librarian","wants":"To stay inside, where he belongs.","end":"He hangs himself after his release.","pos":[850,130],"trait":"Gentle and lost outside the walls","check":{"like":["kind","old","quiet","sad","lonely","scared","afraid","institution","frail","nice","harmless","sweet","gentle","confused","lost"],"want":["stay","inside","prison","shawshank","home","belong","safe","purpose","useful","back"]},"face":{"file":"faces/shawshank-brooks.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"The Shawshank Redemption, film, 1994"}},{"name":"Tommy Williams","who":"A young thief who arrives in 1965; Andy helps him study, and Tommy turns out to know who really committed Andy's crime.","group":"Red's crew","tag":"The young thief","wants":"His exam, and a way out.","end":"Shot dead on Norton's orders.","pos":[600,520],"trait":"Cocky but eager to learn","check":{"like":["young","confident","cheeky","energetic","funny","honest","keen","friendly","loud","immature","cocky","eager"],"want":["exam","study","learn","diploma","educat","pass","school","out","free","better","family","wife","daughter","future","change"]},"face":{"file":"faces/shawshank-tommy.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"The Shawshank Redemption, film, 1994"}},{"name":"Heywood","who":"One of Red's group of friends, who taunts the new arrivals on Andy's first night.","group":"Red's crew","tag":"One of Red's friends","wants":"A laugh at the new arrivals.","end":"Still inside at the end.","pos":[880,450],"trait":"Loud and jokey","check":{"like":["funny","joke","cheeky","rude","mean","laugh","friend","loyal","silly","loud","jokey"],"want":["laugh","fun","joke","bet","win","money","entertain","tease","mock"]},"face":{"file":"faces/shawshank-heywood.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"The Shawshank Redemption, film, 1994"}},{"name":"Bogs Diamond","who":"Leader of 'the Sisters', a gang that repeatedly attacks Andy in his early years in prison.","group":"The Sisters","tag":"The gang leader","wants":"To prey on Andy.","end":"Hadley beats him and he's moved away.","pos":[170,500],"trait":"Violent and predatory","check":{"like":["cruel","aggressive","evil","scary","brutal","dangerous","nasty","bully","animal","monster","abus","attack","violent","predator"],"want":["attack","hurt","abuse","power","control","dominat","victim","hunt","beat","prey"]},"face":{"file":"faces/shawshank-bogs.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"The Shawshank Redemption, film, 1994"}}],"moments":[{"id":"shawshank-1","title":"The crime and the trial","where":"Opening sequence","when":"opening","what":"At night, a drunk Andy sits in his car outside the house where his wife is with her lover, loading a revolver; these images are cut together with his trial, where he insists he threw the gun into a river. He is convicted of both murders and given two life sentences.","why":"The film opens in darkness and injustice, and the cross-cutting between the night and the courtroom leaves the viewer unsure at first whether Andy is guilty.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Night. A man sits in his car, drunk, outside the house where his wife is with her lover. He's loading a revolver.","This is Andy Dufresne, a banker. The film cuts between this night and his trial, where he swears he threw the gun into a river.","The jury doesn't believe him. Two murders. Two life sentences."],"chain":{"happens":"Drunk, with a gun, outside his wife's lover's house; Andy is convicted of their murders.","shows":"Justice can fail, and an innocent man loses everything.","leads":"Andy is sent to Shawshank for life."}},{"id":"shawshank-2","title":"Red's first parole hearing","where":"Early in the film (1947)","when":"opening","what":"Twenty years into a life sentence, Red tells the parole board he is a changed man, and his file is stamped 'REJECTED'. In voiceover he introduces himself as the prisoner who can get things smuggled into Shawshank.","why":"It sets up the parole hearings that measure Red's journey, and introduces the voiceover through which we see the whole story.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Meet Red. Twenty years into a life sentence, telling the parole board he's a changed man.","Rejected.","Red is our narrator, and the man in Shawshank who can get you things, smuggled in from outside."],"chain":{"happens":"After twenty years, Red's parole is rejected.","shows":"The system decides who counts as 'rehabilitated', and hope is rationed.","leads":"Red, our narrator, is still inside when Andy arrives."}},{"id":"shawshank-3","title":"Welcome to Shawshank","where":"Early in the film: Andy's first night","when":"opening","what":"Warden Norton tells the new prisoners that he believes in discipline and the Bible. That night Heywood and other prisoners taunt the new arrivals until one breaks down in tears; Captain Hadley beats him, he dies in the infirmary, and the next morning Andy, who made no sound all night, asks what the dead man's name was.","why":"It shows the cruelty and indifference of the institution, and Andy's quiet humanity in the middle of it.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["New men arrive. Warden Norton tells them he believes in two things: discipline and the Bible.","That night the old prisoners taunt the new ones until one breaks down in tears. Captain Hadley beats him, and he dies in the infirmary.","Andy makes no sound all night. In the morning he asks one question: what was the dead man's name?"],"chain":{"happens":"Norton's welcome, and a new prisoner is beaten to death on the first night.","shows":"Shawshank runs on cruelty and fear.","leads":"Andy stays silent and survives."}},{"id":"shawshank-4","title":"Beer on the roof","where":"First third of the film","when":"middle","what":"While tarring the roof of the licence-plate factory, Andy overhears Captain Hadley complaining about tax on an inheritance and dares to offer advice; Hadley nearly throws him off the roof, but Andy explains how to keep the money legally tax-free, asking only for three beers each for his fellow workers. The men drink in the sunshine while Andy sits apart, smiling, and Red's voiceover says they felt like free men.","why":"Andy discovers that his knowledge is a kind of power, and the prisoners briefly experience ordinary freedom.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Andy is tarring a roof when he hears Captain Hadley complaining about tax on an inheritance. So he offers advice.","Hadley nearly throws him off the roof. But Andy explains how to keep the money legally, and asks for one thing in return: three beers each for his workmates.","The men drink in the sun. Andy sits apart, smiling. For a moment, they feel like free men."],"chain":{"happens":"Andy's tax advice wins beers for the men tarring the roof.","shows":"Andy's brains give him a little power, and the men a little dignity.","leads":"Andy becomes useful to the guards."}},{"id":"shawshank-5","title":"Brooks is released","where":"Around the middle of the film","when":"middle","what":"When the elderly librarian Brooks Hatlen learns he is to be paroled after fifty years, he holds a knife to Heywood's throat in the hope of being kept inside, and Red explains that Brooks is 'institutionalized'. Outside, Brooks cannot cope with the changed world, and he hangs himself in his halfway-house room after carving 'Brooks was here' into a wooden beam.","why":"It shows that prison can destroy a man's ability to live in freedom, a fate Red himself later fears.","modes":["theme","cc","gvv"],"quote":"Brooks Hatlen was here","sure":true,"tell":["Brooks Hatlen, the old librarian, is getting parole after fifty years. And he's terrified.","He holds a knife to Heywood's throat, hoping they'll keep him inside. Red explains: Brooks is 'institutionalized'.","Outside, the world has moved on without him. He can't cope. In his halfway-house room he carves his name into a beam, and hangs himself."],"chain":{"happens":"Brooks is paroled after fifty years, and hangs himself outside.","shows":"Institutionalisation: prison can make freedom unbearable.","leads":"Red fears the same will happen to him."}},{"id":"shawshank-6","title":"Mozart over the loudspeakers","where":"Around the middle of the film","when":"middle","what":"Andy's years of letters finally win a small grant and boxes of donated books and records for the library; he locks himself in the office and plays a duet from Mozart's 'The Marriage of Figaro' over the loudspeakers, and the prisoners stand still in the yard to listen. He is given two weeks in solitary, and afterwards tells the men that music is something inside that cannot be taken from them, while Red warns that hope is a dangerous thing.","why":"It is the film's clearest image of inner freedom, and it begins the argument about hope that runs to the final scene.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Years of letters, and finally: a small grant, and boxes of donated books and records for the library.","Andy locks himself in the office and plays Mozart over the loudspeakers. The whole yard stops to listen.","It costs him two weeks in solitary. Worth it, he says: music is something inside that they can't take from you. Red isn't so sure. Hope, he warns, is a dangerous thing."],"chain":{"happens":"Andy plays Mozart over the loudspeakers to the whole prison.","shows":"Beauty and hope can't be locked up.","leads":"Solitary for Andy, and Red's warning that hope is dangerous."}},{"id":"shawshank-7","title":"Tommy's evidence","where":"Final third of the film (1965)","when":"climax","what":"Tommy, a young prisoner Andy is helping to study, reveals that a former cellmate boasted of killing a golf pro and his lover, the crime Andy was convicted of. Warden Norton, who relies on Andy to hide his illegal profits, refuses to help and throws Andy into solitary when he protests, then has Hadley shoot Tommy dead at night and threatens to take away Andy's protection and destroy the library if he stops working for him.","why":"The institution destroys justice to protect corrupt power, pushing Andy to the edge.","modes":["theme","cc","gvv"],"quote":"How can you be so obtuse?","sure":true,"tell":["Tommy, a young prisoner Andy is helping to study, tells a story: an old cellmate once boasted of killing a golf pro and his lover.","That's Andy's crime. Someone else did it.","But Andy is too useful to Warden Norton, who needs him to hide his illegal money. Norton throws Andy into solitary, has Hadley shoot Tommy dead, and threatens to destroy everything Andy has built."],"chain":{"happens":"Tommy could prove Andy innocent, and Norton has him shot.","shows":"Corrupt power protects itself.","leads":"Andy loses his last legal hope."}},{"id":"shawshank-8","title":"'Get busy living'","where":"Final third of the film, after Andy leaves solitary","when":"climax","what":"Andy tells Red that he was a distant husband who drove his wife away, though he did not kill her, describes his dream of running a small hotel in Zihuatanejo, Mexico, and makes Red promise that if he is ever freed he will look under a rock by a stone wall in a hayfield near Buxton. When Red hears that Andy has asked for a length of rope, he fears Andy is planning to kill himself.","why":"It frames the film's central choice between hope and despair.","modes":["theme","cc","gvv"],"quote":"Get busy living, or get busy dying.","sure":true,"tell":["Out of solitary, Andy sits with Red against the wall. He admits he was a distant husband who drove his wife away. But he didn't kill her.","He talks about a dream: a little hotel in Zihuatanejo, Mexico. And he makes Red promise to look under a rock by a stone wall in a hayfield near Buxton.","Then Red hears that Andy has asked for a length of rope, and fears the worst."],"chain":{"happens":"Andy tells Red to 'get busy living', and about the rock near Buxton.","shows":"Choosing hope over despair.","leads":"That night, Andy escapes."}},{"id":"shawshank-9","title":"The empty cell","where":"Final third of the film (1966)","when":"climax","what":"At the morning count Andy's cell is empty; in a rage the warden throws a stone at the poster on the wall, and it tears straight through, revealing a tunnel. Red's voiceover and a flashback show that Andy dug through the wall in less than twenty years with his small rock hammer and, during a thunderstorm, crawled through five hundred yards of sewer pipe to freedom, raising his arms in the rain.","why":"The film's great reversal turns Andy's years of patience into an act of hidden defiance, and gives the film its central image of freedom.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Morning count. Andy's cell is empty.","The warden throws a stone at the poster on the wall, and it goes straight through. Behind it: a tunnel.","Red tells us how. Less than twenty years with a little rock hammer. Then, in a thunderstorm, five hundred yards of sewer pipe. And Andy, arms raised in the rain, free."],"chain":{"happens":"Andy's cell is empty, and the poster hides a tunnel.","shows":"Patience and hope beat the system.","leads":"Andy is free."}},{"id":"shawshank-10","title":"The warden's fall","where":"Final third of the film (1966)","when":"ending","what":"Posing as 'Randall Stephens', the false identity he had invented to hide Norton's money, Andy withdraws it from several banks and posts the warden's account book and evidence of his crimes to a newspaper. As police arrive, Hadley is arrested, and Norton opens his safe, hidden behind the embroidered words 'His judgment cometh and that right early', to find Andy's Bible with the rock hammer's hiding place cut into its pages, before shooting himself.","why":"Corrupt power collapses, and justice arrives through Andy's cleverness and the press rather than through the courts.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Remember the person Andy invented to hide Norton's money? Andy becomes him, and empties the accounts.","He posts the warden's account book and the proof of his crimes to a newspaper. The police arrive, and Hadley is arrested.","Norton opens his safe and finds Andy's Bible, with the rock hammer's hiding place cut into its pages. Then he shoots himself."],"chain":{"happens":"Andy exposes Norton's crimes, and Norton shoots himself.","shows":"Justice catches up with the corrupt at last.","leads":"Hadley is arrested, and Norton's power is gone."}},{"id":"shawshank-11","title":"Red's last hearing","where":"Near the end of the film (1967)","when":"ending","what":"After forty years, Red tells the parole board that 'rehabilitated' is just a made-up word, that he regrets the foolish young man who committed his crime, and that he no longer cares what they decide; this time he is released. Outside, he is given Brooks's old room and a job bagging groceries, as Brooks had, asks his manager's permission to go to the toilet, and admits he thinks about breaking parole to be sent back.","why":"Red's honesty finally frees him, but life outside shows how deeply the institution has shaped him.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Forty years in, Red faces the board again. And this time he stops performing.","'Rehabilitated' is just a made-up word, he says. He regrets the foolish young man he was, and he doesn't care what they decide. Released.","Outside, he gets Brooks's old room and a job bagging groceries, as Brooks had. He asks permission to go to the toilet. And he thinks about breaking parole, just to be sent back."],"chain":{"happens":"Red is released, and struggles outside just as Brooks did.","shows":"Institutionalisation again: freedom is frightening.","leads":"Red chooses Andy's path instead of Brooks's."}},{"id":"shawshank-12","title":"Buxton and Zihuatanejo","where":"Final scenes","when":"ending","what":"Keeping his promise, Red finds the box Andy hid under the rock near Buxton, with money and a letter inviting him to Mexico; he carves 'So was Red' beside Brooks's words, breaks parole and takes a bus south. In the final scene he walks along a sunlit beach at Zihuatanejo to Andy, who is working on an old boat, and the camera pulls back over the blue Pacific.","why":"The ending rewards hope and friendship, and shows Red choosing life instead of becoming another Brooks.","modes":["theme","cc","gvv"],"quote":"Hope is a good thing, maybe the best of things, and no good thing ever dies.","sure":true,"tell":["Red keeps his promise. Under the rock near Buxton he finds a box: money, and a letter inviting him to Mexico.","He carves 'So was Red' beside Brooks's words, breaks parole, and takes a bus south.","The last scene: a sunlit beach, Andy working on an old boat, and Red walking towards him. The camera pulls back over the blue Pacific."],"chain":{"happens":"Red finds Andy's letter and joins him in Zihuatanejo.","shows":"Hope and friendship win.","leads":"The film ends in freedom, by the open sea."}}],"modes":{"theme":{"themes":[{"name":"Power and control","points":["Official power at Shawshank is brutal: Warden Norton greets new prisoners with talk of discipline and the Bible, and that night Captain Hadley beats a frightened prisoner to death, with no one held to account [shawshank-3].","Andy finds a quieter power in knowledge: by offering tax advice, he turns Hadley, who nearly threw him off the roof, into the man who supplies his fellow prisoners with beer [shawshank-4].","The warden will kill to keep control: when Tommy's evidence could free Andy, the man who hides his illegal profits, Norton has Hadley shoot Tommy dead [shawshank-7].","Andy finally turns the warden's own system against him, using the false identity he created to hide Norton's money to take that money himself, and Norton's power collapses [shawshank-10]."]},{"name":"Freedom and entrapment","points":["Prison traps the mind as well as the body: Brooks, 'institutionalized' after fifty years, cannot live in the free world and hangs himself [shawshank-5].","Freedom can be felt even inside the walls: when Andy plays Mozart over the loudspeakers, the prisoners stand still to listen, and Red's voiceover says that for a brief moment every man in Shawshank felt free [shawshank-6].","Andy's escape through five hundred yards of sewer pipe ends in the film's great image of freedom, as he stands with his arms raised in the pouring rain [shawshank-9].","Release is not the same as freedom: on parole, Red still asks permission to go to the toilet [shawshank-11], and he becomes truly free only when he breaks parole to follow Andy [shawshank-12]."]},{"name":"Courage and silence","points":["Andy shows quiet courage from his first night: he makes no sound while another man breaks down, and the next morning he asks the dead prisoner's name while the others shrug off the killing [shawshank-3].","Andy risks his life to speak up to Hadley on the roof [shawshank-4], and accepts solitary confinement rather than switch off the Mozart [shawshank-6].","Speaking the truth is punished: Andy is thrown into solitary for challenging the warden, and Tommy is shot after agreeing to testify [shawshank-7].","Red's courage is to stop pretending: at his final hearing he refuses to say what the board wants to hear [shawshank-11], and he breaks parole rather than give in to despair [shawshank-12]."]}]},"cc":{"aspects":[{"name":"Power and authority","points":["The warden's authority is total and claims the backing of religion: Norton tells new arrivals that he believes in discipline and the Bible [shawshank-3].","The guards' violence goes unchecked: Hadley beats a prisoner to death on Andy's first night [shawshank-3] and later shoots Tommy on the warden's orders [shawshank-7].","Authority can be bargained with by a prisoner who has something it wants: Andy's financial skill wins beer for his fellow workers [shawshank-4].","This corrupt authority is brought down from outside: once Andy's evidence reaches a newspaper, Hadley is arrested and Norton shoots himself [shawshank-10]."]},{"name":"Class, money and status","points":["Andy's education as a banker gives him value even in prison, where his tax advice to Hadley wins privileges for his friends [shawshank-4].","Prison has its own economy and status: Red is respected as the man who can get things [shawshank-2].","Money corrupts the institution: Norton relies on Andy to hide his illegal profits, so he will not let Tommy's evidence set Andy free [shawshank-7].","Status depends on the institution: inside, Brooks is the respected librarian, but outside he is an old man bagging groceries in a world that has no use for him [shawshank-5]."]},{"name":"Gender roles and marriage","points":["Shawshank is an almost entirely male world where toughness is expected: a new prisoner who weeps on his first night is mocked and then beaten to death [shawshank-3].","Marriage appears only as failure: the film opens with the story of Andy's wife's affair and murder [shawshank-1], and Andy later admits he was a distant husband who drove her away [shawshank-8].","Women are present mostly as images and voices: the film-star posters on Andy's wall, the last of which hides his tunnel [shawshank-9], and the two women's voices singing Mozart [shawshank-6]."]},{"name":"Religion and the Church","points":["Religion is used as a tool of control: Norton presents himself as a man of the Bible when he welcomes new prisoners [shawshank-3].","The film exposes this as hypocrisy: the Bible-quoting warden runs a corrupt business and arranges a murder [shawshank-7].","Andy turns the warden's faith against him: Norton's safe, hidden behind the embroidered words 'His judgment cometh and that right early', holds Andy's Bible, with the rock hammer's hiding place cut into its pages [shawshank-10].","The 'redemption' of the title comes through hope and friendship rather than through the Church [shawshank-12]."]},{"name":"Family and community","points":["Prisoners build their own community: Red's group of friends becomes Andy's substitute family, and on the roof he wins them a moment of ordinary life [shawshank-4].","Losing that community can be fatal: Brooks, cut off from the only world he knows, dies alone outside [shawshank-5].","Andy builds community through education, building up the prison library and helping young Tommy to study [shawshank-7].","The film ends with a chosen family, as Red travels to Mexico to be reunited with his friend [shawshank-12]."]},{"name":"Law, institutions and justice","points":["The legal system fails from the start: Andy is convicted of two murders he did not commit and given two life sentences [shawshank-1].","Parole is shown as an empty ritual: Red is rejected when he says what the board wants to hear [shawshank-2] and released only when he speaks honestly and says he does not care [shawshank-11].","The institution blocks justice: when Tommy offers new evidence, the warden destroys it by having the witness killed [shawshank-7].","Justice comes from outside the system, through Andy's escape and the evidence he sends to a newspaper [shawshank-10]."]},{"name":"Race and the outsider","points":["The film says almost nothing directly about race: Red is a Black man and Andy a white former banker, yet their friendship becomes the heart of the film without the film ever making race an issue [shawshank-12].","Andy is an outsider by class and temperament: educated and reserved, he sits apart on the roof, not drinking, while the others enjoy the beer he won for them [shawshank-4].","Long imprisonment turns men into outsiders in the free world: Brooks finds that the world has changed too fast for him [shawshank-5], and Red, given Brooks's old room, fears the same fate [shawshank-11]."]}]},"gvv":{"opening":"The film opens in darkness and injustice: an innocent man is sentenced to life, Red is refused parole, and on Andy's first night a frightened prisoner is beaten to death, suggesting a world without hope.","ending":"It ends in bright sunlight on a Mexican beach as Red and Andy are reunited; the corrupt warden has fallen and hope and friendship have won, though only by escaping a system that never delivered justice.","outlook":"hopeful","points":["Darabont contrasts dark and light visually: the grey, enclosed prison and night scenes such as Tommy's killing [shawshank-7] give way to the open, sunlit blue of the Pacific in the final shot [shawshank-12].","The film admits that hope can be crushed: Brooks hangs himself after his release [shawshank-5], and Tommy is killed for being willing to tell the truth [shawshank-7].","Moments of grace inside the walls, such as the beer on the roof [shawshank-4] and the Mozart broadcast [shawshank-6], suggest that the human spirit cannot be fully imprisoned.","Red's voiceover guides our feelings: we share his slow journey from warning that hope is dangerous [shawshank-6], to repeating Andy's choice to 'get busy living' [shawshank-8], to ending the film with the words 'I hope' [shawshank-12].","The ending suggests that institutions are corrupt but individuals can be good: justice comes not from the courts or the parole board but from Andy's patience and the truth he sends to a newspaper [shawshank-10].","The escape is hidden from the viewer as well as from Red, so its sudden reveal gives us the same shock and delight [shawshank-9]."]}},"links":[["Andy Dufresne","Ellis 'Red' Redding","best friends"],["Ellis 'Red' Redding","Heywood","his crew"],["Ellis 'Red' Redding","Brooks Hatlen","old friends"],["Andy Dufresne","Brooks Hatlen","works in his library"],["Andy Dufresne","Tommy Williams","helps him study"],["Warden Samuel Norton","Tommy Williams","has him shot"],["Warden Samuel Norton","Andy Dufresne","uses him to hide money"],["Captain Byron Hadley","Andy Dufresne","beers for tax advice"],["Warden Samuel Norton","Captain Byron Hadley","his captain"],["Bogs Diamond","Andy Dufresne","attacks him"],["Captain Byron Hadley","Bogs Diamond","beats him"]]},"stlt":{"id":"stlt","title":"Small Things Like These","author":"Claire Keegan","kind":"novel","made":"2021","setting":"New Ross, Co. Wexford, in the weeks before Christmas 1985.","gist":"Bill Furlong, a coal and timber merchant with five daughters, delivers to the town's convent, where the nuns run a laundry as well as the best girls' school. What he sees there, including girls locked up and a young mother whose baby has been taken, forces him to choose between keeping quiet to protect his family and acting on his conscience. Remembering how one woman's kindness saved his own unmarried mother, he brings a girl called Sarah home from the convent on Christmas Eve.","people":[{"name":"Bill Furlong","who":"A hard-working coal and timber merchant, nearly forty, born to an unmarried mother; a quiet, decent man troubled by what he sees.","group":"The Furlongs","tag":"The coal merchant","wants":"To keep his family safe, and to do what's right.","end":"He takes Sarah home, afraid but hopeful.","face":{"file":"stlt-f-home.jpg","x":0.51,"y":0.41,"zoom":4,"ar":0.5625,"from":"Small Things Like These, film, 2024"},"pos":[440,290],"trait":"Quiet, kind and troubled","check":{"like":["caring","decent","good","gentle","thoughtful","worried","anxious","generous","moral","empath","sensitive","hardwork","humble","brave","conscience","kind","quiet","troubled"],"want":["family","safe","protect","right","good","moral","help","sarah","daughters","girls","wife","peace","conscience","truth","justice"]}},{"name":"Eileen Furlong","who":"Bill's practical wife, who wants him to stay out of the convent's business to protect their daughters.","group":"The Furlongs","tag":"Bill's wife","wants":"To protect their girls by keeping out of it.","end":"We don't see how she takes it.","face":{"file":"stlt-f-eileen.jpg","x":0.21,"y":0.55,"zoom":3.4,"ar":0.5625,"from":"Small Things Like These, film, 2024"},"pos":[690,190],"trait":"Practical and cautious","check":{"like":["sensible","careful","realistic","worried","protective","strict","cold","conform","sharp","busy","organised","loyal","practical","cautious"],"want":["girls","daughters","protect","safe","school","out","quiet","family","ignore","business"]}},{"name":"The Furlong daughters","who":"Kathleen, Joan, Sheila, Grace and Loretta; their schooling at St Margaret's depends on the nuns.","group":"The Furlongs","tag":"Their five girls","wants":"Their places at St Margaret's school.","end":"Their places may be at risk.","pos":[880,330],"trait":"Young, bright and busy","check":{"like":["clever","smart","happy","innocent","good","sweet","lively","studious","children","kids","young","bright","busy"],"want":["school","margaret","educat","place","study","learn","christmas"]},"face":{"file":"faces/stlt-daughters.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Small Things Like These, film, 2024"}},{"name":"Sarah Redmond","who":"A young mother held at the convent; Bill finds her locked in the coal shed, her baby taken from her.","group":"The convent","tag":"The girl in the coal shed","wants":"Her baby back, and to get out.","end":"She walks home with Bill, barefoot.","pos":[540,520],"trait":"Frightened and worn out","check":{"like":["scared","afraid","broken","weak","desperate","sad","terrified","traumat","exhaust","tired","vulnerable","helpless","young","timid","frightened"],"want":["baby","child","out","escape","free","home","leave","help","mother"]},"face":{"file":"faces/stlt-sarah-redmond.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Small Things Like These, film, 2024"}},{"name":"The Mother Superior","who":"Head of the convent: polished, polite and quietly threatening.","group":"The convent","tag":"Head of the convent","wants":"Silence, and her power kept.","end":"Bill defies her; the book ends before we see her answer.","face":{"file":"stlt-f-mother.jpg","x":0.5,"y":0.34,"zoom":3.2,"ar":0.5625,"from":"Small Things Like These, film, 2024"},"pos":[180,510],"trait":"Polished, polite and threatening","check":{"like":["cold","calm","controlling","powerful","manipul","sinister","scary","intimidating","smooth","clever","evil","cruel","fake","hypocrit","menac","polite","threatening"],"want":["silence","quiet","secret","hide","cover","power","control","keep","reputation","image","money"]}},{"name":"Mrs Wilson","who":"The Protestant widow who kept Bill's pregnant teenage mother on as a servant and helped raise him; dead by 1985.","group":"Bill's past","tag":"The widow who took them in","wants":"To give Bill's mother a chance.","end":"Dead by 1985; Bill remembers her small kindnesses.","pos":[160,90],"trait":"Kind and generous","check":{"like":["caring","good","decent","gentle","brave","wise","charitable","nice","warm","loving","generous","kind"],"want":["help","chance","mother","raise","care","look","support","home","job"]},"face":{"file":"faces/stlt-mrs-wilson.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Small Things Like These, film, 2024"}},{"name":"Ned","who":"Mrs Wilson's farmhand, who quietly looked after Bill as a boy; Bill comes to realise he was most likely his father.","group":"Bill's past","tag":"Mrs Wilson's farmhand","wants":"To look after Bill, quietly.","end":"Bill realises Ned was most likely his father.","pos":[80,290],"trait":"Quiet and steady","check":{"like":["kind","gentle","caring","reliable","shy","humble","loyal","patient","decent","calm","good","quiet","steady"],"want":["bill","look","care","son","protect","help","raise","quiet","secret"]},"face":{"file":"faces/stlt-ned.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Small Things Like These, film, 2024"}},{"name":"Sarah (Bill's mother)","who":"Mrs Wilson's servant, who had Bill at sixteen and died when he was twelve.","group":"Bill's past","tag":"Bill's mother","wants":"To raise her son.","end":"She died when Bill was twelve.","pos":[470,80],"trait":"Young and hard-working","check":{"like":["poor","brave","loving","kind","strong","determined","servant","unmarried","young","hardwork"],"want":["bill","son","child","raise","keep","care","love","look","baby","home","job"]},"face":{"file":"faces/stlt-bills-mother.jpg","x":0.5,"y":0.5,"zoom":1,"ar":1,"from":"Small Things Like These, film, 2024"}},{"name":"Mrs Kehoe","who":"Runs the eating-house where Bill's men have their dinner; she warns him to be careful of the nuns.","group":"The town","tag":"Runs the eating-house","wants":"Bill to be careful of the nuns.","end":"She warns him on Christmas Eve.","pos":[800,520],"trait":"Shrewd and careful","check":{"like":["wise","sensible","cautious","knowing","sharp","practical","kind","caring","honest","protective","nosy","worried","shrewd","careful"],"want":["careful","nuns","warn","safe","protect","quiet","trouble","convent"]}}],"moments":[{"id":"stlt-1","title":"Born to an unmarried mother","where":"Chapter 2","when":"opening","what":"We learn that Bill's mother became pregnant at sixteen while working for Mrs Wilson, a Protestant widow, who kept her on when her own family would have nothing more to do with her. Bill's father is recorded as unknown, he was jeered at school, his mother died when he was twelve, and he worked his way up to owning the coal yard.","why":"Bill's own story mirrors that of the girls in the convent: he knows that one person's kindness decided his mother's fate.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Bill Furlong's story starts before he was born. His mother was sixteen, unmarried, and working for Mrs Wilson, a Protestant widow.","Her own family wanted nothing more to do with her. Mrs Wilson kept her on.","Bill's father: unknown. He was jeered at school, lost his mother at twelve, and worked his way up to owning the coal yard."],"chain":{"happens":"Bill's mother, unmarried at sixteen, was kept on by Mrs Wilson.","shows":"One person's kindness can change a life, against a society that shames unmarried mothers.","leads":"Bill grows up to own the coal yard."}},{"id":"stlt-2","title":"Raw times","where":"Chapter 2","when":"opening","what":"On his rounds Bill sees the town's hardship: businesses closing, people emigrating, Mick Sinnott's young son gathering sticks on the road, and a boy drinking milk left out for a cat behind the priest's house. Eileen blames Sinnott's drinking, while Bill resolves to keep his head down, stay on the right side of people and see his girls through St Margaret's.","why":"It establishes the poverty and insecurity that make Bill, and the whole town, reluctant to cross anyone powerful.","modes":["theme","cc"],"quote":"","sure":true,"tell":["New Ross, 1985. Raw times. Businesses closing. People emigrating.","On his rounds Bill sees it all: Mick Sinnott's young son gathering sticks on the road, a boy drinking the milk left out for a cat behind the priest's house.","Eileen blames Sinnott's drinking. Bill decides to keep his head down, stay on the right side of people, and see his girls through St Margaret's."],"chain":{"happens":"On his rounds Bill sees the hardship of 1985 and decides to keep his head down.","shows":"In hard times people protect themselves first.","leads":"Bill's comfortable silence."}},{"id":"stlt-3","title":"Christmas at home","where":"Chapter 3","when":"opening","what":"The town gathers to see the Christmas lights switched on, where the nuns speak only to the better-off parents, and at home the Furlongs bake the Christmas cake while the girls write to Santa. Bill remembers a lonely boyhood Christmas when he longed for the father he never knew, and he wonders, at nearly forty, what all his hard work is for.","why":"Family warmth is real but fragile, and Bill's restlessness shows a man already questioning the life he has built.","modes":["cc","gvv"],"quote":"","sure":true,"tell":["The town gathers to see the Christmas lights switched on. The nuns speak only to the better-off parents.","At home, the Furlongs bake the Christmas cake and the girls write to Santa.","Bill remembers a lonely boyhood Christmas, longing for the father he never knew. Nearly forty, he wonders what all his hard work is for."],"chain":{"happens":"Christmas at home, and Bill wonders what all his hard work is for.","shows":"Comfort isn't enough: Bill's unease is growing.","leads":"He is ready to notice what's happening at the convent."}},{"id":"stlt-4","title":"The girls in the chapel","where":"Chapter 4","when":"middle","what":"Delivering to the convent, Bill wanders into a small chapel where girls in grey shifts and no shoes are polishing the floor; one, with roughly cut hair, begs him to take her as far as the river and says she will drown herself. He holds out his empty hands, says it is not up to him, and says nothing about the girls to the nun who appears, though afterwards he thinks of the padlocks and the high wall topped with broken glass.","why":"This is Bill's first sight of the suffering hidden behind the convent walls, and his first silence.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["A delivery at the convent. Bill wanders into a small chapel, where girls in grey shifts and no shoes are polishing the floor.","One of them, her hair roughly cut, begs him to take her as far as the river. She says she'll drown herself.","He holds out his empty hands. It's not up to him. He says nothing to the nun. But afterwards he keeps thinking of the padlocks, and the high wall topped with broken glass."],"chain":{"happens":"A girl in the convent chapel begs Bill to take her as far as the river.","shows":"The convent is a prison, and the Church's cruelty is hidden.","leads":"Bill can't forget the padlocks and the high wall."}},{"id":"stlt-5","title":"Lost on the road","where":"Chapter 4","when":"middle","what":"Driving away troubled, Bill takes a wrong turn in the fog and loses his way. When he asks an old man where the road will take him, the man answers that it will take him wherever he wants to go.","why":"The old man's words suggest that Bill's direction in life is a matter of choice, foreshadowing the decision he must make.","modes":["theme","gvv"],"quote":"This road will take you wherever you want to go, son.","sure":true,"tell":["Driving away, troubled, Bill takes a wrong turn in the fog and loses his way.","He asks an old man where the road will take him.","The answer: wherever he wants to go."],"chain":{"happens":"Lost in the fog, an old man tells Bill the road goes wherever he wants.","shows":"Bill has a choice.","leads":"He keeps thinking about what to do."}},{"id":"stlt-6","title":"Eileen's warning","where":"Chapter 4","when":"middle","what":"That night Bill tells Eileen what he saw; she says it has nothing to do with them, that the nuns always pay their bills, and that their own girls are well minded. When he asks where he and his mother would have been if Mrs Wilson had thought that way, Eileen replies that Mrs Wilson was rich enough to do as she pleased.","why":"Eileen voices the town's practical, protective silence: getting on in life means looking away.","modes":["theme","cc"],"quote":"there's things you have to ignore, so you can keep on","sure":true,"tell":["That night Bill tells Eileen what he saw. Her answer: it's nothing to do with us. The nuns pay their bills, and our girls are well minded.","So Bill asks: where would he and his mother have been if Mrs Wilson had thought that way?","Eileen's reply: Mrs Wilson was rich enough to do as she pleased."],"chain":{"happens":"Eileen says what happens at the convent is none of their business.","shows":"Fear and self-interest keep the town silent.","leads":"Bill is left alone with his conscience."}},{"id":"stlt-7","title":"The girl in the coal shed","where":"Chapter 5","when":"middle","what":"Making an early Sunday delivery to the convent, Bill finds a girl who has been locked all night in the freezing coal shed, filthy and frightened. As they wait at the convent door, she asks him to find out about her fourteen-week-old baby, who has been taken from her.","why":"The convent's cruelty is now undeniable, and the girl's plea puts the question of action directly to Bill.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["An early Sunday delivery. Bill finds a girl in the convent's coal shed, locked in all night. Freezing. Filthy. Frightened.","As they wait at the convent door, she asks him one thing: find out about her baby. Fourteen weeks old, and taken from her."],"chain":{"happens":"Bill finds a girl locked in the coal shed, and she asks about her baby.","shows":"The cruelty can't be ignored any more.","leads":"He brings her to the convent door."}},{"id":"stlt-8","title":"Tea with the Mother Superior","where":"Chapter 5","when":"middle","what":"The Mother Superior smoothly brings Bill in for tea, produces the girl washed and dressed, passes off the night in the shed as a game of hide and seek, and remarks that places at the school are scarce; she then hands him an envelope with a Christmas card and money. Bill learns that the girl's name is Sarah, like his mother's, but leaves without asking about her baby.","why":"It shows how the institution controls appearances and buys silence, and how Bill, for now, goes along with it.","modes":["theme","cc"],"quote":"","sure":true,"tell":["The Mother Superior is all smooth politeness. She brings Bill in for tea and produces the girl, washed and dressed.","The night in the shed? A game of hide and seek. And, by the way, places at the school are scarce. Then an envelope: a Christmas card, and money.","The girl's name is Sarah, like Bill's mother. He leaves without asking about her baby."],"chain":{"happens":"The Mother Superior gives Bill tea, a Christmas card and money.","shows":"Power buys silence, politely.","leads":"Bill leaves without asking about the baby, and is ashamed."}},{"id":"stlt-9","title":"Communion and Ned","where":"Chapter 6","when":"middle","what":"At Mass Bill stays in his seat at Communion, and that evening he drives to the Wilson house to see Ned, the old farmhand; a woman there remarks on how alike they are, and Bill realises that Ned was most likely his father. Driving home, he is ashamed that he left Sarah at the convent, took the money and never asked about her baby.","why":"Bill sees that a quiet, unclaimed kindness shaped his whole life, and his guilt over Sarah sharpens.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["At Mass, when everyone goes up for Communion, Bill stays in his seat.","That evening he visits Ned, the old farmhand at the Wilson house. A woman remarks on how alike they are, and Bill realises that Ned was most likely his father.","Driving home, the shame hits: he left Sarah there, took the money, and never asked about her baby."],"chain":{"happens":"Bill stays in his seat at Communion, and realises Ned was most likely his father.","shows":"Bill sees his own story in the girls' story.","leads":"He knows he has to act."}},{"id":"stlt-10","title":"Mrs Kehoe's warning","where":"Chapter 7","when":"climax","what":"On Christmas Eve, when Bill pays for his men's dinner, Mrs Kehoe asks about his run-in with the Mother Superior and warns him to be careful, reminding him that his girls are at St Margaret's. Bill asks whether the nuns have only as much power as people give them.","why":"It shows that the town knows what goes on and has chosen to stay quiet, and spells out the cost Bill will pay if he acts.","modes":["theme","cc"],"quote":"these nuns have a finger in every pie","sure":true,"tell":["Christmas Eve. Bill is paying for his men's dinner when Mrs Kehoe asks about him and the Mother Superior.","Be careful, she warns. Remember, your girls are at St Margaret's.","Bill asks her a question: do the nuns only have as much power as people give them?"],"chain":{"happens":"Mrs Kehoe warns Bill that the nuns have a finger in every pie.","shows":"The Church's power rests on the town's fear.","leads":"Bill asks whether their power is only what people give them."}},{"id":"stlt-11","title":"Bill goes back for Sarah","where":"Chapter 7","when":"climax","what":"Instead of going home to get ready for midnight Mass, Bill walks on to the convent, finds Sarah locked in the coal shed again, and tells her she is coming home with him. He decides against bringing her to the priest's house and walks her, barefoot, through the town.","why":"Bill finally breaks his silence, choosing his conscience over his family's security and the town's approval.","modes":["theme","cc","gvv"],"quote":"","sure":true,"tell":["Bill should be going home to get ready for midnight Mass. Instead he walks on, to the convent.","Sarah is locked in the coal shed again. He tells her she's coming home with him.","Not to the priest's house. To his. And he walks her, barefoot, through the town."],"chain":{"happens":"Bill takes Sarah from the coal shed and walks her, barefoot, through the town.","shows":"Courage: one person doing the right thing.","leads":"He knows he will pay for it."}},{"id":"stlt-12","title":"The walk home","where":"Chapter 7","when":"ending","what":"People notice that the barefoot girl is not his daughter and avoid him or cut their talk short, but Bill feels a happiness greater than any he has known, though he knows he will pay for what he has done. Thinking of all the small things Mrs Wilson did, he approaches his own door with Sarah, afraid but hopeful; the novella ends before we see how Eileen or the town responds.","why":"The ending celebrates one person's courage while making clear that the community, and the cost, remain unchanged.","modes":["theme","cc","gvv"],"quote":"was there any point in being alive without helping one another?","sure":true,"tell":["People notice. The barefoot girl isn't his daughter. Some avoid him; some cut their talk short.","But Bill feels happier than he has ever felt, even knowing he'll pay for this.","He thinks of all the small things Mrs Wilson did. Then he walks up to his own door with Sarah, afraid, but hopeful. And the book ends there."],"chain":{"happens":"People look away, but Bill reaches his own door with Sarah, afraid and happy.","shows":"Small acts of kindness matter: a quietly hopeful ending.","leads":"We don't see what happens next: the reader must judge."}}],"modes":{"theme":{"themes":[{"name":"Power and control","points":["Power in the novella is quiet but total: the Mother Superior controls every part of Bill's visit, presenting Sarah washed and dressed, calling the night in the shed a game and hinting that school places are scarce [stlt-8].","The Church's control reaches into every part of town life, as Mrs Kehoe warns, but Bill's question, whether the nuns have only the power people give them, suggests that their power depends on everyone else's silence [stlt-10].","Control over the girls is physical: locked doors, walls topped with broken glass, a girl shut in a coal shed overnight and a baby taken from its mother [stlt-4] [stlt-7].","Money is a quieter form of control: the nuns pay their coal bills on time, and the Mother Superior presses an envelope of money on Bill as he leaves [stlt-6] [stlt-8]."]},{"name":"Freedom and entrapment","points":["The convent girls are prisoners: one begs Bill to take her as far as the river [stlt-4], and Sarah is found locked in the coal shed not once but twice [stlt-7] [stlt-11].","Bill is trapped in a different way, by hard times, routine and the fear of losing what he has built; he keeps his head down and wonders what all his work is for [stlt-2] [stlt-3].","The old man's answer, that the road will take Bill wherever he wants to go, hints that he is freer than he believes [stlt-5].","Acting on his conscience frees Bill: walking Sarah home, he feels a happiness greater than any he has known, even though he knows trouble lies ahead [stlt-12]."]},{"name":"Courage and silence","points":["Silence is the town's habit, and Bill shares it at first: he holds out empty hands to the girl in the chapel and later leaves the convent with the Mother Superior's money, never asking about Sarah's baby [stlt-4] [stlt-8].","Silence is presented as sensible and even loving: Eileen says there are things you have to ignore to get on, and Mrs Kehoe warns him to think of his daughters [stlt-6] [stlt-10].","Bill's first protest is small and private, staying in his seat at Communion, while his shame over leaving Sarah grows [stlt-9].","His courage, when it comes, is an ordinary act: he walks Sarah home through the town, asking himself whether there is any point in being alive without helping one another [stlt-11] [stlt-12]."]}]},"cc":{"aspects":[{"name":"Power and authority","points":["The Catholic Church is the real authority in 1985 New Ross: the nuns run the laundry and the best girls' school, and even a respected businessman treads carefully around the Mother Superior [stlt-8].","Authority works through hints rather than orders: the Mother Superior never threatens Bill openly, but her remark about scarce school places is understood [stlt-8], and Mrs Kehoe spells out the risk [stlt-10].","The townspeople defer to the convent's power: on Christmas Eve people avoid Bill or cut their talk short rather than ask about the barefoot girl beside him [stlt-12]."]},{"name":"Class, money and status","points":["Economic hardship shapes every choice: businesses close, people emigrate and children go without, so families like the Furlongs cling to what they have [stlt-2].","Status depends on respectability: Bill has risen from nothing to owning a business, and he and Eileen fear losing their place by offending the nuns [stlt-1] [stlt-6].","Eileen argues that only wealth gave Mrs Wilson the freedom to be kind, suggesting that conscience is a luxury for the secure [stlt-6].","Class divides even the Church's attention: at the Christmas lights the nuns speak only to the better-off parents [stlt-3]."]},{"name":"Gender roles and marriage","points":["Unmarried mothers are punished and hidden: Bill's mother escaped only because Mrs Wilson kept her on, while Sarah's baby is taken and she is locked away [stlt-1] [stlt-7].","Shame falls on the women, never the fathers: Bill's own father is unknown, and Eileen blames the girls' families for letting them get into trouble [stlt-1] [stlt-6].","Even the Mother Superior suggests that Bill must regret having no son, and he answers that his own mother was a girl once [stlt-8].","Marriage is a working partnership: Eileen runs the home and the girls while Bill earns, so the threat to their daughters' schooling makes his choice a family matter [stlt-3] [stlt-6]."]},{"name":"Religion and the Church","points":["The Church's public face hides private cruelty: the convent is admired for its beauty, while girls are locked behind walls topped with broken glass [stlt-4] [stlt-7].","Religious ritual is questioned: Bill cannot bring himself to receive Communion after leaving Sarah behind [stlt-9].","Keegan contrasts institutional religion with practical Christianity: Bill decides he cannot call himself a Christian if he is never brave enough to go against the way things are [stlt-12], and the kindness that saved his mother came from a Protestant widow [stlt-1].","Bill decides against bringing Sarah to the priest's house [stlt-11], suggesting that the clergy are seen as part of the same system as the convent."]},{"name":"Family and community","points":["Family is Bill's greatest love and his strongest reason to stay quiet: Eileen argues that their own girls are safe and must be protected [stlt-6].","The community knows but looks away: Mrs Kehoe has already heard about his run-in with the nuns [stlt-10], and people avoid him as he walks Sarah through the town [stlt-12].","Small kindnesses within a community matter: Mrs Wilson and Ned quietly raised Bill, and the novella ends with him thinking of all the small things Mrs Wilson did [stlt-9] [stlt-12].","Struggling families are judged harshly: Eileen blames Mick Sinnott's drinking for his son gathering sticks on the road, while Bill refuses to blame the child [stlt-2]."]},{"name":"Law, institutions and justice","points":["The laundry operates beyond the reach of the law: no guard, court or inspector ever appears, and at the convent the police are mentioned only when the Mother Superior claims they were about to call them because the girl was missing [stlt-8].","Keegan dedicates the book to the women and children who suffered in Ireland's mother and baby homes and Magdalen laundries, and opens with the 1916 Proclamation's promise to cherish all the children of the nation equally, so the coal-shed scene indicts the State as well as the Church [stlt-7].","Justice depends on one man's conscience, not on any institution: Bill takes Sarah out of the convent himself on Christmas Eve [stlt-11]."]}]},"gvv":{"opening":"The novella opens in a cold, struggling town where Bill works hard, worries about money and wonders what his life is for. The mood is muted and anxious, softened by the warmth of his family.","ending":"On Christmas Eve Bill frees Sarah and walks her home, feeling a happiness he has never known while knowing he will pay for it. The story ends at his door, so we never see how Eileen, the nuns or the town respond: it is hopeful about one man's courage but uncertain about everything else.","outlook":"mixed","points":["Light and dark sit side by side: the warmth of the Furlong kitchen at Christmas [stlt-3] contrasts sharply with the girls polishing the convent chapel and the girl locked in the coal shed [stlt-4] [stlt-7].","Kindness is the novella's source of light: Mrs Wilson's and Ned's quiet care for Bill [stlt-1] [stlt-9] is what finally moves him to help Sarah [stlt-12].","The ending is hopeful about individuals, since one man can choose to act, but darker about society, which looks away and will make him pay [stlt-12].","The open ending leaves the reader uneasy as well as uplifted: we never learn what happens to Sarah, Bill's daughters or his business [stlt-12].","Keegan makes the reader feel the pressure of silence before the relief of action: Eileen's warning and Mrs Kehoe's advice sound reasonable [stlt-6] [stlt-10], so Bill's choice feels genuinely brave.","The old man's words offer a hopeful view of human choice: Bill's road is not fixed, and he can still change direction [stlt-5]."]}},"links":[["Bill Furlong","Eileen Furlong","married"],["Bill Furlong","The Furlong daughters","their father"],["The Mother Superior","The Furlong daughters","runs their school"],["Bill Furlong","Sarah Redmond","takes her home"],["The Mother Superior","Sarah Redmond","keeps her locked up"],["The Mother Superior","Bill Furlong","buys his silence"],["Mrs Wilson","Sarah (Bill's mother)","kept her on"],["Sarah (Bill's mother)","Bill Furlong","his mother"],["Ned","Bill Furlong","most likely his father"],["Mrs Wilson","Ned","her farmhand"],["Mrs Kehoe","Bill Furlong","warns him"],["Eileen Furlong","Sarah Redmond","\"none of our business\""]]}},"questions":[{"year":2012,"paper":"main","mode":"gvv","option":"1","marks":70,"text":"“The general vision and viewpoint of a text can be shaped by the reader’s attitude to a central character.” Compare the extent to which your attitude to a central character helped shape your understanding of the general vision and viewpoint of at least two texts on your comparative course.","source":"https://exam-papers.stikleaf.com/exampapers/2012/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2012,"paper":"main","mode":"gvv","option":"2","marks":[30,40],"text":"“Various aspects of texts can provoke a range of emotional responses in readers which aid the construction of the general vision and viewpoint.” (a) With reference to one text on your comparative course, what aspects of the text shaped your emotional response and helped you to construct the general vision and viewpoint of that text? (b) With reference to two other texts on your comparative course, compare the aspects of these texts that shaped your emotional response and helped you to construct the general vision and viewpoint of these texts.","parts":{"stem":"“Various aspects of texts can provoke a range of emotional responses in readers which aid the construction of the general vision and viewpoint.”","a":"With reference to one text on your comparative course, what aspects of the text shaped your emotional response and helped you to construct the general vision and viewpoint of that text?","b":"With reference to two other texts on your comparative course, compare the aspects of these texts that shaped your emotional response and helped you to construct the general vision and viewpoint of these texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2012/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2013,"paper":"main","mode":"cc","option":"1","marks":70,"text":"“In any cultural context, deeply embedded values and attitudes can be difficult to change.” Compare the extent to which the above statement is valid in relation to your understanding of the cultural context of at least two texts on your comparative course.","source":"https://exam-papers.stikleaf.com/exampapers/2013/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2013,"paper":"main","mode":"cc","option":"2","marks":[30,40],"text":"“The issue of social class is important in shaping our understanding of the cultural context of a text.” (a) Discuss the importance of social class in shaping your understanding of the cultural context of one text that you have studied as part of your comparative course. (b) Compare the importance of social class in shaping your understanding of the cultural context of two other texts that you have studied as part of your comparative course.","parts":{"stem":"“The issue of social class is important in shaping our understanding of the cultural context of a text.”","a":"Discuss the importance of social class in shaping your understanding of the cultural context of one text that you have studied as part of your comparative course.","b":"Compare the importance of social class in shaping your understanding of the cultural context of two other texts that you have studied as part of your comparative course."},"source":"https://exam-papers.stikleaf.com/exampapers/2013/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2013,"paper":"main","mode":"theme","option":"1","marks":70,"text":"“Studying a theme or issue enables a reader to form both personal and universal reflections on that theme or issue.” Compare both the personal and universal reflections that you formed on a common theme or issue in two or more texts from your comparative course.","source":"https://exam-papers.stikleaf.com/exampapers/2013/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2013,"paper":"main","mode":"theme","option":"2","marks":[30,40],"text":"“In many texts, a theme or issue may not be resolved to the complete satisfaction of the reader.” (a) Discuss the extent to which a theme or issue is resolved to your satisfaction in one text on your comparative course. (b) Compare the extent to which the same theme or issue (as discussed in (a) above) is resolved to your satisfaction, in two other texts on your comparative course.","parts":{"stem":"“In many texts, a theme or issue may not be resolved to the complete satisfaction of the reader.”","a":"Discuss the extent to which a theme or issue is resolved to your satisfaction in one text on your comparative course.","b":"Compare the extent to which the same theme or issue (as discussed in (a) above) is resolved to your satisfaction, in two other texts on your comparative course."},"source":"https://exam-papers.stikleaf.com/exampapers/2013/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2014,"paper":"main","mode":"cc","option":"1","marks":70,"text":"“Various social groups, both large and small, (such as family, friends, organisations or community) reflect the cultural context in texts.” Compare the extent to which one or more social groups reflect the cultural context in at least two texts on your comparative course.","source":"https://exam-papers.stikleaf.com/exampapers/2014/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2014,"paper":"main","mode":"cc","option":"2","marks":[30,40],"text":"“The cultural context within a text often dictates the crises or difficulties faced by characters and their responses to these difficulties.” (a) Discuss to what extent this statement applies to at least one central character in one of the texts you have studied for your comparative course. (b) Compare the extent to which the above statement is applicable to at least one central character in each of two other texts you have studied on your comparative course.","parts":{"stem":"“The cultural context within a text often dictates the crises or difficulties faced by characters and their responses to these difficulties.”","a":"Discuss to what extent this statement applies to at least one central character in one of the texts you have studied for your comparative course.","b":"Compare the extent to which the above statement is applicable to at least one central character in each of two other texts you have studied on your comparative course."},"source":"https://exam-papers.stikleaf.com/exampapers/2014/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2014,"paper":"main","mode":"gvv","option":"1","marks":[30,40],"text":"(a) “The extent to which a reader can relate an aspect of a text to his or her experience of life, helps to shape an understanding of the general vision and viewpoint of that text.” Discuss this view in relation to your study of one text on your comparative course. (b) With reference to the text you referred to in 1. (a) above and at least one other text from your comparative course, compare how two other aspects of the texts (excluding the aspect discussed in 1. (a) above) influenced your understanding of the general vision and viewpoint of those texts.","parts":{"stem":"","a":"“The extent to which a reader can relate an aspect of a text to his or her experience of life, helps to shape an understanding of the general vision and viewpoint of that text.” Discuss this view in relation to your study of one text on your comparative course.","b":"With reference to the text you referred to in 1. (a) above and at least one other text from your comparative course, compare how two other aspects of the texts (excluding the aspect discussed in 1. (a) above) influenced your understanding of the general vision and viewpoint of those texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2014/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2014,"paper":"main","mode":"gvv","option":"2","marks":70,"text":"“Significant events in texts and the impact they have on readers often help to clarify the general vision and viewpoint of those texts.” With reference to three texts on your comparative course, compare the ways in which at least one significant event in each text, and its impact on you, helped to clarify the general vision and viewpoint of these texts.","source":"https://exam-papers.stikleaf.com/exampapers/2014/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2015,"paper":"main","mode":"theme","option":"1","marks":70,"text":"“Some texts leave readers with a largely idealistic impression of a theme or issue, while others leave readers with a more realistic or believable impression of the same theme or issue.” With reference to the above statement, compare the impressions of the same theme or issue you formed when studying three texts on your comparative course. Support your answer by reference to the texts.","source":"https://exam-papers.stikleaf.com/exampapers/2015/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2015,"paper":"main","mode":"theme","option":"2","marks":[30,40],"text":"“It is possible for a reader to be surprised or shocked (or both) by aspects of a theme or issue encountered in texts.” (a) Discuss the extent to which you were surprised or shocked (or both) by aspects of a theme or issue encountered in one of the texts you have studied for your comparative course. Support your answer by reference to the text. (b) Compare the extent to which you were surprised or shocked (or both) by aspects of the same theme or issue encountered in two other texts you have studied on your comparative course. Support your answer by reference to the texts.","parts":{"stem":"“It is possible for a reader to be surprised or shocked (or both) by aspects of a theme or issue encountered in texts.”","a":"Discuss the extent to which you were surprised or shocked (or both) by aspects of a theme or issue encountered in one of the texts you have studied for your comparative course. Support your answer by reference to the text.","b":"Compare the extent to which you were surprised or shocked (or both) by aspects of the same theme or issue encountered in two other texts you have studied on your comparative course. Support your answer by reference to the texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2015/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2016,"paper":"main","mode":"cc","option":"1","marks":70,"text":"“Understanding who holds power and who is powerless helps to reveal the cultural context in texts.” Compare how the distribution of power within each of three texts on your comparative course helps to reveal the cultural contexts in these texts. Support your answer with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2016/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2016,"paper":"main","mode":"cc","option":"2","marks":[30,40],"text":"“Central characters can be successful or unsuccessful in challenging aspects of the cultural context in texts.” (a) Discuss the extent to which at least one central character is successful or unsuccessful in challenging at least one aspect of the cultural context in one text on your comparative course. Support your answer with reference to the text. (b) Compare the extent to which at least one central character, from each of two other comparative texts, is either successful or unsuccessful in challenging at least one aspect of the cultural context in these texts. Support your answer with reference to your chosen texts. You may refer to the same aspect or different aspects of the cultural contexts in your answers.","parts":{"stem":"“Central characters can be successful or unsuccessful in challenging aspects of the cultural context in texts.”","a":"Discuss the extent to which at least one central character is successful or unsuccessful in challenging at least one aspect of the cultural context in one text on your comparative course. Support your answer with reference to the text.","b":"Compare the extent to which at least one central character, from each of two other comparative texts, is either successful or unsuccessful in challenging at least one aspect of the cultural context in these texts. Support your answer with reference to your chosen texts. You may refer to the same aspect or different aspects of the cultural contexts in your answers."},"source":"https://exam-papers.stikleaf.com/exampapers/2016/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2017,"paper":"main","mode":"gvv","option":"1","marks":[30,40],"text":"“Relationships between characters can influence our sense of the general vision and viewpoint of texts.” (a) Discuss the extent to which your sense of the general vision and viewpoint of one text on your comparative course is influenced by one (or more) relationship(s) in the text. Support your answer with reference to the text. (b) Compare the extent to which your sense of the general vision and viewpoint of two other texts on your comparative course is influenced by at least one relationship in each of these texts. Support your answer with reference to your chosen texts.","parts":{"stem":"“Relationships between characters can influence our sense of the general vision and viewpoint of texts.”","a":"Discuss the extent to which your sense of the general vision and viewpoint of one text on your comparative course is influenced by one (or more) relationship(s) in the text. Support your answer with reference to the text.","b":"Compare the extent to which your sense of the general vision and viewpoint of two other texts on your comparative course is influenced by at least one relationship in each of these texts. Support your answer with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2017/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2017,"paper":"main","mode":"gvv","option":"2","marks":70,"text":"“A variety of factors in texts can change or reinforce our initial impression of the general vision and viewpoint.” Compare the main factor or factors in three texts on your comparative course that changed or reinforced your initial impression of the general vision and viewpoint in these texts.","source":"https://exam-papers.stikleaf.com/exampapers/2017/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2017,"paper":"main","mode":"theme","option":"1","marks":[30,40],"text":"“The same theme or issue can appear more relevant to life today in some texts than in others.” (a) In relation to one text on your comparative course, discuss the aspects of the text that, in your opinion, make your chosen theme or issue appear more or less relevant to life today. Support your answer with reference to the text. (b) In relation to two other texts on your comparative course, compare the aspects of those texts that, in your opinion, make your chosen theme or issue appear more or less relevant to life today. Support your answer with reference to your chosen texts.","parts":{"stem":"“The same theme or issue can appear more relevant to life today in some texts than in others.”","a":"In relation to one text on your comparative course, discuss the aspects of the text that, in your opinion, make your chosen theme or issue appear more or less relevant to life today. Support your answer with reference to the text.","b":"In relation to two other texts on your comparative course, compare the aspects of those texts that, in your opinion, make your chosen theme or issue appear more or less relevant to life today. Support your answer with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2017/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2017,"paper":"main","mode":"theme","option":"2","marks":70,"text":"“There are many reasons why the exploration of the same theme or issue can be more entertaining in some texts than in others.” Compare the reasons why you found the exploration of the same theme or issue more entertaining in some texts than in others. Support your answer with reference to three texts on your comparative course.","source":"https://exam-papers.stikleaf.com/exampapers/2017/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2018,"paper":"main","mode":"cc","option":"1","marks":[30,40],"text":"(a) Identify at least one type of behaviour considered to be unacceptable within the world of one text on your comparative course. Explain why such behaviour is considered unacceptable in this cultural context and discuss the response or responses of society to such behaviour. Support your answer with reference to the text. (b) With reference to two other texts on your comparative course, identify at least one type of behaviour considered to be unacceptable in the world of each of these texts. Compare why such behaviour is considered unacceptable in these cultural contexts and the response or responses of society to such unacceptable behaviour. Support your answer with reference to the texts. In response to 1. (b) you may refer to the same or different types of behaviour in each of your chosen texts. You may refer to the same or different type(s) of behaviour as those referred to in 1. (a) above.","parts":{"stem":"","a":"Identify at least one type of behaviour considered to be unacceptable within the world of one text on your comparative course. Explain why such behaviour is considered unacceptable in this cultural context and discuss the response or responses of society to such behaviour. Support your answer with reference to the text.","b":"With reference to two other texts on your comparative course, identify at least one type of behaviour considered to be unacceptable in the world of each of these texts. Compare why such behaviour is considered unacceptable in these cultural contexts and the response or responses of society to such unacceptable behaviour. Support your answer with reference to the texts. In response to 1. (b) you may refer to the same or different types of behaviour in each of your chosen texts. You may refer to the same or different type(s) of behaviour as those referred to in 1. (a) above."},"source":"https://exam-papers.stikleaf.com/exampapers/2018/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2018,"paper":"main","mode":"cc","option":"2","marks":70,"text":"“Aspects of cultural context affect the extent to which a character can be happy or successful within the world of a text.” Identify a central character in each of three texts on your comparative course. Compare the aspect of the cultural context in each of these texts that, in your opinion, most affects the extent to which your chosen characters are happy or successful. You may refer to the same or different aspects of cultural context in each of your chosen texts. Support your answer with reference to the texts.","source":"https://exam-papers.stikleaf.com/exampapers/2018/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2019,"paper":"main","mode":"gvv","option":"1","marks":[30,40],"text":"“Our personal beliefs – our views and values – can influence our sense of the general vision and viewpoint of a text.” (a) With reference to one text on your comparative course, explain how your sense of the general vision and viewpoint was influenced by at least one of your personal beliefs. Develop your response with reference to the text. (b) Compare how your sense of the general vision and viewpoint in each of two other comparative texts was influenced by at least one of your personal beliefs. Develop your response with reference to your chosen texts. In response to 1. (b) you may refer to the same or different personal belief(s) that you referred to in 1. (a) above. You may refer to the same personal belief or different personal beliefs in relation to each of your two other comparative texts.","parts":{"stem":"“Our personal beliefs – our views and values – can influence our sense of the general vision and viewpoint of a text.”","a":"With reference to one text on your comparative course, explain how your sense of the general vision and viewpoint was influenced by at least one of your personal beliefs. Develop your response with reference to the text.","b":"Compare how your sense of the general vision and viewpoint in each of two other comparative texts was influenced by at least one of your personal beliefs. Develop your response with reference to your chosen texts. In response to 1. (b) you may refer to the same or different personal belief(s) that you referred to in 1. (a) above. You may refer to the same personal belief or different personal beliefs in relation to each of your two other comparative texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2019/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2019,"paper":"main","mode":"gvv","option":"2","marks":70,"text":"“Our view of the personal integrity of a central character can help to shape our impression of the general vision and viewpoint of a text.” Compare the extent to which your view of the personal integrity of one central character, in each of three texts on your comparative course, helped to shape your impression of the general vision and viewpoint of your chosen texts. Develop your answer with reference to the texts.","source":"https://exam-papers.stikleaf.com/exampapers/2019/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2020,"paper":"main","mode":"cc","option":"1","marks":[30,40],"text":"(a) Identify and discuss two aspects of cultural context which you believe make a significant contribution to the level of social division or the level of social unity evident in one text on your comparative course. Develop your response with reference to the text. (b) Compare the extent to which social division is evident in each of two other comparative texts you have studied. Develop your response with reference to the aspect or aspects of cultural context that you believe contribute(s) to the level of social division evident in these texts. In your answer you may refer to the same aspect or different aspects of cultural context in each of the texts that you have studied.","parts":{"stem":"","a":"Identify and discuss two aspects of cultural context which you believe make a significant contribution to the level of social division or the level of social unity evident in one text on your comparative course. Develop your response with reference to the text.","b":"Compare the extent to which social division is evident in each of two other comparative texts you have studied. Develop your response with reference to the aspect or aspects of cultural context that you believe contribute(s) to the level of social division evident in these texts. In your answer you may refer to the same aspect or different aspects of cultural context in each of the texts that you have studied."},"source":"https://exam-papers.stikleaf.com/exampapers/2020/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2020,"paper":"main","mode":"cc","option":"2","marks":70,"text":"Choose one central character from each of three texts on your comparative course. Compare the factors, related to cultural context, that affect the extent to which these characters are accepted or rejected as members of their societies. Develop your response with reference to your chosen texts. In your answer you should refer to at least one relevant factor related to cultural context in each of your three comparative texts. You may refer to the same factor or different factors in each of your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2020/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2021,"paper":"main","mode":"theme","option":"1","marks":[30,40],"text":"(a) Identify a theme or issue you studied on your comparative course. Discuss the various reasons why you did or did not find the exploration of this theme or issue emotionally engaging in one text on your comparative course. Support your response with reference to the text. (b) Compare the reasons why you found the exploration of the same theme or issue discussed above, more, less or equally emotionally engaging in each of two other texts you studied on your comparative course. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Identify a theme or issue you studied on your comparative course. Discuss the various reasons why you did or did not find the exploration of this theme or issue emotionally engaging in one text on your comparative course. Support your response with reference to the text.","b":"Compare the reasons why you found the exploration of the same theme or issue discussed above, more, less or equally emotionally engaging in each of two other texts you studied on your comparative course. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2021/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2021,"paper":"main","mode":"theme","option":"2","marks":70,"text":"Compare the insights you gained into the same theme or issue through understanding what influences or motivates one central character, from each of at least two texts on your comparative course, when making one or more key decisions. Develop your response with reference to your chosen texts. The insight or insights you gain into the same theme or issue from different texts may be similar or different.","source":"https://exam-papers.stikleaf.com/exampapers/2021/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2021,"paper":"main","mode":"cc","option":"1","marks":[30,40],"text":"(a) Discuss the extent to which a significant relationship was influenced by at least one aspect of the cultural context in one text on your comparative course. Develop your response with reference to the text. (b) Compare the extent to which one significant relationship was influenced by any aspect or aspects of the cultural context in each of two other texts on your comparative course. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss the extent to which a significant relationship was influenced by at least one aspect of the cultural context in one text on your comparative course. Develop your response with reference to the text.","b":"Compare the extent to which one significant relationship was influenced by any aspect or aspects of the cultural context in each of two other texts on your comparative course. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2021/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2021,"paper":"main","mode":"cc","option":"2","marks":70,"text":"Compare the reasons why significant social change does or does not occur within the cultural context established in each of at least two texts on your comparative course. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2021/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2021,"paper":"main","mode":"gvv","option":"1","marks":[30,40],"text":"(a) Discuss the extent to which a character that you found inspiring in one text on your comparative course influenced your sense of the general vision and viewpoint of this text. Develop your response with reference to your chosen text. (b) In relation to two other texts on your comparative course, compare the extent to which a character that you found inspiring influenced your sense of the general vision and viewpoint of each of these texts. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss the extent to which a character that you found inspiring in one text on your comparative course influenced your sense of the general vision and viewpoint of this text. Develop your response with reference to your chosen text.","b":"In relation to two other texts on your comparative course, compare the extent to which a character that you found inspiring influenced your sense of the general vision and viewpoint of each of these texts. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2021/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2021,"paper":"main","mode":"gvv","option":"2","marks":70,"text":"“The aspects of a text that we find unsettling or disturbing often influence our sense of the general vision and viewpoint.” In relation to at least two texts on your comparative course, compare the extent to which an aspect or aspects of your chosen texts, that you found unsettling or disturbing, influenced your sense of the general vision and viewpoint of these texts. Develop your response with refence to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2021/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2022,"paper":"main","mode":"cc","option":"1","marks":[30,40],"text":"(a) Discuss how those in power in society maintain their dominant position in one text on your comparative course. Develop your response with reference to the text. (b) Compare how those in power in society maintain their dominant position in each of two other texts on your comparative course. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss how those in power in society maintain their dominant position in one text on your comparative course. Develop your response with reference to the text.","b":"Compare how those in power in society maintain their dominant position in each of two other texts on your comparative course. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2022/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2022,"paper":"main","mode":"cc","option":"2","marks":70,"text":"Compare the extent to which the expression of individuality or divergence from social or cultural norms is tolerated within the cultural context of each of at least two texts on your comparative course. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2022/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2022,"paper":"main","mode":"gvv","option":"1","marks":[30,40],"text":"(a) Discuss how the level of resilience you found displayed by individuals or communities in one text on your comparative course helped to shape your sense of the general vision and viewpoint of this text. (b) Compare how the levels of resilience you found displayed by individuals or communities in each of two other texts on your comparative course influenced your sense of the general vision and viewpoint of these texts. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss how the level of resilience you found displayed by individuals or communities in one text on your comparative course helped to shape your sense of the general vision and viewpoint of this text.","b":"Compare how the levels of resilience you found displayed by individuals or communities in each of two other texts on your comparative course influenced your sense of the general vision and viewpoint of these texts. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2022/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2022,"paper":"main","mode":"gvv","option":"2","marks":70,"text":"Compare the extent to which your response to the treatment of disadvantaged or disempowered characters contributed to your sense of the general vision and viewpoint in each of at least two texts on your comparative course. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2022/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2023,"paper":"main","mode":"gvv","option":"1","marks":[30,40],"text":"(a) To what extent does the level of compassion and kindness, evident in one text on your comparative course, influence your sense of the general vision and viewpoint in that text? Develop your response with reference to your chosen text. (b) Compare the extent to which the levels of compassion and kindness, evident in two other texts on your comparative course, influence your sense of the general vision and viewpoint in these texts. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"To what extent does the level of compassion and kindness, evident in one text on your comparative course, influence your sense of the general vision and viewpoint in that text? Develop your response with reference to your chosen text.","b":"Compare the extent to which the levels of compassion and kindness, evident in two other texts on your comparative course, influence your sense of the general vision and viewpoint in these texts. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2023/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2023,"paper":"main","mode":"gvv","option":"2","marks":70,"text":"Compare how the response of characters to personal or societal crises, in at least two texts on your comparative course, influence your sense of the general vision and viewpoint. Develop your response with reference to your chosen texts. In your response you may discuss personal or societal crises, or both.","source":"https://exam-papers.stikleaf.com/exampapers/2023/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2023,"paper":"main","mode":"theme","option":"1","marks":[30,40],"text":"(a) In the case of one text on your comparative course, discuss how contradictory aspects of human nature emerge from a study of a particular theme or issue. Develop your response with reference to your chosen text. (b) Compare the extent to which contradictory aspects of human nature emerge from a study of the same theme or issue discussed in 1. (a) above, in two other texts on your comparative course. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"In the case of one text on your comparative course, discuss how contradictory aspects of human nature emerge from a study of a particular theme or issue. Develop your response with reference to your chosen text.","b":"Compare the extent to which contradictory aspects of human nature emerge from a study of the same theme or issue discussed in 1. (a) above, in two other texts on your comparative course. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2023/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2023,"paper":"main","mode":"theme","option":"2","marks":70,"text":"Compare how comprehensively similar or different ethical (moral) questions are explored in the treatment of the same theme or issue, in at least two texts on your comparative course. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2023/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2024,"paper":"main","mode":"cc","option":"1","marks":[30,40],"text":"(a) Discuss the extent to which the level of freedom enjoyed by a central character in one text on your comparative course is determined by this character’s social position and status. Develop your response with reference to your chosen text. (b) In the case of two other texts you have studied on your comparative course, compare the extent to which the level of freedom enjoyed by a central character in each of these texts is determined by these characters’ social position and status. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss the extent to which the level of freedom enjoyed by a central character in one text on your comparative course is determined by this character’s social position and status. Develop your response with reference to your chosen text.","b":"In the case of two other texts you have studied on your comparative course, compare the extent to which the level of freedom enjoyed by a central character in each of these texts is determined by these characters’ social position and status. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2024/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2024,"paper":"main","mode":"cc","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare the extent to which aspects of the cultural context, prevalent in these texts, nurture admirable values and attitudes. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2024/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2024,"paper":"main","mode":"theme","option":"1","marks":[30,40],"text":"(a) Discuss how an interesting interaction between two or more characters, at a pivotal moment in one of the texts on your comparative course, revealed important insights about a theme or issue in that text. Develop your response with reference to your chosen text. (b) In the case of at least two other texts you have studied on your comparative course, compare how an interesting interaction between two or more characters, at a pivotal moment in each of these texts, revealed important insights about the same theme or issue you discussed in part 1 (a) above. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss how an interesting interaction between two or more characters, at a pivotal moment in one of the texts on your comparative course, revealed important insights about a theme or issue in that text. Develop your response with reference to your chosen text.","b":"In the case of at least two other texts you have studied on your comparative course, compare how an interesting interaction between two or more characters, at a pivotal moment in each of these texts, revealed important insights about the same theme or issue you discussed in part 1 (a) above. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2024/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2024,"paper":"main","mode":"theme","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare the extent to which the exploration of a theme or issue in these texts, instilled in you a sense that human beings are selfless in their thoughts and actions. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2024/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"main","mode":"theme","option":"1","marks":[30,40],"text":"(a) In the case of one text on your comparative course, explain how the particular frame of mind or mindset of a central character aided the author’s exploration of the complexity of a theme or issue. Develop your response with reference to your chosen text. (b) Compare how the particular frame of mind or mindset of a central character, in each of two other texts you studied on your comparative course, aided the authors’ explorations of the complexity of the same theme or issue you discussed in part 1 (a) above. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"In the case of one text on your comparative course, explain how the particular frame of mind or mindset of a central character aided the author’s exploration of the complexity of a theme or issue. Develop your response with reference to your chosen text.","b":"Compare how the particular frame of mind or mindset of a central character, in each of two other texts you studied on your comparative course, aided the authors’ explorations of the complexity of the same theme or issue you discussed in part 1 (a) above. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"main","mode":"theme","option":"2","marks":70,"text":"Compare the extent to which inclusive or exclusive behaviour, in at least two texts on your comparative course, reveals interesting lessons about a theme or issue in these texts. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"main","mode":"cc","option":"1","marks":[30,40],"text":"(a) In the case of one text on your comparative course, discuss the extent to which understanding the consequences of not conforming to societal norms influences the behaviour of a central character in the cultural context of this text. Develop your response with reference to your chosen text. (b) In the case of two other texts on your comparative course, compare the extent to which understanding the consequences of not conforming to societal norms influences the behaviour of a central character in the cultural contexts in each of these texts. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"In the case of one text on your comparative course, discuss the extent to which understanding the consequences of not conforming to societal norms influences the behaviour of a central character in the cultural context of this text. Develop your response with reference to your chosen text.","b":"In the case of two other texts on your comparative course, compare the extent to which understanding the consequences of not conforming to societal norms influences the behaviour of a central character in the cultural contexts in each of these texts. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"main","mode":"cc","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare the extent to which divisions are encouraged in subtle rather than obvious ways, in order to maintain control and power successfully. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"main","mode":"gvv","option":"1","marks":[30,40],"text":"(a) Do you think that the climax of a text is over-influential in shaping a reader’s perception of the general vision and viewpoint of that whole text? Develop your response in relation to one text on your comparative course. (b) In the case of two other texts on your comparative course, compare the extent to which the climax, in each of these texts, is over-influential in shaping a reader’s perception of the general vision and viewpoint of these whole texts. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Do you think that the climax of a text is over-influential in shaping a reader’s perception of the general vision and viewpoint of that whole text? Develop your response in relation to one text on your comparative course.","b":"In the case of two other texts on your comparative course, compare the extent to which the climax, in each of these texts, is over-influential in shaping a reader’s perception of the general vision and viewpoint of these whole texts. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"main","mode":"gvv","option":"2","marks":70,"text":"Compare the extent to which your perception of the general vision and viewpoint, in at least two texts on your comparative course, is influenced by the varying degrees to which these texts present human nature as contradictory and paradoxical. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2026,"paper":"main","mode":"cc","option":"1","marks":[30,40],"text":"(a) In the case of one text on your comparative course, discuss the extent to which social mobility, between different social positions in the society of this text, is possible. Develop your response with reference to your chosen text. (b) In the case of two other texts on your comparative course, compare the extent to which social mobility, between different social positions in these societies, is possible. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"In the case of one text on your comparative course, discuss the extent to which social mobility, between different social positions in the society of this text, is possible. Develop your response with reference to your chosen text.","b":"In the case of two other texts on your comparative course, compare the extent to which social mobility, between different social positions in these societies, is possible. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/exampapers/2026/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2026,"paper":"main","mode":"cc","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare the extent to which a patriarchal and male-dominated society is nurtured and maintained in these texts. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2026/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2026,"paper":"main","mode":"gvv","option":"1","marks":[30,40],"text":"(a) In the case of one text on your comparative course, discuss whether your perception of the general vision and viewpoint was formed predominantly by your emotional or by your rational response to elements of this text. Develop your response with reference to your chosen text. (b) In the case of two other texts on your comparative course, compare the extent to which your perception of the general vision and viewpoint was formed predominantly by your emotional or by your rational response to elements of these texts. Develop your response with reference to your chosen texts. You may refer to the same or different elements of each of your chosen texts. You may refer to the same or different elements to those you referred to in 1 (a) above.","parts":{"stem":"","a":"In the case of one text on your comparative course, discuss whether your perception of the general vision and viewpoint was formed predominantly by your emotional or by your rational response to elements of this text. Develop your response with reference to your chosen text.","b":"In the case of two other texts on your comparative course, compare the extent to which your perception of the general vision and viewpoint was formed predominantly by your emotional or by your rational response to elements of these texts. Develop your response with reference to your chosen texts. You may refer to the same or different elements of each of your chosen texts. You may refer to the same or different elements to those you referred to in 1 (a) above."},"source":"https://exam-papers.stikleaf.com/exampapers/2026/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2026,"paper":"main","mode":"gvv","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare the extent to which human intervention, as a catalyst for change, influenced your perception of the general vision and viewpoint. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/exampapers/2026/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2022,"paper":"deferred","mode":"cc","option":"1","marks":[30,40],"text":"(a) Discuss the extent to which individual rights are respected or threatened in the cultural context established in one text on your comparative course. Develop your response with reference to the text. (b) Compare the extent to which individual rights are respected or threatened in the cultural context established in each of two other texts on your comparative course. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss the extent to which individual rights are respected or threatened in the cultural context established in one text on your comparative course. Develop your response with reference to the text.","b":"Compare the extent to which individual rights are respected or threatened in the cultural context established in each of two other texts on your comparative course. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/deferredexams/2022/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2022,"paper":"deferred","mode":"cc","option":"2","marks":70,"text":"Compare how democratic you find the society established in at least two texts on your comparative course. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2022/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2022,"paper":"deferred","mode":"gvv","option":"1","marks":[30,40],"text":"(a) Discuss the extent to which your sense of the general vision and viewpoint in one text on your comparative course was influenced by your response to the prevailing values evident in this text. Develop your response with reference to the text. (b) Compare the extent to which your sense of the general vision and viewpoint in two other texts on your comparative course was influenced by your response to the prevailing values evident in these texts. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss the extent to which your sense of the general vision and viewpoint in one text on your comparative course was influenced by your response to the prevailing values evident in this text. Develop your response with reference to the text.","b":"Compare the extent to which your sense of the general vision and viewpoint in two other texts on your comparative course was influenced by your response to the prevailing values evident in these texts. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/deferredexams/2022/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2022,"paper":"deferred","mode":"gvv","option":"2","marks":70,"text":"Compare the extent to which your sense of the general vision and viewpoint in at least two texts on your comparative course was shaped by how successfully a significant conflict or tension was resolved in each of these texts. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2022/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2023,"paper":"deferred","mode":"theme","option":"1","marks":[30,40],"text":"(a) Identify a theme or issue you studied on your comparative course. Discuss what your study of this theme or issue in one text on your comparative course revealed to you about yourself. Develop your response with reference to the text. (b) With reference to the same theme or issue discussed above, compare what your study of this theme or issue in each of two other comparative texts revealed to you about yourself. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Identify a theme or issue you studied on your comparative course. Discuss what your study of this theme or issue in one text on your comparative course revealed to you about yourself. Develop your response with reference to the text.","b":"With reference to the same theme or issue discussed above, compare what your study of this theme or issue in each of two other comparative texts revealed to you about yourself. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/deferredexams/2023/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2023,"paper":"deferred","mode":"theme","option":"2","marks":70,"text":"Compare the extent to which tension or conflict is used to explore or develop the same theme or issue in each of at least two texts on your comparative course. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2023/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2023,"paper":"deferred","mode":"gvv","option":"1","marks":[30,40],"text":"(a) Discuss how the portrayal of any kind of love helped to shape your perception of the general vision and viewpoint of one text on your comparative course. Develop your response with reference to the text. (b) Compare how the portrayal of any kind of love helped to shape your perception of the general vision and viewpoint of each of two other comparative texts. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss how the portrayal of any kind of love helped to shape your perception of the general vision and viewpoint of one text on your comparative course. Develop your response with reference to the text.","b":"Compare how the portrayal of any kind of love helped to shape your perception of the general vision and viewpoint of each of two other comparative texts. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/deferredexams/2023/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2023,"paper":"deferred","mode":"gvv","option":"2","marks":70,"text":"Compare the extent to which the level of idealism evident in each of at least two texts on your comparative course influenced your sense of the general vision and viewpoint in these texts. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2023/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2024,"paper":"deferred","mode":"theme","option":"1","marks":[30,40],"text":"(a) Identify a theme or issue from one text on your comparative course. To what extent was what you learned from the author’s exploration of this theme or issue original or innovative? Develop your response with reference to the text. (b) In the case of two other texts on your comparative course, compare the extent to which what you learned from the authors’ exploration of the same theme or issue, dealt with in part (a) above, was original or innovative. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Identify a theme or issue from one text on your comparative course. To what extent was what you learned from the author’s exploration of this theme or issue original or innovative? Develop your response with reference to the text.","b":"In the case of two other texts on your comparative course, compare the extent to which what you learned from the authors’ exploration of the same theme or issue, dealt with in part (a) above, was original or innovative. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/deferredexams/2024/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2024,"paper":"deferred","mode":"theme","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare the extent to which, in your opinion, the treatment of a theme or issue by the authors of these texts, had a long-lasting impact on you as a reader. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2024/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2024,"paper":"deferred","mode":"cc","option":"1","marks":[30,40],"text":"(a) In the case of one text on your comparative course, explain how your exploration of an aspect of the cultural context allowed you to gain at least one insight into the human condition. Develop your response with reference to the text. (b) In the case of two other texts on your comparative course, compare the extent to which your exploration of an aspect of the cultural context in each of these texts allowed you to gain at least one insight into the human condition. Develop your response with reference to your chosen texts. You may refer to the same or different aspects of cultural context in relation to each of your chosen texts. You may refer to the same or a different aspect of cultural context to the one discussed in part (a) above.","parts":{"stem":"","a":"In the case of one text on your comparative course, explain how your exploration of an aspect of the cultural context allowed you to gain at least one insight into the human condition. Develop your response with reference to the text.","b":"In the case of two other texts on your comparative course, compare the extent to which your exploration of an aspect of the cultural context in each of these texts allowed you to gain at least one insight into the human condition. Develop your response with reference to your chosen texts. You may refer to the same or different aspects of cultural context in relation to each of your chosen texts. You may refer to the same or a different aspect of cultural context to the one discussed in part (a) above."},"source":"https://exam-papers.stikleaf.com/deferredexams/2024/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2024,"paper":"deferred","mode":"cc","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare the extent to which the dominant values held by characters in these texts shaped the cultural context evident in your chosen texts. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2024/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"deferred","mode":"theme","option":"1","marks":[30,40],"text":"(a) Discuss how, by thoroughly investigating a theme or issue in one text on your comparative study, the author of this text exposed both positive and negative dimensions to that theme or issue. Develop your response with reference to your chosen text. (b) In each of two other texts on your comparative course compare how, by thoroughly investigating the same theme or issue discussed in part 1 (a), the authors of these texts, exposed both positive and negative dimensions to that theme or issue. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"Discuss how, by thoroughly investigating a theme or issue in one text on your comparative study, the author of this text exposed both positive and negative dimensions to that theme or issue. Develop your response with reference to your chosen text.","b":"In each of two other texts on your comparative course compare how, by thoroughly investigating the same theme or issue discussed in part 1 (a), the authors of these texts, exposed both positive and negative dimensions to that theme or issue. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/deferredexams/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"deferred","mode":"theme","option":"2","marks":70,"text":"Compare how the complexity of one character, from at least two comparative texts you have studied, was determined by the depth to which the authors explored a particular theme or issue in these texts. Clearly identify the theme or issue you have chosen to discuss. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"deferred","mode":"cc","option":"1","marks":[30,40],"text":"(a) In the case of one text on your comparative course, explain how a significant character’s engagement with aspects of the cultural context in that text did or did not help to build resilience in that character. Develop your response with reference to the text. (b) In the case of two other texts on your comparative course, compare how a significant character’s engagement with aspects of the cultural contexts in each of these texts did or did not help to build resilience in each of these characters. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"In the case of one text on your comparative course, explain how a significant character’s engagement with aspects of the cultural context in that text did or did not help to build resilience in that character. Develop your response with reference to the text.","b":"In the case of two other texts on your comparative course, compare how a significant character’s engagement with aspects of the cultural contexts in each of these texts did or did not help to build resilience in each of these characters. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/deferredexams/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"deferred","mode":"cc","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare the extent to which key characters in each of these texts, shape or are shaped by, or both, the cultural contexts which they inhabit. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"deferred","mode":"gvv","option":"1","marks":[30,40],"text":"(a) In the case of one text on your comparative course, use one or more key moment(s), to explain whether complex or simple factors or both, in your chosen text, helped you to form your sense of the general vision and viewpoint of that text. Develop your response with reference to the text. (b) Using one or more key moment(s) in each of two other texts on your comparative course, compare the extent to which it was complex or simple factors or both, in your chosen texts, that helped you to form your sense of the general vision and viewpoint of these texts. Develop your response with reference to your chosen texts.","parts":{"stem":"","a":"In the case of one text on your comparative course, use one or more key moment(s), to explain whether complex or simple factors or both, in your chosen text, helped you to form your sense of the general vision and viewpoint of that text. Develop your response with reference to the text.","b":"Using one or more key moment(s) in each of two other texts on your comparative course, compare the extent to which it was complex or simple factors or both, in your chosen texts, that helped you to form your sense of the general vision and viewpoint of these texts. Develop your response with reference to your chosen texts."},"source":"https://exam-papers.stikleaf.com/deferredexams/2025/lc/2/LC002ALP200EV.pdf","sure":true},{"year":2025,"paper":"deferred","mode":"gvv","option":"2","marks":70,"text":"In the case of at least two texts on your comparative course, compare how your general vision and viewpoint of these texts was influenced by the extent to which characters avail of opportunities to learn and improve, when they encounter them. Develop your response with reference to your chosen texts.","source":"https://exam-papers.stikleaf.com/deferredexams/2025/lc/2/LC002ALP200EV.pdf","sure":true}],"images":[{"file":"sive-kitchen.jpg","text":"sive","title":"A farmhouse kitchen, Bunratty Folk Park","author":"Joseph Mischyshyn, geograph.org.uk","licence":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Bunratty_Park_-_Site_%5E5-Mountain_Farmhouse_Kitchen_-_geograph.org.uk_-_3045722.jpg","kind":"place","caption":"The kitchen of the Mountain Farmhouse at Bunratty Folk Park, rebuilt as a poor farmer's house from the Limerick–Kerry border: the kind of kitchen where the whole of Sive is played.","moment":"sive-1","spots":[{"x":45,"y":38,"label":"The hearth","note":"The fire is the centre of the house. Every row, bargain and plea in the play happens in this one room.","quote":"","moment":"sive-1"},{"x":20,"y":78,"label":"Pots and chairs","note":"A bare, poor house. Money is short, which is why Seán Dóta's money can buy Mena's agreement.","quote":"","moment":"sive-2"},{"x":76,"y":45,"label":"The door","note":"Who comes through the door brings the outside world in: the matchmaker, the old suitor, the travelling men with their songs.","quote":"","moment":"sive-5"}],"scene":"sive-1"},{"file":"sive-s-body.jpg","text":"sive","title":"Sive is brought home","author":"Sive, Druid's 2003 Irish tour: Ruth Bradley as Sive, with Barry Ward, Noel O'Donovan and Eamon Morrissey. Photo: Valerie O'Sullivan","licence":"Copyright: used here for study","source":"https://www.druid.ie/productions/sive-2003-irish-tour","kind":"production","caption":"Liam carries in Sive's body: she has drowned in a bog hole.","moment":"sive-11","spots":[{"x":50,"y":66,"label":"Sive","note":"Laid on the kitchen table, in the room where her life was bargained away.","quote":"","moment":"sive-11"},{"x":44,"y":40,"label":"Liam","note":"The young man who loved her. He turns furiously on Mena.","quote":"","moment":"sive-11"}]},{"file":"sive-bog.jpg","text":"sive","title":"A Kerry bog","author":"Graham Horn, geograph.org.uk, 2008","licence":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:Kerry_peat_bog_-_geograph.org.uk_-_775099.jpg","kind":"place","caption":"Turf cut by hand and stacked to dry, with dark water in the cut-away holes. The play's world is bog and mountain.","moment":"sive-11","spots":[{"x":74,"y":33,"label":"Stacked turf","note":"Turf, cut each spring, was the fuel of every farmhouse: the hard, physical life of a small farm.","quote":"","moment":"sive-1"},{"x":40,"y":78,"label":"A bog hole","note":"Water fills the holes in the bog. Sive runs out across the bog at night and drowns in a bog hole.","quote":"","moment":"sive-11"}],"scene":"sive-11"},{"file":"sive-s-kitchen.jpg","text":"sive","title":"The Glavins' kitchen on stage","author":"Sive at the Gaiety Theatre, Dublin, 2024, directed by Andrew Flynn; photo via No More Workhorse","licence":"Copyright: used here for study","source":"https://nomoreworkhorse.com/2024/01/31/sive-gaiety-theatre-review-2/","kind":"production","caption":"The whole play happens in this one kitchen. Behind its walls, a red sky over the bog.","moment":"","spots":[{"x":24,"y":66,"label":"The table","note":"Where the match is made and where, at the end, Sive's body is laid.","quote":"","moment":"sive-2"},{"x":40,"y":18,"label":"The sky","note":"The set puts the bog and the mountain right behind the house: the dark, open country Sive runs into.","quote":"","moment":"sive-11"}],"scene":"sive-1"},{"file":"sive-s-nanna.jpg","text":"sive","title":"Sive and Nanna","author":"Sive at the Gaiety Theatre, Dublin, 2024, directed by Andrew Flynn; photo via No More Workhorse","licence":"Copyright: used here for study","source":"https://nomoreworkhorse.com/2024/01/31/sive-gaiety-theatre-review-2/","kind":"production","caption":"Nanna, Sive's grandmother, holds on to her: the one person in the house who takes her side.","moment":"","spots":[{"x":52,"y":52,"label":"Sive","note":"Gentle, still a schoolgirl, with no say over her own life. Mena tells her:","quote":"You will have no name till you take a husband.","moment":"sive-6"},{"x":70,"y":22,"label":"Nanna","note":"Sharp-tongued with Mena, but she begs Mike to stop the match.","quote":"","moment":"sive-8"}],"hero":true,"scene":"sive-8"},{"file":"sive-keane.jpg","text":"sive","title":"John B. Keane, 1983","author":"Bernard Gotfryd, Library of Congress","licence":"Public domain","source":"https://commons.wikimedia.org/wiki/File:John_B._Keane%2C_Irish_playwright.jpg","kind":"author","caption":"John B. Keane (1928–2002) ran a pub in Listowel, Co. Kerry. Sive, his first play, was put on by the Listowel Drama Group in 1959.","moment":"","spots":[],"scene":""},{"file":"othello-fradelle.jpg","text":"othello","title":"Othello Relating His Life Story to Desdemona","author":"Henri-Jean-Baptiste Fradelle (1778–1865), Royal Shakespeare Theatre collection","licence":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Henri_Jean-Baptiste_Victoire_Fradelle_%281778-1865%29_-_%27Othello%27%2C_Act_I%2C_Scene_3%2C_Othello_Relating_His_Life_Story_to_Desdemona_-_STRPG-A%2C_1993.47_-_Royal_Shakespeare_Theatre.jpg","kind":"painting","caption":"The story Othello tells the Senate in Act 1, Scene 3: at her father's house in Venice, Desdemona falls in love with him as he tells the story of his life.","moment":"othello-2","spots":[{"x":22,"y":40,"label":"Othello","note":"He tells of battles, sieges, capture, slavery and escape. He wins Desdemona with words, not witchcraft, as Brabantio claims.","quote":"She loved me for the dangers I had passed, / And I loved her that she did pity them.","moment":"othello-2"},{"x":66,"y":44,"label":"Desdemona","note":"She chooses her own husband, against her father and against Venice's expectations: a bold act for a woman in her world.","quote":"She'd come again, and with a greedy ear / Devour up my discourse.","moment":"othello-2"},{"x":75,"y":33,"label":"Brabantio","note":"Her father welcomed Othello as a guest and a war hero, but not as a son-in-law. He later warns: she has deceived her father, and may deceive Othello.","quote":"Her father loved me, oft invited me","moment":"othello-2"},{"x":85,"y":14,"label":"Venice","note":"Rich, ordered and proud: Othello is its trusted general and still an outsider. Cultural context: power, race and a daughter's duty.","quote":"","moment":""}]},{"file":"othello-f-watch.jpg","text":"othello","title":"Iago watches","author":"Othello (1995 film), directed by Oliver Parker, with Laurence Fishburne, Kenneth Branagh and Irène Jacob; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/16420-othello/images/backdrops","kind":"film","caption":"Othello and Desdemona together, while Iago leans on a pillar and watches.","moment":"othello-3","spots":[{"x":22,"y":40,"label":"Othello and Desdemona","note":"Their love at its height.","quote":"If it were now to die, / 'Twere now to be most happy","moment":"othello-3"},{"x":78,"y":45,"label":"Iago","note":"He vows to ruin their happiness.","quote":"O, you are well tuned now! But I'll set down the pegs that make this music","moment":"othello-3"}],"hero":true},{"file":"othello-stothard.jpg","text":"othello","title":"The Return of Othello (Act 2, Scene 1)","author":"Thomas Stothard (1755–1834), for the Boydell Shakespeare Gallery","licence":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Thomas_Stothard_-_The_Return_of_Othello%2C_from_Othello%2C_Act_II%2C_Scene_ii.jpg","kind":"painting","caption":"Othello lands safely in Cyprus after the storm wrecks the Turkish fleet, and greets Desdemona. It is the happiest moment in the play.","moment":"othello-3","spots":[{"x":31,"y":25,"label":"Othello","note":"In armour, a soldier back from the sea. His joy is so complete he fears nothing can match it again: a warning for the audience.","quote":"If it were now to die, / 'Twere now to be most happy","moment":"othello-3"},{"x":38,"y":31,"label":"Desdemona","note":"She has followed her husband to a war zone. He calls her his fair warrior.","quote":"O my fair warrior!","moment":"othello-3"},{"x":8,"y":16,"label":"The soldiers","note":"Cyprus is a military outpost: soldiers, weapons and men far from home. Gossip, drink and rank matter here (cultural context).","quote":"","moment":"othello-4"}]},{"file":"othello-tower.jpg","text":"othello","title":"Othello's Tower, Famagusta, Cyprus","author":"A.Savin (Wikimedia Commons), 2017","licence":"Free Art Licence","source":"https://commons.wikimedia.org/wiki/File:Famagusta_01-2017_img26_city_walls_Othello_Tower.jpg","kind":"place","caption":"A citadel in the walls of Famagusta, rebuilt by the Venetians, who ruled Cyprus from 1489 to 1571. Its nickname comes from the play, set in a Venetian fortress on Cyprus.","moment":"othello-3","spots":[{"x":46,"y":39,"label":"The Lion of Saint Mark","note":"The winged lion carved over the tower is the symbol of Venice: the island belongs to Venice, and Othello governs it for Venice.","quote":"","moment":"othello-3"},{"x":82,"y":46,"label":"The walls","note":"A fortress on the edge of the Venetian world, facing the Ottoman Turks. Once the Turks are drowned there is no enemy outside, so the war moves inside.","quote":"","moment":"othello-4"}]},{"file":"othello-f-iago.jpg","text":"othello","title":"Othello and Iago","author":"Othello (1995 film), directed by Oliver Parker, with Laurence Fishburne, Kenneth Branagh and Irène Jacob; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/16420-othello/images/backdrops","kind":"film","caption":"Iago at Othello's ear: the temptation scene, Act 3, Scene 3.","moment":"othello-5","spots":[{"x":28,"y":45,"label":"Othello","note":"He wants certainty and gets hints, pauses and pretended reluctance.","quote":"Give me the ocular proof","moment":"othello-5"},{"x":75,"y":45,"label":"Iago","note":"He warns against jealousy while planting it.","quote":"It is the green-eyed monster","moment":"othello-5"}]},{"file":"othello-holl.jpg","text":"othello","title":"G. V. Brooke as Othello and James Bennett as Iago, Act 3, Scene 3","author":"Benjamin Holl, engraved from a daguerreotype; Yale Center for British Art","licence":"CC0","source":"https://commons.wikimedia.org/wiki/File:Benjamin_Holl_-_Mr._G._V._Brooke_as_Othello_and_James_Bennett_as_Iago_-_%27Othello%2C%27_Act_III%2C_Scene_III_-_B1976.1.158_-_Yale_Center_for_British_Art.jpg","kind":"stage","caption":"The temptation scene on the Victorian stage: Othello turns on Iago and demands proof. Brooke was a Dublin-born actor famous in the role.","moment":"othello-5","spots":[{"x":35,"y":30,"label":"Othello","note":"He seizes Iago. He wants certainty, and Iago gives him only hints, pauses and pretended reluctance.","quote":"Villain, be sure thou prove my love a whore; / Be sure of it; give me the ocular proof","moment":"othello-5"},{"x":67,"y":32,"label":"Iago","note":"He looks shocked and loyal, but every word is planned. He warns Othello against jealousy while planting it.","quote":"O, beware, my lord, of jealousy; / It is the green-eyed monster","moment":"othello-5"},{"x":50,"y":86,"label":"The caption","note":"The engraving prints a line from this scene, Othello's threat to Iago.","quote":"If thou dost slander her and torture me, / Never pray more","moment":"othello-5"}]},{"file":"othello-willow.jpg","text":"othello","title":"Desdemona (The Song of the Willow)","author":"Théodore Chassériau (1819–1856), Metropolitan Museum of Art","licence":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Th%C3%A9odore_Chass%C3%A9riau_-_Desdemona_%28The_Song_of_the_Willow%29_-_2019.141.8_-_Metropolitan_Museum_of_Art.jpg","kind":"painting","caption":"Act 4, Scene 3: preparing for bed as Othello ordered, Desdemona sings the willow song. Only Emilia is with her.","moment":"othello-9","spots":[{"x":47,"y":36,"label":"Desdemona","note":"Quiet and sad, remembering her mother's maid Barbary, whose lover abandoned her. She still won't blame Othello.","quote":"Sing willow, willow, willow","moment":"othello-9"},{"x":55,"y":56,"label":"The harp","note":"The song is a story of a woman wronged by love: Desdemona's own story, though she can't see it yet.","quote":"","moment":"othello-9"},{"x":22,"y":54,"label":"The lamp","note":"The light by her bed. In the next scene Othello enters with a light and says he will put it out, and hers.","quote":"Put out the light, and then put out the light","moment":"othello-10"},{"x":80,"y":34,"label":"Emilia","note":"She tells Desdemona that when wives go wrong it is their husbands' fault: the play's sharpest words about how men treat women.","quote":"But I do think it is their husbands' faults / If wives do fall","moment":"othello-9"}]},{"file":"othello-colin.jpg","text":"othello","title":"Othello and Desdemona","author":"Alexandre-Marie Colin (1798–1875), 1829","licence":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Othello_and_Desdemona_by_Alexandre-Marie_Colin.jpg","kind":"painting","caption":"Act 5, Scene 2: Othello has smothered Desdemona. He believes he has done justice, not murder, until Emilia tells the truth.","moment":"othello-10","spots":[{"x":30,"y":30,"label":"Othello","note":"His hand on his heart: the noble general destroyed. At the end he asks to be remembered as one who loved too much.","quote":"one that loved not wisely but too well","moment":"othello-12"},{"x":70,"y":62,"label":"Desdemona","note":"Reviving for a moment, she protects him even now and blames herself.","quote":"Nobody; I myself. Farewell.","moment":"othello-10"},{"x":52,"y":86,"label":"The white cloth","note":"A white cloth lies by her hand. Is the painter reminding us of the handkerchief, Iago's false 'proof'?","quote":"","moment":"othello-6"}]},{"file":"othello-f-desdemona.jpg","text":"othello","title":"Desdemona","author":"Othello (1995 film), directed by Oliver Parker, with Laurence Fishburne, Kenneth Branagh and Irène Jacob; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/16420-othello/images/backdrops","kind":"film","caption":"Irène Jacob as Desdemona: brave enough to defy her father, loyal to Othello to the end.","moment":"","spots":[{"x":40,"y":38,"label":"Desdemona","note":"Her last words protect the husband who killed her.","quote":"Nobody; I myself. Farewell.","moment":"othello-10"}],"scene":"othello-9"},{"file":"othello-aldridge.jpg","text":"othello","title":"Ira Aldridge as Othello","author":"Henry Perronet Briggs (1791–1844), about 1830","licence":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Henry_Perronet_Briggs_-_Ira_Aldridge_as_Othello_-_Google_Art_Project.jpg","kind":"stage","caption":"Ira Aldridge (1807–1867), an African American actor, was one of the first Black actors to play Othello, including in London in 1833, where some critics attacked him in racist terms.","moment":"","spots":[{"x":50,"y":22,"label":"Ira Aldridge","note":"A reminder that race is at the heart of the play and of how it was staged: for centuries Othello was usually played by white actors.","quote":"","moment":""}],"scene":"othello-2"},{"file":"shawshank-f-crime.jpg","text":"shawshank","title":"The night of the murders","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"The opening: Andy, drunk, sits in his car outside the house where his wife is with her lover, loading a revolver.","moment":"shawshank-1","spots":[{"x":50,"y":55,"label":"The revolver","note":"The film cuts between this night and his trial. Andy says he threw the gun in the river. The jury doesn't believe him: two life sentences.","quote":"","moment":"shawshank-1"}]},{"file":"shawshank-f-bus.jpg","text":"shawshank","title":"The bus to Shawshank","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Andy arrives at Shawshank with the other new prisoners. (The prison is the real Ohio State Reformatory.)","moment":"shawshank-3","spots":[{"x":67,"y":70,"label":"The bus","note":"New men arrive. Inside, the prisoners bet on which 'fresh fish' will crack first: Red bets on Andy.","quote":"","moment":"shawshank-3"},{"x":50,"y":14,"label":"Shawshank","note":"Built like a fortress or a cathedral: a place made to show power.","quote":"I believe in two things: discipline and the Bible. Here you'll receive both.","moment":"shawshank-3"}]},{"file":"shawshank-f-arrivals.jpg","text":"shawshank","title":"The new arrivals","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Andy, still in his banker's suit, lined up with the other new men.","moment":"shawshank-3","spots":[{"x":44,"y":26,"label":"Andy","note":"Calm and silent. That night one new man breaks down and is beaten to death by Hadley; next morning Andy asks his name.","quote":"","moment":"shawshank-3"},{"x":12,"y":35,"label":"The new men","note":"Stripped of their clothes and names: from now on they are numbers.","quote":"","moment":"shawshank-3"}]},{"file":"shawshank-f-roof.jpg","text":"shawshank","title":"Beer on the roof","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Andy's tax advice to Captain Hadley wins three beers each for the men tarring the roof.","moment":"shawshank-4","spots":[{"x":7,"y":16,"label":"The beer","note":"A small reward, but for a moment they aren't prisoners. Andy sits apart and doesn't drink: he did it for them.","quote":"We sat and drank with the sun on our shoulders and felt like free men.","moment":"shawshank-4"}]},{"file":"shawshank-f-brooks.jpg","text":"shawshank","title":"Brooks was here","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Brooks carves his name into the beam of his halfway-house room before he hangs himself.","moment":"shawshank-5","spots":[{"x":48,"y":24,"label":"The carving","note":"After fifty years inside, Brooks can't live in the outside world: 'institutionalized'.","quote":"Brooks Hatlen was here","moment":"shawshank-5"}]},{"file":"shawshank-f-mozart.jpg","text":"shawshank","title":"Mozart over the loudspeakers","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Andy locks himself in the office and plays Mozart to the whole prison. The men in the yard stand still.","moment":"shawshank-6","spots":[{"x":40,"y":25,"label":"The loudspeaker","note":"Music fills the yard: the walls can't keep out beauty.","quote":"","moment":"shawshank-6"},{"x":65,"y":60,"label":"The men","note":"Red says that for the briefest of moments every last man in Shawshank felt free.","quote":"","moment":"shawshank-6"}]},{"file":"shawshank-f-office.jpg","text":"shawshank","title":"Andy in the office","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Andy leans back as the record plays. He knows it will cost him two weeks in solitary.","moment":"shawshank-6","spots":[{"x":65,"y":32,"label":"Andy","note":"Afterwards he says music is something inside you that they can't touch. Red warns him that hope is dangerous.","quote":"","moment":"shawshank-6"},{"x":86,"y":74,"label":"The record player","note":"Mozart's The Marriage of Figaro: donated records for the library he built.","quote":"","moment":"shawshank-6"}]},{"file":"shawshank-f-wall.jpg","text":"shawshank","title":"'Get busy living'","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Andy and Red sit against the wall after Tommy's death. Andy tells Red about Zihuatanejo and the rock near Buxton.","moment":"shawshank-8","spots":[{"x":40,"y":32,"label":"Andy","note":"He has chosen hope.","quote":"Get busy living, or get busy dying.","moment":"shawshank-8"},{"x":72,"y":32,"label":"Red","note":"Red fears the worst: Andy has asked for a length of rope.","quote":"","moment":"shawshank-8"}]},{"file":"shawshank-f-poster.jpg","text":"shawshank","title":"The poster","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Andy's poster of Rita Hayworth, later replaced by others, hides what he's doing behind it for almost twenty years.","moment":"shawshank-9","spots":[{"x":62,"y":60,"label":"The poster","note":"When the warden throws a stone at the last poster, it goes straight through: a tunnel.","quote":"","moment":"shawshank-9"},{"x":16,"y":30,"label":"Andy","note":"Patience and time: he digs with a tiny rock hammer, a little every night.","quote":"","moment":"shawshank-9"}]},{"file":"shawshank-f-hole.jpg","text":"shawshank","title":"The empty cell","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Norton looks into the tunnel behind the poster. Andy is gone.","moment":"shawshank-9","spots":[{"x":56,"y":50,"label":"Norton","note":"The man who controlled everything is beaten by the prisoner he exploited.","quote":"","moment":"shawshank-9"}]},{"file":"shawshank-f-rain.jpg","text":"shawshank","title":"Freedom in the rain","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Andy crawls through five hundred yards of sewer pipe and comes out into a creek in a thunderstorm.","moment":"shawshank-9","spots":[{"x":55,"y":42,"label":"Andy","note":"Arms raised to the rain, as if washed clean. The film's most famous image of hope.","quote":"","moment":"shawshank-9"}],"hero":true},{"file":"shawshank-f-bible.jpg","text":"shawshank","title":"The warden's Bible","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"In Norton's safe: Andy's Bible, with the rock hammer's hiding place cut into its pages.","moment":"shawshank-10","spots":[{"x":52,"y":45,"label":"The hollow","note":"Andy's note says it all.","quote":"Dear Warden, You were right. Salvation lay within.","moment":"shawshank-10"}]},{"file":"shawshank-f-approved.jpg","text":"shawshank","title":"Approved","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"After forty years, Red's parole is approved, once he stops telling the board what it wants to hear.","moment":"shawshank-11","spots":[{"x":66,"y":50,"label":"The stamp","note":"Red says 'rehabilitated' is just a made-up word, and this time he's released.","quote":"","moment":"shawshank-11"},{"x":18,"y":28,"label":"Red's photo","note":"Ellis Boyd Redding, prisoner 30265.","quote":"","moment":"shawshank-2"}]},{"file":"shawshank-f-sowasred.jpg","text":"shawshank","title":"So was Red","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Red carves his own words beside Brooks's and breaks parole: he chooses hope, where Brooks gave up.","moment":"shawshank-12","spots":[{"x":38,"y":32,"label":"The carving","note":"The same beam, two endings: Brooks's despair and Red's hope.","quote":"So was Red","moment":"shawshank-12"}]},{"file":"shawshank-f-letter.jpg","text":"shawshank","title":"Andy's letter","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"Under the black rock in the hayfield: money and a letter inviting Red to Mexico.","moment":"shawshank-12","spots":[{"x":40,"y":45,"label":"The letter","note":"Andy kept his promise.","quote":"Hope is a good thing, maybe the best of things, and no good thing ever dies.","moment":"shawshank-12"}]},{"file":"shawshank-f-beach.jpg","text":"shawshank","title":"Zihuatanejo","author":"The Shawshank Redemption (1994), directed by Frank Darabont; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/278-the-shawshank-redemption/images/backdrops","kind":"film","caption":"The last shot: Red walks along the beach to Andy, working on his boat. (Filmed at Sandy Point, St Croix.)","moment":"shawshank-12","spots":[{"x":68,"y":78,"label":"The boat","note":"Andy, free, doing the thing he dreamed of.","quote":"I hope the Pacific is as blue as it has been in my dreams. I hope.","moment":"shawshank-12"},{"x":50,"y":35,"label":"The sea","note":"Open blue after decades of grey walls: the film ends in freedom and friendship.","quote":"They say it has no memory.","moment":"shawshank-12"}]},{"file":"shawshank-oak.jpg","text":"shawshank","title":"The Shawshank oak, near Lucas, Ohio","author":"Tom Hart, 2013","licence":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Shawshank_tree%2C_Lucas%2C_Ohio_-_cropped.jpg","kind":"place","caption":"The white oak in the hayfield where Red finds Andy's box. A storm split it in half in 2011 (this photo is from 2013), and the rest fell in 2016.","moment":"shawshank-12","spots":[{"x":40,"y":30,"label":"The oak","note":"Andy describes the place: a long rock wall with a big oak tree at the north end.","quote":"a rock that has no earthly business in a Maine hayfield","moment":"shawshank-8"},{"x":22,"y":82,"label":"The split trunk","note":"Under the black rock by the wall, Red finds money and a letter: Andy kept his promise, so Red keeps his and breaks parole.","quote":"","moment":"shawshank-12"}]},{"file":"stlt-f-coal.jpg","text":"stlt","title":"The coal yard","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"Bill Furlong at work: the coal and timber merchant who keeps the town warm.","moment":"stlt-2","spots":[{"x":45,"y":40,"label":"Bill","note":"He worked his way up from nothing, the son of an unmarried mother. Now he has a business, a wife and five daughters to keep.","quote":"","moment":"stlt-1"},{"x":76,"y":72,"label":"The coal","note":"Hard, black, filthy work, and a living in hard times: 1985, businesses closing and people emigrating.","quote":"","moment":"stlt-2"}],"hero":true},{"file":"stlt-f-lorry.jpg","text":"stlt","title":"W. Furlong, New Ross","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"Bill's lorry, with his name on it: everyone in the town knows him.","moment":"stlt-2","spots":[{"x":76,"y":52,"label":"His name","note":"Respectable and known by all, which is exactly what he risks at the end.","quote":"","moment":"stlt-12"}]},{"file":"stlt-f-boy.jpg","text":"stlt","title":"The boy on the road","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"On his rounds Bill sees the town's hardship: a young boy gathering sticks.","moment":"stlt-2","spots":[{"x":24,"y":55,"label":"The boy","note":"Mick Sinnott's son, out gathering sticks for the fire.","quote":"","moment":"stlt-2"},{"x":74,"y":40,"label":"Bill","note":"He reaches out to the boy: one of the small kindnesses the title points to.","quote":"","moment":"stlt-2"}]},{"file":"stlt-town.jpg","text":"stlt","title":"South Street, New Ross, 1993","author":"Ben Brooksbank, geograph.org.uk","licence":"CC BY-SA 2.0","source":"https://commons.wikimedia.org/wiki/File:New_Ross%2C_South_Street_to_Tholsel%2C_1993_-_geograph.org.uk_-_4451638.jpg","kind":"place","caption":"New Ross, Co. Wexford, where the novella is set: eight years after its Christmas of 1985.","moment":"stlt-2","spots":[{"x":47,"y":25,"label":"The Tholsel","note":"The old town hall at the top of the street, with its clock: a small town where everybody knows everybody's business.","quote":"","moment":"stlt-10"},{"x":85,"y":45,"label":"The shops","note":"In 1985 businesses are closing and people are emigrating. Bill sees the hardship on his rounds and keeps his head down.","quote":"","moment":"stlt-2"},{"x":12,"y":75,"label":"People in the street","note":"When Bill walks home with Sarah, barefoot, people notice and look away.","quote":"","moment":"stlt-12"}],"scene":"stlt-2"},{"file":"stlt-f-home.jpg","text":"stlt","title":"At home","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"Bill at the table with his family: the comfortable home he could lose.","moment":"stlt-3","spots":[{"x":40,"y":42,"label":"Bill","note":"He has a good life, and he can't stop thinking about what he saw at the convent.","quote":"","moment":"stlt-3"}]},{"file":"stlt-f-girls.jpg","text":"stlt","title":"The girls at the convent","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"Girls in grey shifts, barefoot in the cold, watched by a nun.","moment":"stlt-4","spots":[{"x":34,"y":62,"label":"The girls","note":"One of the girls in the chapel begs Bill to take her as far as the river.","quote":"","moment":"stlt-4"},{"x":66,"y":40,"label":"The nun","note":"The Church holds the power in the town. Nobody asks what happens behind the walls.","quote":"","moment":"stlt-10"}]},{"file":"stlt-laundry.jpg","text":"stlt","title":"The ironing room, Gloucester Street laundry, Dublin","author":"Old postcard, via Architecture of Dublin (Flickr)","licence":"Public domain","source":"https://commons.wikimedia.org/wiki/File:Monastery%2C_Gloucester_Street_North%2C_Dublin.jpg","kind":"place","caption":"The ironing room of the Monastery of Our Lady of Charity of Refuge, Gloucester Street (now Sean McDermott Street), Dublin. It was the last Magdalene laundry in Ireland to close, in 1996.","moment":"stlt-4","spots":[{"x":55,"y":44,"label":"The women at work","note":"Women and girls washed and ironed here for no pay, some for most of their lives. The girls Bill meets at the convent are kept the same way.","quote":"","moment":"stlt-4"},{"x":50,"y":23,"label":"The crucifix","note":"The Church ran the laundries. In the novella the town knows what goes on at the convent and says nothing: the nuns have a hand in everything.","quote":"","moment":"stlt-10"}],"scene":"stlt-4"},{"file":"stlt-f-eileen.jpg","text":"stlt","title":"Eileen","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"Bill tells Eileen what he saw. She says it has nothing to do with them.","moment":"stlt-6","spots":[{"x":20,"y":50,"label":"Eileen","note":"Practical and afraid for their girls: the nuns pay their bills, and their own daughters are well minded.","quote":"","moment":"stlt-6"},{"x":74,"y":40,"label":"Bill","note":"He asks where he and his mother would have been if Mrs Wilson had thought that way.","quote":"","moment":"stlt-6"}]},{"file":"stlt-f-shed.jpg","text":"stlt","title":"The coal shed","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"On an early delivery Bill finds a girl locked all night in the freezing coal shed.","moment":"stlt-7","spots":[{"x":46,"y":48,"label":"The girl","note":"Sarah. She asks him to find out about her baby, who has been taken from her.","quote":"","moment":"stlt-7"}]},{"file":"stlt-f-mother.jpg","text":"stlt","title":"The Mother Superior","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"Sister Mary (Emily Watson): smooth, polite and in control.","moment":"stlt-8","spots":[{"x":50,"y":40,"label":"Sister Mary","note":"She calls the night in the shed a game of hide and seek, mentions how scarce places at the school are, and hands Bill an envelope with money.","quote":"","moment":"stlt-8"}]},{"file":"stlt-f-tea.jpg","text":"stlt","title":"Brought in for tea","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"At the convent: Bill with the nuns and the girl, now washed and dressed. He leaves without asking about her baby.","moment":"stlt-8","spots":[{"x":24,"y":40,"label":"Bill","note":"Silenced by politeness and fear for his daughters' places at the school.","quote":"","moment":"stlt-8"},{"x":55,"y":45,"label":"The girl","note":"Her name is Sarah, like Bill's mother's.","quote":"","moment":"stlt-8"}]},{"file":"stlt-f-mass.jpg","text":"stlt","title":"Mass","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"At Mass Bill stays in his seat at Communion.","moment":"stlt-9","spots":[{"x":70,"y":38,"label":"The altar","note":"The Church at the centre of the town's life. Bill can't go up: something in him has changed.","quote":"","moment":"stlt-9"}]},{"file":"stlt-f-walk.jpg","text":"stlt","title":"Taking Sarah","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"Bill finds Sarah in the coal shed again and walks her, barefoot, through the town.","moment":"stlt-11","spots":[{"x":45,"y":30,"label":"Bill","note":"He decides not to bring her to the priest's house. He is doing the thing, not asking permission.","quote":"","moment":"stlt-11"},{"x":57,"y":55,"label":"Sarah","note":"Wrapped in his coat. People notice she isn't his daughter.","quote":"","moment":"stlt-12"}]},{"file":"stlt-f-door.jpg","text":"stlt","title":"His own door","author":"Small Things Like These (2024 film of the novella), directed by Tim Mielants, with Cillian Murphy; still via TMDB","licence":"Copyright: used here for study","source":"https://www.themoviedb.org/movie/1102493-small-things-like-these/images/backdrops","kind":"film","caption":"Bill comes to his own door with Sarah, afraid but hopeful. The novella ends before we see what Eileen or the town does.","moment":"stlt-12","spots":[{"x":50,"y":60,"label":"Bill and Sarah","note":"Happier than he has ever been, though he knows he will pay for it. The open ending leaves the reader to judge.","quote":"","moment":"stlt-12"}]},{"file":"stlt-seat.jpg","text":"stlt","title":"The Magdalene memorial seat, St Stephen's Green, Dublin","author":"Osama Shukir Muhammed Amin (Wikimedia Commons), 2015","licence":"CC BY-SA 4.0","source":"https://commons.wikimedia.org/wiki/File:Magdalene_seat%2C_St_Stephen%27s_Green_Park%2C_Dublin.jpg","kind":"place","caption":"A bench in St Stephen's Green, Dublin, remembering the women who worked in the Magdalene laundries and the children born to some of them.","moment":"stlt-12","spots":[{"x":50,"y":52,"label":"The words","note":"Ireland now remembers what Bill's town wouldn't talk about. Keegan's novella is part of that remembering.","quote":"To the women who worked in the Magdalen laundry institutions and to the children born to some members of those communities – reflect here upon their lives.","moment":"stlt-12"}],"scene":"stlt-12"},{"file":"stlt-keegan.jpg","text":"stlt","title":"Claire Keegan, 2007","author":"Ian Oliver, at the Dublin Writers Festival","licence":"CC BY 2.0","source":"https://commons.wikimedia.org/wiki/File:Dublin_Writers_Festival_2007_%28686228986%29_%28cropped%29.jpg","kind":"author","caption":"Claire Keegan, from Co. Wicklow, published Small Things Like These in 2021. It was shortlisted for the Booker Prize.","moment":"","spots":[],"scene":""}],"games":{"link":[{"texts":["sive","othello"],"mode":"theme","a":{"t":"sive","s":"Sive objects to the match but is too isolated to act, so her death in the bog becomes a silent protest against the life chosen for her."},"b":{"t":"othello","s":"once Desdemona is accused in Othello, she can only protest her innocence and submit, and her dying words, 'Nobody; I myself', shield the husband who has killed her."},"rel":"same","link":"Similarly,","why":"Both young women are silenced by the people around them, and neither can save herself by speaking out."},{"texts":["sive","othello"],"mode":"theme","a":{"t":"sive","s":"Mike cannot look his mother in the face when he insists the match is for the best, yet he says nothing to stop it."},"b":{"t":"othello","s":"Emilia finally breaks her silence in Othello, defying her husband's orders and Othello's sword to reveal the truth about the handkerchief."},"rel":"differ","link":"In contrast,","why":"Mike's silence keeps a wrong going, while Emilia risks, and loses, her life to speak the truth."},{"texts":["sive","othello"],"mode":"cc","a":{"t":"sive","s":"In Sive, a matchmaker, an aunt and an uncle settle a schoolgirl's marriage for £200, as if she were goods to be sold."},"b":{"t":"othello","s":"women are treated as property in Othello, where Iago wakes Brabantio by shouting 'thieves!' and telling him to look to his house, his daughter and his bags."},"rel":"same","link":"Likewise,","why":"In both societies a young woman is treated as a possession of the men and families around her."},{"texts":["sive","othello"],"mode":"cc","a":{"t":"sive","s":"In Sive, no guard, court or official ever appears, and a private bargain made in a kitchen decides a girl's life."},"b":{"t":"othello","s":"Venice offers a fair hearing in Othello, as the Duke lets Othello and Desdemona speak before dismissing Brabantio's charge of witchcraft."},"rel":"differ","link":"On the other hand,","why":"Sive's world has no law to turn to, while Venice's institutions at first listen to both sides."},{"texts":["sive","othello"],"mode":"gvv","a":{"t":"sive","s":"In Sive, goodness exists in Liam, Nanna and the travelling men, but it is powerless against the money that drives the match."},"b":{"t":"othello","s":"goodness in Othello is real but cannot save itself, as Desdemona stays loyal to the end and Emilia dies defending her mistress's honour."},"rel":"same","link":"In the same way,","why":"Both plays show good people defeated, which is a large part of what makes their visions so bleak."},{"texts":["shawshank","sive"],"mode":"theme","a":{"t":"shawshank","s":"In The Shawshank Redemption, Andy crawls through five hundred yards of sewer pipe and stands in the pouring rain with his arms raised, finally free."},"b":{"t":"sive","s":"the only escape left to Sive is death in the bog, because Liam's letter offering her a way out is burned before she can read it."},"rel":"differ","link":"Conversely,","why":"Andy's escape leads to freedom and life, while Sive's only way out of her trap is death."},{"texts":["sive","shawshank"],"mode":"theme","a":{"t":"sive","s":"Liam is the one character in Sive who speaks out openly, but when he begs Mike and Mena to stop the match, they simply send him away."},"b":{"t":"shawshank","s":"Andy's courage pays off in The Shawshank Redemption: by daring to speak up to Captain Hadley on the roof, he wins beer for his fellow workers."},"rel":"differ","link":"However,","why":"Both men find the courage to speak to those with power, but only Andy's words change anything."},{"texts":["shawshank","sive"],"mode":"cc","a":{"t":"shawshank","s":"At Shawshank, Captain Hadley beats a frightened new prisoner to death on Andy's first night, and no one is held to account."},"b":{"t":"sive","s":"than Hadley's violence, threats keep the weak in line in Sive, where Mena and Thomasheen silence Nanna by threatening her with the county home."},"rel":"degree","link":"less overtly","why":"Both worlds silence the powerless, but Sive's bullies use threats where Shawshank's guards use open violence."},{"texts":["sive","shawshank"],"mode":"gvv","a":{"t":"sive","s":"In Sive, Carthalawn's mocking songs comment on the action like a chorus, telling the truth about greed and foreshadowing a death."},"b":{"t":"shawshank","s":"in The Shawshank Redemption, Red's voiceover guides how we feel, taking us from his warning that hope is dangerous to the film's last words, 'I hope'."},"rel":"same","link":"Similarly,","why":"Both texts use a voice that stands slightly outside the action to shape how the audience sees the story."},{"texts":["sive","shawshank"],"mode":"gvv","a":{"t":"sive","s":"In Sive, every glimmer of hope, from Liam's secret visit to his escape plan, is crushed by the adults' greed."},"b":{"t":"shawshank","s":"than Sive, The Shawshank Redemption admits that hope can be crushed, as Brooks hangs himself after his release and Tommy is killed for being willing to tell the truth."},"rel":"degree","link":"to a lesser degree","why":"Both texts show hope destroyed, but in the film these losses are outweighed by Andy's escape, while in Sive nothing outweighs them."},{"texts":["stlt","sive"],"mode":"theme","a":{"t":"stlt","s":"In Small Things Like These, Bill holds out his empty hands to the girl in the chapel who begs for his help, saying it is not up to him."},"b":{"t":"sive","s":"Bill, Mike in Sive stays silent when he could act, doing nothing to warn Sive after Thomasheen burns Liam's letter."},"rel":"same","link":"Much like","why":"Both men see a wrong being done and at first do nothing, so their silence makes them complicit."},{"texts":["sive","stlt"],"mode":"cc","a":{"t":"sive","s":"In Sive, Mena uses Sive's birth outside marriage as a weapon, telling her she will have no name till she takes a husband."},"b":{"t":"stlt","s":"than Sive, Small Things Like These shows how unmarried mothers are punished: Sarah's baby is taken from her and she is locked away in the convent."},"rel":"degree","link":"more explicitly","why":"Both societies shame unmarried mothers, but Keane shows it through cruel words while Keegan shows girls locked up and babies taken."},{"texts":["sive","stlt"],"mode":"cc","a":{"t":"sive","s":"In Sive, the Church stays in the background as a source of rules and respectability, and no priest ever steps in to protect Sive."},"b":{"t":"stlt","s":"than in Sive, the Church holds real power in Small Things Like These, where the nuns run the laundry and the best girls' school."},"rel":"degree","link":"to a far greater extent","why":"Religion shapes respectability in both worlds, but only in Keegan's New Ross does the Church directly control people's lives."},{"texts":["stlt","sive"],"mode":"gvv","a":{"t":"stlt","s":"Small Things Like These ends with Bill walking Sarah home through the town, feeling a happiness greater than any he has known."},"b":{"t":"sive","s":"Sive ends with a drowned girl, a lament and Nanna's grief, while those who profited from the match slip away unpunished."},"rel":"differ","link":"In contrast,","why":"Keegan's ending offers hope through one man's courage, while Keane's leaves only grief and injustice."},{"texts":["sive","stlt"],"mode":"gvv","a":{"t":"sive","s":"Keane's play opens in a cramped, poor kitchen full of insults and resentment, where the schoolgirl Sive is treated as a burden."},"b":{"t":"stlt","s":"Small Things Like These opens in a cold, struggling town, where businesses are closing, people are emigrating and Bill worries about money."},"rel":"same","link":"Likewise,","why":"Both openings show a world worn down by poverty, which casts a shadow over the outlook from the start."},{"texts":["othello","shawshank"],"mode":"theme","a":{"t":"othello","s":"In Othello, Iago, who holds no high rank, uses cunning to destroy a good man, turning Desdemona's goodness into 'the net / That shall enmesh them all'."},"b":{"t":"shawshank","s":"in The Shawshank Redemption, Andy uses his cleverness against a corrupt man, turning the false identity he invented to hide Norton's money into a way of taking that money himself."},"rel":"differ","link":"However,","why":"Both men overturn someone more powerful through cleverness, but Iago's power destroys the innocent while Andy's brings down the guilty."},{"texts":["shawshank","othello"],"mode":"theme","a":{"t":"shawshank","s":"In The Shawshank Redemption, prison traps Brooks's mind as well as his body: after fifty years he is 'institutionalized' and cannot cope with the free world."},"b":{"t":"othello","s":"Othello becomes a prisoner of his own mind: once Iago's suggestions take hold, he cannot go back to trusting Desdemona, and he bids 'Farewell the tranquil mind!'"},"rel":"same","link":"In the same way,","why":"In both texts the worst trap is inside a man's own head, and neither man escapes it."},{"texts":["othello","shawshank"],"mode":"cc","a":{"t":"othello","s":"In Othello, the Duke gives Othello and Desdemona a fair hearing before dismissing Brabantio's charge of witchcraft."},"b":{"t":"shawshank","s":"the Venetian Senate, the court in The Shawshank Redemption fails Andy completely, convicting him of two murders he did not commit."},"rel":"differ","link":"Unlike","why":"Venice's institutions first show justice working, while the film opens with the law condemning an innocent man."},{"texts":["shawshank","othello"],"mode":"cc","a":{"t":"shawshank","s":"The Shawshank Redemption says almost nothing directly about race: Red is a Black man and Andy a white former banker, but the film never makes race an issue."},"b":{"t":"othello","s":"than The Shawshank Redemption, Othello makes race part of its world: racist language greets Othello from the first scene, when Iago calls him 'an old black ram'."},"rel":"degree","link":"more explicitly","why":"Both texts have a Black central character, but only Othello shows a society that openly judges a man by his colour."},{"texts":["othello","shawshank"],"mode":"gvv","a":{"t":"othello","s":"In Othello, Iago reveals his plan to the audience in soliloquy while Othello keeps calling him 'honest Iago', so we watch the disaster coming, helpless to stop it."},"b":{"t":"shawshank","s":"Darabont hides Andy's escape from the viewer as well as from Red, so its sudden reveal gives us the same shock and delight."},"rel":"differ","link":"In contrast,","why":"Shakespeare lets us see the evil coming, which fills us with dread, while Darabont keeps the good news secret, which lifts us."},{"texts":["stlt","othello"],"mode":"theme","a":{"t":"stlt","s":"In Small Things Like These, Bill knows he will pay for taking Sarah out of the convent, yet he chooses his conscience over his family's security."},"b":{"t":"othello","s":"than Bill, Emilia pays for speaking out in Othello: she reveals the truth about the handkerchief and is stabbed by her own husband."},"rel":"degree","link":"to a far greater extent","why":"Both characters' courage has a cost, but Emilia pays with her life while Bill's price lies in an uncertain future."},{"texts":["stlt","othello"],"mode":"theme","a":{"t":"stlt","s":"In Small Things Like These, Bill asks whether the nuns have only as much power as people give them, suggesting that their control depends on the town's silence."},"b":{"t":"othello","s":"Othello, where Iago's power depends on others trusting him as 'honest Iago' and never questioning what he tells them."},"rel":"same","link":"This is echoed in","why":"In both texts power is not simply held but given by others, and it lasts only as long as no one challenges it."},{"texts":["othello","stlt"],"mode":"cc","a":{"t":"othello","s":"Authority in Othello lies with the state: the Duke and Senate judge Brabantio's complaint, and a letter from Venice can recall even a great general."},"b":{"t":"stlt","s":"the real authority in Small Things Like These is the Catholic Church, and even a respected businessman like Bill treads carefully around the Mother Superior."},"rel":"differ","link":"On the other hand,","why":"Power in Venice belongs to the state, while in Keegan's town it belongs to the Church."},{"texts":["othello","stlt"],"mode":"gvv","a":{"t":"othello","s":"At the end of Othello, Iago refuses to explain himself, leaving the disturbing sense that cruelty needs no good reason."},"b":{"t":"stlt","s":"Small Things Like These ends with questions unanswered, as we never learn what happens to Sarah, Bill's daughters or his business."},"rel":"same","link":"Likewise,","why":"Both endings refuse to tie everything up, leaving the audience or reader uneasy."},{"texts":["othello","stlt"],"mode":"gvv","a":{"t":"othello","s":"In Othello, the joy of the Cyprus reunion, when Othello says he could die 'most happy', ends with him putting out the light before he smothers Desdemona."},"b":{"t":"stlt","s":"the darkness of the convent in Small Things Like These is broken by kindness, as Bill takes Sarah out of the coal shed and walks her home."},"rel":"differ","link":"Conversely,","why":"Shakespeare lets the darkness put out the light, while Keegan lets one act of kindness break through the dark."},{"texts":["shawshank","stlt"],"mode":"theme","a":{"t":"shawshank","s":"Warden Norton keeps control through force, having Hadley shoot Tommy dead and threatening to destroy the library if Andy stops working for him."},"b":{"t":"stlt","s":"than Norton, the Mother Superior keeps control through politeness, calling the night in the coal shed a game and hinting that places at the school are scarce."},"rel":"degree","link":"more subtly","why":"Both institutions control people, but the convent works through hints while the prison uses open force."},{"texts":["stlt","shawshank"],"mode":"cc","a":{"t":"stlt","s":"In Small Things Like These, Bill has risen from nothing to owning a business, and he and Eileen fear losing their place by offending the nuns."},"b":{"t":"shawshank","s":"status in The Shawshank Redemption depends on the institution: inside, Brooks is the respected librarian, but outside he is an old man bagging groceries in a world with no use for him."},"rel":"same","link":"In the same way,","why":"In both worlds a person's standing depends on a powerful institution, which can take it away."},{"texts":["shawshank","stlt"],"mode":"cc","a":{"t":"shawshank","s":"In The Shawshank Redemption, the prisoners build their own community, and Red's group of friends becomes Andy's substitute family."},"b":{"t":"stlt","s":"the community in Small Things Like These knows what goes on in the convent but looks away, and people avoid Bill as he walks Sarah through the town."},"rel":"differ","link":"In contrast,","why":"Darabont's prisoners stand by one another, while Keegan's townspeople turn their backs on anyone who disturbs the order."},{"texts":["stlt","shawshank"],"mode":"gvv","a":{"t":"stlt","s":"Small Things Like These is hopeful about individuals but darker about society, since one man chooses to act while the town looks away."},"b":{"t":"shawshank","s":"Darabont's film suggests that institutions are corrupt but individuals can be good, as justice comes from Andy's patience and a newspaper, not from the courts."},"rel":"same","link":"Similarly,","why":"Both texts place their hope in one good person rather than in the institutions around them."},{"texts":["shawshank","stlt"],"mode":"gvv","a":{"t":"shawshank","s":"The Shawshank Redemption ends in bright sunlight, as Red is reunited with Andy on a beach in Mexico and the camera pulls back over the blue Pacific."},"b":{"t":"stlt","s":"than The Shawshank Redemption, Small Things Like These ends on hope: Bill reaches his door with Sarah, afraid but hopeful, and we never learn how Eileen or the town will respond."},"rel":"degree","link":"to a lesser degree","why":"Both endings are hopeful, but Keegan's open ending leaves the reader uneasy, while Darabont's reunion feels complete."}],"level":[{"texts":["sive","othello"],"mode":"theme","id":"lv-1","cue":"Power and lies in Sive and Othello","statement":"In both Sive and Othello, power belongs to those who control what others are allowed to know.","steps":[[["In Sive, Thomasheen makes Mike open Liam's letter and then burns it, so Sive never learns that Liam planned to marry her in secret that night."],["In Sive, Pats brings Nanna a letter from Liam on the day before the wedding, Mike finds out about it, and Thomasheen spots it.","f","It retells events but never says what the moment shows about power."],["In Sive, the stronger characters control the weaker ones in many different ways.","v","No key moment and no character named, so nothing is proven."]],[["Similarly, in Othello Iago controls what Othello believes, working through hints, pauses and pretended reluctance until Othello demands 'ocular proof'."],["Similarly, Othello has a bleak outlook, ending with four deaths and leaving the audience with pity rather than hope.","o","That's general vision and viewpoint, not the theme of power: it says nothing about who controls whom."],["Similarly, in Othello Emilia poisons Othello's mind by telling him that Desdemona gave the handkerchief to Cassio.","w","Wrong: Emilia gives the handkerchief to Iago and says nothing; it is Iago who poisons Othello's mind."]]]},{"texts":["othello","sive"],"mode":"cc","id":"lv-2","cue":"Women's place in Othello and Sive","statement":"In the worlds of Othello and Sive, a young woman's place is defined by the men in her life, though Desdemona, unlike Sive, dares to choose for herself.","steps":[[["Before the Senate, Desdemona tells her father that she sees 'a divided duty' and must now put her husband before him."],["Brabantio accuses Othello of witchcraft, Othello tells the Senate how Desdemona fell in love with him, and the Duke accepts the marriage.","f","It retells the Senate scene but never says what it shows about a woman's place."],["Women in Othello have to do what the men in their lives tell them.","v","A broad claim with no key moment or quotation to support it."]],[["In contrast, Sive has no say at all: Mena tells her she will have no name till she takes a husband, and announces that she will leave school."],["In contrast, Mena is a hard, bitter woman whose cruelty makes the audience dislike her intensely.","o","This is about Mena's personality and our reaction to her, not the rules of the society Sive lives in."],["In contrast, Sive has no say at all: Nanna tells her she will have no name till she takes a husband.","w","Wrong: it is Mena who says this; Nanna is Sive's only defender in the house."]]]},{"texts":["sive","othello"],"mode":"gvv","id":"lv-3","cue":"Crushed hope in Sive and Othello","statement":"Sive and Othello both offer moments of light only to crush them, which makes their visions even bleaker.","steps":[[["In Sive, moments of light are brief: Liam's secret visit offers a glimpse of young love, but Mike catches him and orders him away."],["Liam comes to see Sive in secret, Mike catches him and tells him to go, and then Mike calls for Mena.","f","It retells the scene but says nothing about the play's outlook."],["Sive has a few hopeful moments, but in the end things go badly for most of the characters.","v","No key moment is named, so it proves nothing about the play's vision."]],[["Similarly, in Othello the joy of the Cyprus reunion, when Othello says he could die 'most happy', is destroyed when he puts out the light and smothers Desdemona."],["Similarly, Venice is a Christian state at war with the Muslim Ottoman Turks, and Othello is a baptised Christian.","o","That's cultural context: it says nothing about whether the play's outlook is hopeful or bleak."],["Similarly, in Othello the joy of the Cyprus reunion is destroyed when Iago smothers Desdemona in her bed.","w","Wrong: Othello himself smothers Desdemona; Iago stabs his own wife, Emilia."]]]},{"texts":["shawshank","sive"],"mode":"theme","id":"lv-4","cue":"Escape in Shawshank and Sive","statement":"Both The Shawshank Redemption and Sive show characters trapped by the world around them, but only the film lets its hero escape into life.","steps":[[["In The Shawshank Redemption, Andy crawls through five hundred yards of sewer pipe during a thunderstorm and raises his arms in the pouring rain, finally free."],["At the morning count Andy's cell is empty, the warden throws a stone at the poster, and it tears straight through.","f","It retells the scene but never says what it shows about freedom."],["The Shawshank Redemption is a film about being trapped and wanting to be free.","v","It names the theme but gives no key moment to prove anything about it."]],[["In contrast, Sive's only escape from the match is death: on the eve of the wedding she runs out across the bog and drowns."],["In contrast, Sive dates from 1959 and is set in the Glavins' poor farmhouse kitchen in rural Co. Kerry.","o","True, but it is background about the play, not a comparison of how freedom is denied."],["In contrast, Sive escapes the match by running away with Liam on the eve of the wedding.","w","Wrong: Sive never learns of Liam's plan, because his letter is burned, and she drowns in a bog hole."]]]},{"texts":["sive","shawshank"],"mode":"cc","id":"lv-5","cue":"Institutions in Sive and Shawshank","statement":"The worlds of Sive and The Shawshank Redemption both fail the innocent, because their institutions serve the powerful rather than the weak.","steps":[[["In Sive, the only state institution mentioned, the county home, is used by Mena and Thomasheen as a threat to frighten Nanna into silence."],["Pats and Carthalawn arrive at the house, Nanna welcomes them, and Mena and Thomasheen refuse them food and money.","f","It retells events but says nothing about institutions or justice."],["There is a lot of injustice in Sive, and people do not get what they deserve.","v","A general claim with no key moment and no detail about how this world works."]],[["Similarly, the institution in The Shawshank Redemption blocks justice: when Tommy offers evidence that could free Andy, Warden Norton has the witness shot dead."],["Similarly, Andy is a quiet, patient man, and his friendship with Red is the heart of the film.","o","This describes Andy's character, not the law and institutions of his world."],["Similarly, in The Shawshank Redemption the courts finally free Andy once Tommy's evidence proves his innocence.","w","Wrong: Norton has Tommy shot before his evidence can help, and Andy frees himself by escaping."]]]},{"texts":["shawshank","sive"],"mode":"gvv","id":"lv-6","cue":"Dark openings in Shawshank and Sive","statement":"The Shawshank Redemption and Sive both open in a dark, hostile world, but only the film moves out of that darkness into hope.","steps":[[["Darabont opens the film at night, as a drunk Andy loads a revolver outside the house where his wife is with her lover, cut together with the trial that wrongly convicts him."],["Andy sits in his car, goes on trial, says he threw the gun into a river and is sentenced, and then Red goes before the parole board.","f","It retells the opening but doesn't say what outlook it creates."],["The start of The Shawshank Redemption is very dark and sets the tone for the film.","v","No key moment and no film technique, so it shows nothing about the vision."]],[["Sive also opens in a dark world, a cramped, poor kitchen where Nanna and Mena trade insults, but here the darkness only deepens until Sive's death."],["Sive also shows a poor family, where Mena resents paying for Sive's schooling instead of having her contribute to the house.","o","That's cultural context (money and education), not the play's outlook."],["Sive also opens in a dark world, as the play begins with Carthalawn's lament for the drowned Sive.","w","Wrong: the play opens with Nanna and Mena trading insults in the kitchen; the lament comes at the very end."]]]},{"texts":["stlt","sive"],"mode":"theme","id":"lv-7","cue":"Silence in STLT and Sive","statement":"Small Things Like These and Sive both show how silence makes ordinary people complicit, but only Keegan's hero finds the courage to break it.","steps":[[["In Small Things Like These, Bill accepts the Mother Superior's envelope of money and leaves the convent without ever asking about Sarah's baby."],["Bill makes an early Sunday delivery to the convent, finds a girl in the coal shed, and is brought in for tea with the Mother Superior.","f","It retells events but never says how the moment shows silence."],["Bill is a decent man, but at first he does not do much about what he sees.","v","No key moment is named, so the point stays unproven."]],[["Similarly, Mike in Sive knows the match is wrong, yet when Nanna begs him to stop it, he insists it is for the best and cannot look her in the face."],["Similarly, Sive is set in 1950s Kerry, where a man's worth is measured in land and cattle.","o","That's cultural context: it describes the world of the play, not the theme of silence."],["Similarly, Mike in Sive agrees with Nanna that the match is wrong and goes to the priest to stop it.","w","Wrong: Mike goes to the priest to arrange the wedding, insisting the match is for the best."]]]},{"texts":["sive","stlt"],"mode":"cc","id":"lv-8","cue":"The Church in Sive and STLT","statement":"In both Sive and Small Things Like These, the Church stands for respectability rather than protection, and no priest or nun steps in to save a vulnerable girl.","steps":[[["When Sive is found drowned, Mike's first thought is the priest and whether she can be buried in holy ground, since the Church then refused consecrated burial to suicides."],["At the end of Sive, Liam carries in Sive's body, Thomasheen and Seán Dóta slip away, and Carthalawn sings a song.","f","It retells the ending but says nothing about religion in this society."],["Religion is a big part of life in Sive, and it affects the characters in many ways.","v","A broad claim with no key moment and no sense of how the Church shapes lives."]],[["Similarly, the convent in Small Things Like These hides cruelty behind a respectable face, and Bill decides against bringing Sarah to the priest's house."],["Similarly, Bill's realisation that Ned was most likely his father is one of the most moving moments in the novella.","o","That's about Bill's personal story and our feelings, not the Church's place in this society."],["Similarly, in Small Things Like These, Bill brings Sarah to the priest's house, but the priest refuses to help her.","w","Wrong: Bill decides against bringing her to the priest's house and walks her home himself."]]]},{"texts":["sive","stlt"],"mode":"gvv","id":"lv-9","cue":"Endings in Sive and STLT","statement":"Although Sive and Small Things Like These both expose a cruel society, Keane's ending is bleak while Keegan's offers hope through one man's courage.","steps":[[["Keane's play ends with Sive drowned in a bog hole, the matchmaker and the bridegroom slipping away, and only Carthalawn's lament and Nanna's grief left."],["Mena finds that Sive has gone, Pats says he saw a girl on the bog, Liam carries in her body and Mike talks about the priest.","f","It lists the events of the ending but doesn't judge its outlook."],["The ending of Sive is very sad and leaves the audience feeling down.","v","No detail from the ending and no sense of what it says about people or society."]],[["In contrast, Small Things Like These ends with Bill walking Sarah barefoot through the town, feeling a happiness greater than any he has known."],["In contrast, Small Things Like These is set in New Ross, Co. Wexford, in the weeks before Christmas 1985.","o","That's the setting, not the outlook of the ending, so it is off the mode."],["In contrast, Small Things Like These ends with Eileen welcoming Sarah into the family home.","w","Wrong: the novella ends at Bill's door, before we see how Eileen or the town responds."]]]},{"texts":["othello","shawshank"],"mode":"theme","id":"lv-10","cue":"Defiance in Othello and Shawshank","statement":"In Othello and The Shawshank Redemption, standing up to those in power takes real courage, because those who defy authority pay a price for it.","steps":[[["In Othello, Emilia ignores Othello's sword and her husband's order to hold her peace, saying it is proper to obey him 'but not now', and dies for telling the truth."],["Emilia learns that Iago accused Desdemona, says that she found the handkerchief, and then Iago stabs her and flees.","f","This retells the scene but doesn't say what it shows about courage."],["Emilia is a brave character who does the right thing in the end.","v","It praises her but gives no key moment or detail as evidence."]],[["Similarly, Andy is punished for defying authority in The Shawshank Redemption, accepting two weeks in solitary rather than switch off the Mozart he is playing to the prisoners."],["Similarly, Red's voiceover guides how the viewer feels throughout The Shawshank Redemption.","o","That's how the film shapes our viewpoint, not the theme of courage and silence."],["Similarly, Andy is punished for defying authority, spending two years in solitary for playing Mozart over the loudspeakers.","w","Wrong: he is given two weeks in solitary, not two years."]]]},{"texts":["shawshank","othello"],"mode":"cc","id":"lv-11","cue":"Authority in Shawshank and Othello","statement":"In both The Shawshank Redemption and Othello, authority that seems total is finally overturned by a power from outside.","steps":[[["Warden Norton's rule at Shawshank collapses only when Andy's evidence reaches a newspaper: Hadley is arrested and Norton shoots himself."],["Posing as Randall Stephens, Andy takes money out of several banks and posts some things to a newspaper, and then the police arrive.","f","This retells events but never says what they show about authority."],["The people in charge at Shawshank are very powerful and abuse their position.","v","It names no one and no key moment, so it proves nothing."]],[["Likewise, in Othello even a great general's power depends on Venice: Lodovico brings orders recalling Othello, and at the end Lodovico strips him of his command."],["Likewise, Othello is a jealous man, and in the temptation scene his peace of mind collapses.","o","This is about Othello's character, not the power structures of his world."],["Likewise, in Othello the Duke sails to Cyprus at the end to arrest Iago and take Othello's command.","w","Wrong: it is Lodovico, the nobleman sent from Venice, who takes charge at the end, not the Duke."]]]},{"texts":["othello","shawshank"],"mode":"gvv","id":"lv-12","cue":"Endings in Othello and Shawshank","statement":"Othello and The Shawshank Redemption both end with evil exposed, yet Othello leaves us with pity while the film leaves us with hope.","steps":[[["Othello ends with order restored, but Lodovico makes Iago look on 'the tragic loading of this bed', and Iago refuses to explain his evil."],["In the last scene Lodovico takes away Othello's command, and Othello makes a speech, stabs himself and dies beside Desdemona.","f","It describes the ending but doesn't judge its outlook."],["The ending of Othello is tragic, as the endings of tragedies usually are.","v","A general claim about tragedy, with no detail from the ending."]],[["In contrast, The Shawshank Redemption ends in bright sunlight, as Red walks along the beach at Zihuatanejo to Andy and the camera pulls back over the blue Pacific."],["In contrast, The Shawshank Redemption is set in a prison whose warden claims the backing of the Bible.","o","That's cultural context, not the outlook of the film's ending."],["In contrast, The Shawshank Redemption ends with Andy released on parole and reunited with Red in Buxton.","w","Wrong: Andy escapes; it is Red who is paroled, and they meet again on a beach in Mexico."]]]},{"texts":["stlt","othello"],"mode":"theme","id":"lv-13","cue":"Freedom and choice in STLT and Othello","statement":"Small Things Like These and Othello both show a man's choices narrowing under pressure, but only Bill finds his way to freedom.","steps":[[["Lost in the fog, Bill asks an old man where the road will take him, and the answer, 'wherever you want to go', hints that he is freer than he believes."],["Bill drives away from the convent, takes a wrong turn in the fog and asks an old man for directions.","f","It retells what happens but not what it shows about freedom."],["Bill feels trapped in his life at first, but later on he becomes free.","v","No key moment or detail, so the point is just asserted."]],[["In contrast, Othello's choices close down once Iago's suggestions take hold, and within one scene he moves from love and trust to a vow of murderous revenge."],["In contrast, Othello is a Black general in white Venice, greeted with racist language from the first scene.","o","That's cultural context about race, not the theme of freedom and entrapment."],["In contrast, Othello's choices close down when Desdemona admits to an affair with Cassio in the temptation scene.","w","Wrong: Desdemona admits nothing, because there was no affair; Iago persuades Othello with hints and pretended reluctance."]]]},{"texts":["othello","stlt"],"mode":"cc","id":"lv-14","cue":"Women condemned in Othello and STLT","statement":"Both Othello and Small Things Like These present societies in which women are condemned and punished without a fair hearing.","steps":[[["Despite Emilia's oath that Desdemona is faithful, Othello treats his wife as 'that cunning whore of Venice' and Emilia as a brothel-keeper."],["Othello questions Emilia, then speaks to Desdemona, and afterwards Desdemona kneels to Iago to ask how she can win Othello back.","f","It retells the scene without saying what it shows about how women are treated."],["Women in Othello have a hard time and are often treated unfairly.","v","No key moment or quotation, so there is no evidence."]],[["Similarly, unmarried mothers in Small Things Like These are punished without any court or hearing: Sarah is locked in the coal shed and her fourteen-week-old baby is taken from her."],["Similarly, Bill is a quiet, decent man whose shame grows after he leaves Sarah at the convent.","o","This is about Bill's character and feelings, not how his society treats women."],["Similarly, in Small Things Like These, Bill's own mother is sent to the convent laundry when she becomes pregnant at sixteen.","w","Wrong: Mrs Wilson kept Bill's mother on as a servant when her own family would have nothing to do with her."]]]},{"texts":["stlt","othello"],"mode":"gvv","id":"lv-15","cue":"Shaping our view in STLT and Othello","statement":"Keegan and Shakespeare both make the audience feel the pressure on their characters, though only Small Things Like These releases us into hope.","steps":[[["Keegan makes Eileen's warning that 'there's things you have to ignore, so you can keep on' sound reasonable, so we feel the pressure of silence before Bill acts."],["Bill tells Eileen what he saw at the convent, and she says that the nuns always pay their bills and that their own girls are well minded.","f","It retells the conversation but says nothing about how Keegan shapes our view."],["Keegan writes in a way that really makes the reader think about the story.","v","It could be said of any book: no technique and no key moment."]],[["Similarly, Shakespeare uses dramatic irony to trap us: Iago reveals his plan in soliloquy while Othello calls him 'honest Iago', so we watch the disaster unfold, helpless."],["Similarly, Venice is ruled by the Duke and Senate, who need Othello to defend Cyprus against the Turks.","o","That's cultural context about power in Venice, not the play's outlook."],["Similarly, Shakespeare keeps Iago's plan hidden from the audience until the final scene, so the ending comes as a shock.","w","Wrong: Iago tells us his plan in soliloquy; only the characters are kept in the dark."]]]},{"texts":["shawshank","stlt"],"mode":"theme","id":"lv-16","cue":"Quiet courage in Shawshank and STLT","statement":"In The Shawshank Redemption and Small Things Like These, courage is shown not through grand gestures but through quiet acts of humanity.","steps":[[["On his first night, Andy makes no sound while another man breaks down, and the next morning he asks the dead prisoner's name while the others shrug off the killing."],["On Andy's first night, Heywood and the others taunt the new arrivals until one breaks down, and Captain Hadley beats him.","f","It retells the scene but doesn't explain how it shows Andy's courage."],["Andy is a brave character who never gives up throughout the film.","v","No key moment is given, so the point is just an opinion."]],[["Likewise, Bill's courage is an ordinary act: he walks Sarah home through the town, asking himself whether there is any point in being alive without helping one another."],["Likewise, Small Things Like These is set in New Ross in 1985, a time of closing businesses and emigration.","o","That's the novella's cultural context, not the theme of courage."],["Likewise, Bill's courage shows when he confronts the Mother Superior over tea and demands to see Sarah's baby.","w","Wrong: at the tea Bill goes along with the Mother Superior and leaves without asking about the baby."]]]},{"texts":["stlt","shawshank"],"mode":"cc","id":"lv-17","cue":"Religious hypocrisy in STLT and Shawshank","statement":"In both Small Things Like These and The Shawshank Redemption, a religious public face hides the cruelty of a powerful institution.","steps":[[["The convent in Small Things Like These is admired for its beauty, yet behind walls topped with broken glass Bill finds a girl locked all night in the freezing coal shed."],["Bill delivers coal to the convent early on a Sunday and finds a frightened girl, who asks him about her baby.","f","It retells the scene but never connects it to the Church's power or hypocrisy."],["The Church in the novella is not as good as it seems.","v","Too vague: no key moment, no detail, and nothing on how the Church works in this society."]],[["Similarly, Warden Norton greets new prisoners at Shawshank with talk of discipline and the Bible, yet he runs a corrupt business and arranges a murder."],["Similarly, the sudden reveal of Andy's escape is the most exciting moment in the film.","o","That's about the film's effect on the viewer, not religion or power in Shawshank's world."],["Similarly, Warden Norton preaches the Bible to new prisoners, but it is Captain Hadley who orders Tommy's murder.","w","Wrong: Norton orders the killing; Hadley carries it out."]]]},{"texts":["shawshank","stlt"],"mode":"gvv","id":"lv-18","cue":"Light in dark places in Shawshank and STLT","statement":"The Shawshank Redemption and Small Things Like These both find light in dark places, suggesting that small moments of beauty and kindness can sustain people.","steps":[[["When Andy plays Mozart over the loudspeakers, the prisoners stand still in the yard to listen, and Red's voiceover says that for a brief moment every man in Shawshank felt free."],["Andy gets books and records for the library, locks himself in the office, plays a record and is sent to solitary for two weeks.","f","It retells the scene but doesn't say what it shows about the film's outlook."],["There are some happy moments in the film that make it less depressing to watch.","v","No key moment is named, so there is no evidence for the film's vision."]],[["Similarly, Keegan finds light in quiet kindness: Mrs Wilson kept Bill's pregnant teenage mother on when her own family would have nothing more to do with her."],["Similarly, the nuns in Small Things Like These run the laundry and the best girls' school in the town.","o","That's cultural context, not the novella's outlook."],["Similarly, Keegan finds light in quiet kindness: Bill's mother took in Mrs Wilson when she was a poor widow with nowhere to go.","w","Wrong: it was the other way round; Mrs Wilson kept Bill's pregnant teenage mother on as a servant."]]]}],"chains":[{"texts":["othello","sive","shawshank"],"mode":"theme","title":"Power in Othello, Sive and Shawshank","steps":["In Othello, Sive and The Shawshank Redemption, real power often lies not with those who seem to be in charge but with those who can manipulate them.","In Othello, Iago, a mere ensign, works on his general through hints, pauses and pretended reluctance until Othello vows revenge and makes him his lieutenant.","Similarly, Mike is the man of the house in name only in Sive, as Mena, tempted by Seán Dóta's £200, works on him until he gives in to the match.","The Shawshank Redemption turns this around: unlike Iago and Mena, Andy, a mere prisoner, uses his financial skill against the corrupt warden, taking the money he had hidden for Norton.","Ultimately, hidden power destroys in Othello and Sive but frees Andy in Shawshank, and Othello is the bleakest of the three, since Iago never even explains why."],"why":"In Othello, Sive and The Shawshank Redemption, real <b>power</b> often lies not with those who seem to be in charge but with those who can <b>manipulate</b> them. In Othello, Iago, a mere ensign, works on his general through <b>hints</b>, pauses and pretended reluctance until Othello vows revenge and makes him his lieutenant. Similarly, Mike is the man of the house in name only in Sive, as Mena, tempted by Seán Dóta's <b>£200</b>, works on him until he gives in to the match. The Shawshank Redemption turns this around: unlike Iago and Mena, Andy, a mere prisoner, uses his <b>financial skill</b> against the <b>corrupt warden</b>, taking the money he had hidden for Norton. Ultimately, hidden power destroys in Othello and Sive but frees Andy in Shawshank, and Othello is the bleakest of the three, since Iago never even explains why."},{"texts":["stlt","othello","shawshank"],"mode":"theme","title":"Courage and silence in STLT, Othello and Shawshank","steps":["All three texts show that silence protects the powerful, and that breaking it takes a courage which always comes at a cost.","In Small Things Like These, Bill finally breaks the town's silence on Christmas Eve, walking a barefoot Sarah home even though he knows he will pay for it.","Likewise, Emilia breaks her silence in Othello, defying her husband's order to hold her peace, but her courage costs her life when Iago stabs her.","Speaking out is punished just as harshly in The Shawshank Redemption, where Andy is thrown into solitary for challenging the warden and Tommy is shot for agreeing to testify.","Of the three, Keegan offers the most hopeful view of courage, since Bill's act brings him a happiness greater than any he has known."],"why":"All three texts show that <b>silence</b> protects the powerful, and that breaking it takes a <b>courage</b> which always comes at a cost. In Small Things Like These, Bill finally breaks the town's silence on Christmas Eve, walking a barefoot Sarah home even though he knows he will pay for it. Likewise, Emilia breaks her silence in Othello, defying her husband's order to <b>hold her peace</b>, but her courage costs her life when Iago stabs her. Speaking out is punished just as harshly in The Shawshank Redemption, where Andy is thrown into <b>solitary</b> for challenging the warden and Tommy is shot for agreeing to testify. Of the three, Keegan offers the most hopeful view of courage, since Bill's act brings him a <b>happiness</b> greater than any he has known."},{"texts":["sive","othello","stlt"],"mode":"cc","title":"Women and marriage in Sive, Othello and STLT","steps":["In all three worlds, a woman's worth is judged through marriage, and women who fall outside its rules, or are suspected of breaking them, are punished.","In Sive, Mena tells Sive she will have no name till she takes a husband, using her birth outside marriage as a weapon to force the match.","Marriage gives no protection in Othello either: Othello treats Desdemona as 'that cunning whore of Venice' and later smothers her, and Iago stabs Emilia for disobeying him.","Small Things Like These shows this punishment at its most systematic, as unmarried mothers like Sarah are locked away and their babies taken, while the shame never falls on the fathers.","Ultimately, all three expose a world where women pay for men's judgements, though only Keegan shows a man, Bill, refusing to look away."],"why":"In all three worlds, a woman's worth is judged through <b>marriage</b>, and women who fall outside its rules, or are suspected of breaking them, are punished. In Sive, Mena tells Sive she will have <b>no name</b> till she takes a husband, using her birth outside marriage as a weapon to force the match. Marriage gives <b>no protection</b> in Othello either: Othello treats Desdemona as 'that cunning whore of Venice' and later smothers her, and Iago stabs Emilia for disobeying him. Small Things Like These shows this punishment at its most systematic, as unmarried mothers like Sarah are <b>locked away</b> and their babies taken, while the shame never falls on the fathers. Ultimately, all three expose a world where women pay for <b>men's judgements</b>, though only Keegan shows a man, Bill, refusing to look away."},{"texts":["stlt","shawshank","sive"],"mode":"cc","title":"The Church in STLT, Shawshank and Sive","steps":["In all three texts, religion serves power and respectability rather than protecting the vulnerable.","In Small Things Like These, the convent is admired for its beauty, yet behind its walls topped with broken glass girls are locked up and a young mother's baby is taken.","Similarly, in The Shawshank Redemption, Warden Norton greets new prisoners with talk of discipline and the Bible, yet he runs a corrupt business and arranges a murder.","Less overtly than either, the Church in Sive stands for respectability: when Sive drowns, Mike's first thought is whether she can be buried in holy ground.","Of the three, Keegan's criticism is the most direct, because the cruelty is carried out by the Church itself rather than merely in its name."],"why":"In all three texts, religion serves power and <b>respectability</b> rather than protecting the vulnerable. In Small Things Like These, the convent is admired for its beauty, yet behind its walls topped with <b>broken glass</b> girls are locked up and a young mother's baby is taken. Similarly, in The Shawshank Redemption, Warden Norton greets new prisoners with talk of discipline and <b>the Bible</b>, yet he runs a corrupt business and arranges a murder. Less overtly than either, the Church in Sive stands for respectability: when Sive drowns, Mike's first thought is whether she can be buried in <b>holy ground</b>. Of the three, Keegan's criticism is the most direct, because the cruelty is carried out by <b>the Church itself</b> rather than merely in its name."},{"texts":["sive","stlt","shawshank"],"mode":"gvv","title":"Endings in Sive, STLT and Shawshank","steps":["The endings of the three texts reveal very different visions: bleak in Sive, hopeful but uncertain in Small Things Like These, and triumphantly hopeful in The Shawshank Redemption.","Sive ends with a drowned girl, Carthalawn's lament and Nanna's grief, while the matchmaker and the bridegroom slip away and no one is brought to account.","In contrast, Small Things Like These ends with Bill walking Sarah home, feeling a happiness greater than any he has known, though we never learn how Eileen or the town responds.","The Shawshank Redemption goes further still, ending in bright sunlight as Red walks along the beach at Zihuatanejo to Andy and the camera pulls back over the blue Pacific.","Ultimately, the hope in these texts comes from individuals rather than society, which is why Sive, where goodness is powerless, leaves the bleakest vision of all."],"why":"The endings of the three texts reveal very different visions: <b>bleak</b> in Sive, hopeful but uncertain in Small Things Like These, and triumphantly hopeful in The Shawshank Redemption. Sive ends with a drowned girl, Carthalawn's <b>lament</b> and Nanna's grief, while the matchmaker and the bridegroom slip away and no one is brought to account. In contrast, Small Things Like These ends with Bill walking Sarah home, feeling a <b>happiness</b> greater than any he has known, though we never learn how Eileen or the town responds. The Shawshank Redemption goes further still, ending in <b>bright sunlight</b> as Red walks along the beach at Zihuatanejo to Andy and the camera pulls back over the blue Pacific. Ultimately, the hope in these texts comes from <b>individuals</b> rather than society, which is why Sive, where goodness is powerless, leaves the bleakest vision of all."},{"texts":["othello","shawshank","stlt"],"mode":"gvv","title":"Light and dark in Othello, Shawshank and STLT","steps":["All three texts set moments of light against darkness, but they differ sharply over which one wins.","In Othello, the joy of the Cyprus reunion, when Othello says he could die 'most happy', is destroyed when he puts out the light before smothering Desdemona.","In contrast, The Shawshank Redemption moves from grey prison walls and night scenes like Tommy's killing to the open, sunlit blue of the Pacific in its final shot.","Small Things Like These sits between the two, setting the warmth of the Furlong kitchen at Christmas against the girl locked all night in the convent's coal shed.","Ultimately, light is destroyed in Othello, triumphs in Shawshank and survives only uncertainly in Keegan's novella, which makes the film the most hopeful of the three."],"why":"All three texts set moments of <b>light</b> against darkness, but they differ sharply over which one wins. In Othello, the joy of the Cyprus reunion, when Othello says he could die <b>'most happy'</b>, is destroyed when he puts out the light before smothering Desdemona. In contrast, The Shawshank Redemption moves from grey prison walls and night scenes like Tommy's killing to the open, <b>sunlit blue</b> of the Pacific in its final shot. Small Things Like These sits between the two, setting the <b>warmth</b> of the Furlong kitchen at Christmas against the girl locked all night in the convent's <b>coal shed</b>. Ultimately, light is destroyed in Othello, triumphs in Shawshank and survives only uncertainly in Keegan's novella, which makes the film the most hopeful of the three."}],"spot":[{"texts":["sive","shawshank","othello"],"mode":"theme","ask":"Tap the line an examiner wouldn't reward.","lines":["In Sive, The Shawshank Redemption and Othello, those in power silence anyone who threatens their control.","In Sive, the travelling men Pats and Carthalawn come to the house, Nanna welcomes them, and Mena and Thomasheen refuse them food and money.","Similarly, in The Shawshank Redemption Andy is thrown into solitary for challenging the warden, and Tommy is shot dead after agreeing to testify.","Othello goes further, as Iago stabs his own wife, Emilia, when she defies his order to be silent and reveals the truth about the handkerchief.","Ultimately, all three suggest that power at its worst depends on silence, and that those who speak the truth pay a terrible price."],"weak":1,"kind":"Plot summary","why":"It retells the travellers' visit but never says how the powerful silence anyone, so it proves nothing.","fix":"In Sive, when Nanna challenges the match, Mena and Thomasheen bully her and threaten her with the county home."},{"texts":["othello","shawshank","sive"],"mode":"cc","ask":"Tap the line an examiner wouldn't reward.","lines":["In all three worlds, the institutions meant to protect people fail them, so justice is either absent or arrives too late.","In Othello, Venice first gives Othello a fair hearing, yet justice returns only after Desdemona's murder, when Lodovico strips him of his command.","Similarly, the law fails Andy from the start of The Shawshank Redemption, convicting him of two murders he did not commit.","In Sive, Mena is a hard, bitter woman, and the audience comes to dislike her intensely.","Of the three, Sive's world is the harshest, because there is no outside force at all to bring the guilty to account."],"weak":3,"kind":"Off the mode","why":"It is about Mena's personality and our feelings, not law or justice in Sive's world.","fix":"In Sive, the law is absent altogether: no guard, court or official appears, and Thomasheen and Seán Dóta slip away unpunished after Sive's death."},{"texts":["shawshank","othello","sive"],"mode":"gvv","ask":"Tap the line an examiner wouldn't reward.","lines":["All three texts show that good people exist, but they differ sharply on whether goodness can survive.","In The Shawshank Redemption, Andy's patience and the truth he sends to a newspaper bring down the corrupt warden, suggesting that individuals can be good even when institutions are not.","In contrast, goodness cannot save itself in Othello, where Desdemona stays loyal to the end and Emilia dies when Othello stabs her for speaking out.","Sive is bleaker still, as the goodness of Liam, Nanna and the travelling men is powerless against the money that drives the match.","Ultimately, only Darabont lets goodness win, which is why his film feels hopeful while the two plays leave us with grief and pity."],"weak":2,"kind":"Wrong fact","why":"Wrong: it is Iago, not Othello, who stabs Emilia when she reveals the truth.","fix":"In contrast, goodness cannot save itself in Othello, where Desdemona stays loyal to the end and Emilia dies defending her mistress's honour."},{"texts":["stlt","sive","othello"],"mode":"theme","ask":"Tap the line an examiner wouldn't reward.","lines":["In Small Things Like These, Sive and Othello, silence allows cruelty to continue, and courage means being willing to act against it.","In Small Things Like These, Bill first holds out his empty hands to the girl in the chapel, but on Christmas Eve he goes back for Sarah and walks her home.","In contrast, Mike in Sive never breaks his silence, and after Thomasheen burns Liam's letter he does nothing to warn Sive.","Emilia's silence in Othello lasts until the final scene, when she defies her husband's order to hold her peace, but by then Desdemona is dead.","In the end, Bill feels a happiness greater than any he has known, even though he knows he will pay for what he has done."],"weak":4,"kind":"No comparison","why":"It talks about one text only, so the evaluation never compares the three texts or answers the question.","fix":"Ultimately, only Keegan lets courage come in time to save someone, which makes Bill's walk home far more hopeful than Mike's silence or Emilia's late defiance."},{"texts":["othello","stlt","sive"],"mode":"cc","ask":"Tap the line an examiner wouldn't reward.","lines":["All three texts are set in societies where some people have more power than others.","In Othello, the Duke and Senate judge Brabantio's complaint, and a letter from Venice can recall even a great general.","In contrast, the real authority in Small Things Like These is the Catholic Church, and Bill understands the Mother Superior's remark that school places are scarce as a warning.","In Sive, authority belongs to whoever has money, as Seán Dóta's wealth buys him a bride and the matchmaker Thomasheen brokers the deal for his own gain.","Of the three worlds, Keegan's is the most frightening, because its power is never openly stated, yet the whole town defers to it."],"weak":0,"kind":"Vague","why":"It is true of almost any text: it names no source of power and sets up no real comparison.","fix":"Authority in Othello lies with the state, but in Small Things Like These it lies with the Church, and in Sive with whoever controls money."},{"texts":["sive","othello","stlt"],"mode":"gvv","ask":"Tap the line an examiner wouldn't reward.","lines":["Each text opens in a dark or troubled world, but only Small Things Like These moves from that darkness towards hope.","Keane's play opens in a cramped, poor kitchen where Nanna and Mena trade insults, and Sive, home from school, is treated as a burden.","Othello also opens in darkness, at night, with Iago's hatred and racist shouts, though Othello's calm dignity before the Senate suggests that goodness may win out.","Small Things Like These starts with Bill doing his rounds, then the town gathers for the Christmas lights, and the Furlongs bake the Christmas cake at home.","Ultimately, both plays move from these dark openings to tragedy, while Keegan's muted start prepares for a hopeful, if uncertain, ending."],"weak":3,"kind":"Plot summary","why":"It lists events from the opening chapters but never says what outlook they create.","fix":"Small Things Like These opens in a cold, struggling town where Bill worries about money and wonders what his life is for, though his family's warmth softens the mood."},{"texts":["shawshank","stlt","sive"],"mode":"theme","ask":"Tap the line an examiner wouldn't reward.","lines":["In The Shawshank Redemption, Small Things Like These and Sive, characters are trapped by the institutions and people around them, but not all of them find a way out.","The Shawshank Redemption is set in a state prison in Maine between 1947 and 1966, and its warden claims the backing of the Bible.","Similarly, the girls in Small Things Like These are prisoners, and Sarah is found locked in the convent's coal shed not once but twice.","Sive is trapped too, but Liam's letter offering escape is burned before she can read it, so the only freedom left to her is death in the bog.","Ultimately, Andy breaks free and Bill leads Sarah out, but Sive's one way out is destroyed, which makes Keane's play the darkest of the three."],"weak":1,"kind":"Off the mode","why":"It describes the film's setting and the warden's religion, which is cultural context, not a key moment about freedom or entrapment.","fix":"In The Shawshank Redemption, Brooks is so 'institutionalized' after fifty years that he cannot cope outside, while Andy escapes through five hundred yards of sewer pipe."},{"texts":["sive","stlt","shawshank"],"mode":"cc","ask":"Tap the line an examiner wouldn't reward.","lines":["In all three worlds, money shapes people's choices: it tempts the greedy, frightens the insecure and corrupts the powerful.","In Sive, poverty drives the tragedy, as Mena, who married to escape a desperately poor home, will not refuse Seán Dóta's £200.","Similarly, hard times in Small Things Like These make families cling to what they have, and Eileen argues that only wealth gave Mrs Wilson the freedom to be kind.","Worse still, in The Shawshank Redemption money corrupts the institution itself, as Captain Hadley relies on Andy to hide his illegal profits and so will not let Tommy's evidence set him free.","Of the three, Keegan shows most clearly how money buys silence, since fear of losing what they have keeps decent people quiet."],"weak":3,"kind":"Wrong fact","why":"Wrong: it is Warden Norton, not Captain Hadley, who relies on Andy to hide his illegal profits.","fix":"Worse still, in The Shawshank Redemption money corrupts the institution itself, as Warden Norton relies on Andy to hide his illegal profits and so will not let Tommy's evidence set him free."},{"texts":["stlt","shawshank","sive"],"mode":"gvv","ask":"Tap the line an examiner wouldn't reward.","lines":["Small Things Like These and The Shawshank Redemption both place their hope in individuals rather than institutions, while Sive shows good individuals defeated.","Keegan is hopeful about individuals but darker about society: in Small Things Like These one man chooses to act, while the town looks away.","The Shawshank Redemption is a hopeful film, and Red ends it with the words 'I hope'.","In contrast, the goodness of Liam, Nanna and the travelling men in Sive is powerless against money, which deepens the play's bleakness.","Ultimately, all three suggest that institutions fail people, but only Keegan and Darabont believe that one good person can make a difference."],"weak":2,"kind":"No comparison","why":"It describes one text on its own, with no link to the others, and says nothing about hope in individuals.","fix":"Similarly, in The Shawshank Redemption justice comes not from the courts but from Andy's patience and the evidence he sends to a newspaper."},{"texts":["othello","shawshank","stlt"],"mode":"theme","ask":"Tap the line an examiner wouldn't reward.","lines":["The most effective power in all three texts works quietly, through persuasion, knowledge and hints rather than force.","In Othello, Iago, a mere ensign, uses hints, pauses and pretended reluctance in the temptation scene until his general vows murderous revenge.","Similarly, Andy discovers in The Shawshank Redemption that knowledge is power, when his tax advice turns Captain Hadley from threatening him into supplying beer for his fellow prisoners.","More subtly still, the Mother Superior in Small Things Like These controls Bill's visit by calling the night in the coal shed a game and hinting that school places are scarce.","So power is a very important theme in all three texts and it affects all of the characters in different ways."],"weak":4,"kind":"Vague","why":"It repeats that power matters without saying what the comparison shows or which text goes furthest.","fix":"Ultimately, Iago's power is the most frightening, because it needs nothing but words and trust, while Andy uses his to help others and the Mother Superior's depends on silence."},{"texts":["shawshank","stlt","othello"],"mode":"cc","ask":"Tap the line an examiner wouldn't reward.","lines":["The communities in all three texts shape who survives: chosen friendships protect people, while families and towns can turn their backs.","In The Shawshank Redemption, the prisoners build their own community, and Red's group of friends becomes Andy's substitute family, ending in a reunion in Mexico.","In Small Things Like These, Bill pays for his men's dinner on Christmas Eve, Mrs Kehoe asks him about the Mother Superior, and then he walks on to the convent.","In Othello, family ties break completely, as Brabantio disowns Desdemona, and far from home her only real companion is Emilia.","Of the three, Darabont offers the most hopeful view of community, since only his chosen family survives intact."],"weak":2,"kind":"Plot summary","why":"It strings events together but never says what they show about the community in Keegan's town.","fix":"In contrast, Keegan's townspeople know what goes on in the convent but look away, and on Christmas Eve people avoid Bill as he walks Sarah through the town."},{"texts":["stlt","othello","shawshank"],"mode":"gvv","ask":"Tap the line an examiner wouldn't reward.","lines":["Each writer or director shapes our outlook by controlling what we know, and so decides whether we finish in hope, dread or uncertainty.","In Small Things Like These, the nuns run the laundry and the best girls' school, so they have enormous power over the town.","In contrast, Shakespeare tells us too much in Othello: Iago reveals his plan in soliloquy while Othello calls him 'honest Iago', so we watch helplessly as disaster approaches.","Darabont, on the other hand, hides Andy's escape from the viewer as well as from Red, so its sudden reveal gives us the same shock and delight.","Ultimately, Shakespeare's dramatic irony creates the bleakest experience, while Darabont's surprise makes his vision the most uplifting of the three."],"weak":1,"kind":"Off the mode","why":"It describes who holds power in Keegan's town, which is cultural context, not how Keegan shapes the reader's outlook.","fix":"Keegan ends the novella at Bill's door, so we never learn what happens to Sarah, his daughters or his business, which leaves us uplifted but uneasy."}]},"glossary":[{"id":"extent","kind":"task","match":["the extent to which","the extent","extent"],"term":"the extent to which","def":"How far, or how much. Don't just say yes or no: say how much it's true, and where it's more true or less true.","do":"Give a judgement of degree: completely, largely, partly, hardly at all, and in which text most."},{"id":"discuss","kind":"task","match":["discuss"],"term":"discuss","def":"Talk it through, point by point, with evidence. You can agree, disagree, or say it's partly true.","do":"Make a clear argument and back every point with a key moment."},{"id":"compare","kind":"task","match":["compare"],"term":"compare","def":"Show how the texts are alike and how they're different on this point.","do":"Bring the texts together inside each paragraph: similarly, in contrast, to a greater extent."},{"id":"contrast","kind":"task","match":["contrast"],"term":"contrast","def":"Show the differences between the texts.","do":"Put the texts side by side and say how they differ, and why it matters."},{"id":"identify","kind":"task","match":["identify"],"term":"identify","def":"Name it clearly, so the examiner knows exactly what you're writing about.","do":"Say what it is in your first sentence."},{"id":"explain","kind":"task","match":["explain"],"term":"explain","def":"Say why or how, not just what.","do":"After each point, add because..., which shows..."},{"id":"develop","kind":"task","match":["develop your response","develop your answer"],"term":"develop your response","def":"Build each point out properly with evidence and explanation, rather than listing points.","do":"Point, then a key moment, then what it shows."},{"id":"reference","kind":"task","match":["with reference to","in relation to"],"term":"with reference to","def":"Using evidence from: key moments, quotes and details from the texts.","do":"Ground every point in a specific moment."},{"id":"chosen","kind":"task","match":["your chosen texts","your chosen text"],"term":"your chosen texts","def":"The texts you studied for the comparative: for you, three of Sive, Othello, The Shawshank Redemption and Small Things Like These.","do":"Name them, with their authors or director, in your introduction."},{"id":"statement","kind":"task","match":["the above statement","this statement","the statement"],"term":"the statement","def":"The quotation given at the start of the question.","do":"Agree, disagree, or partly agree with it, and say so early."},{"id":"cc","kind":"topic","match":["cultural contexts","cultural context"],"term":"cultural context","def":"The world of the text: who has power, what people value, and how they live: money, class, religion, family, men and women."},{"id":"gvv","kind":"topic","match":["general vision and viewpoint"],"term":"general vision and viewpoint","def":"The text's outlook on life: is it bleak or hopeful, and how does that change from the opening to the ending?"},{"id":"theme","kind":"topic","match":["theme or issue","same theme","theme"],"term":"theme or issue","def":"A big idea the text explores, like power, love, freedom or identity, and what it says about it."},{"id":"mobility","kind":"topic","match":["social mobility"],"term":"social mobility","def":"Being able to move up (or down) from one social position to another: from poor to rich, from a servant to a master, from nobody to somebody. Ask: can people in this world change where they stand, and what does it cost them?","eg":{"sive":"Hardly any. A poor girl's only way up is a marriage for money: Mena married Mike to escape poverty, and Sive is to be married off to old Seán Dóta for his money.","othello":"Othello rose from slavery to general of Venice's army, yet Venice still treats him as an outsider. Iago is bitter that Cassio was promoted over him.","shawshank":"Inside, the only way up is being useful to the powerful: Andy goes from new arrival to the warden's banker. The only way out is parole or escape.","stlt":"Bill rose from the son of an unmarried servant girl to owner of the coal yard, thanks to Mrs Wilson's kindness. But his place depends on staying on the right side of the nuns."}},{"id":"position","kind":"topic","match":["different social positions","social positions","social position","positions"],"term":"social position","def":"Where a person stands in their society: their rank, class or status, and how others treat them because of it."},{"id":"class","kind":"topic","match":["social class","class"],"term":"social class","def":"A group of people with similar money, work and standing: for example, landowners, labourers, the poor."},{"id":"division","kind":"topic","match":["social divisions","social division","divisions","division"],"term":"social division","def":"A line that splits a society into groups: rich and poor, men and women, insiders and outsiders, the powerful and the powerless."},{"id":"society","kind":"topic","match":["societies","society","societal"],"term":"society","def":"The world of people the text shows: its community, its rules, and who belongs where."},{"id":"status","kind":"topic","match":["status"],"term":"status","def":"Your rank or importance in the eyes of others."},{"id":"power","kind":"topic","match":["holds power","power","powerless"],"term":"power","def":"Who controls people and events, and how: through money, authority, violence or words.","eg":{"sive":"Money and the matchmaker: Mena and Thomasheen arrange Sive's life for Seán Dóta's £200.","othello":"Venice's Senate and Othello's command on one side; Iago's power is all in his words.","shawshank":"Warden Norton and the guards: discipline, violence and the Bible.","stlt":"The Church: the nuns run the convent and the school, and the town keeps quiet."}},{"id":"values","kind":"topic","match":["prevailing values","values"],"term":"values","def":"What people believe matters most: money, land, faith, family, reputation, love."},{"id":"attitudes","kind":"topic","match":["attitudes","attitude"],"term":"attitudes","def":"How people think and feel about something, and how that shows in what they do."},{"id":"beliefs","kind":"topic","match":["personal beliefs","personal belief","beliefs","belief"],"term":"beliefs","def":"What a person holds to be true or right."},{"id":"norms","kind":"topic","match":["societal norms","norms"],"term":"norms","def":"The unwritten rules of how people are expected to behave in that society."},{"id":"dominant","kind":"topic","match":["dominant position","dominant"],"term":"dominant","def":"On top: the most powerful or most common."},{"id":"patriarchal","kind":"topic","match":["patriarchal"],"term":"patriarchal","def":"A society where men hold the power and women are expected to obey them.","eg":{"othello":"Desdemona is treated as her father's property, then her husband's. Emilia's speech in the willow scene pushes back against it.","sive":"Sive has no say in her own marriage: it's arranged over her head for money. A woman has no name till she takes a husband, Mena tells her."}},{"id":"maledom","kind":"topic","match":["male-dominated"],"term":"male-dominated","def":"Run by men, with men in the positions of power."},{"id":"conform","kind":"topic","match":["conforming","conform"],"term":"conforming","def":"Going along with what everyone else expects, even when you disagree."},{"id":"intervention","kind":"topic","match":["human intervention","intervention"],"term":"intervention","def":"Someone stepping in to change what happens."},{"id":"catalyst","kind":"topic","match":["catalyst"],"term":"catalyst","def":"Something that sparks a change or makes it happen faster."},{"id":"nature","kind":"topic","match":["human nature"],"term":"human nature","def":"What people are really like, deep down: kind or cruel, brave or selfish."},{"id":"condition","kind":"topic","match":["human condition"],"term":"the human condition","def":"What it's like to be human: love, loss, fear, hope, death."},{"id":"contradictory","kind":"topic","match":["contradictory"],"term":"contradictory","def":"Opposite or clashing: two things that can't both seem true at once."},{"id":"complexity","kind":"topic","match":["complexity","complex"],"term":"complexity","def":"Having many sides; not simple or black and white."},{"id":"resilience","kind":"topic","match":["resilience"],"term":"resilience","def":"The strength to keep going and recover after hardship.","eg":{"shawshank":"Andy: nearly twenty years of digging with a tiny rock hammer, and he never gives up hope."}},{"id":"integrity","kind":"topic","match":["personal integrity","integrity"],"term":"integrity","def":"Being honest and sticking to what you believe is right, even when it costs you."},{"id":"compassion","kind":"topic","match":["compassion"],"term":"compassion","def":"Feeling for other people's suffering and wanting to help.","eg":{"stlt":"Bill can't stop thinking about the girls at the convent, and in the end he brings Sarah home."}},{"id":"kindness","kind":"topic","match":["kindness"],"term":"kindness","def":"Being good to others, often in small, everyday ways."},{"id":"idealistic","kind":"topic","match":["idealistic","idealism"],"term":"idealistic","def":"Showing life as better or more perfect than it really is."},{"id":"realistic","kind":"topic","match":["realistic"],"term":"realistic","def":"Showing life as it really is, warts and all."},{"id":"universal","kind":"topic","match":["universal"],"term":"universal","def":"True for people everywhere and at any time, not just in the world of the text."},{"id":"paradoxical","kind":"topic","match":["paradoxical"],"term":"paradoxical","def":"Seeming to contradict itself but still true, like a prison that gives a man hope."},{"id":"disadvantaged","kind":"topic","match":["disadvantaged","disempowered"],"term":"disadvantaged","def":"Given less of a chance than others; disempowered means having your power taken away."},{"id":"inclusive","kind":"topic","match":["inclusive","exclusive"],"term":"inclusive or exclusive","def":"Inclusive: letting everyone belong. Exclusive: shutting some people out."},{"id":"moral","kind":"topic","match":["ethical","moral"],"term":"moral, ethical","def":"About right and wrong."},{"id":"divergence","kind":"topic","match":["divergence"],"term":"divergence","def":"Being different from what's normal or expected."},{"id":"tolerated","kind":"topic","match":["tolerated"],"term":"tolerated","def":"Put up with or allowed, even if not liked."},{"id":"individuality","kind":"topic","match":["individual rights","individuality"],"term":"individuality","def":"Being yourself, different from others; individual rights are what each person is entitled to."},{"id":"crises","kind":"topic","match":["societal crises","crises","crisis"],"term":"crisis","def":"A time of great trouble or danger, when things could go either way."},{"id":"democratic","kind":"topic","match":["democratic"],"term":"democratic","def":"Where people share power and have a say in decisions."},{"id":"mindset","kind":"topic","match":["frame of mind","mindset"],"term":"mindset","def":"A way of thinking that shapes how you see things."},{"id":"nurture","kind":"topic","match":["nurtured","nurture","instilled"],"term":"nurture","def":"To care for something and help it grow; instilled means put into someone's mind over time."},{"id":"perception","kind":"topic","match":["perception"],"term":"perception","def":"How you see and understand something."},{"id":"impression","kind":"topic","match":["initial impression","impressions","impression"],"term":"impression","def":"The view or feeling you're left with."},{"id":"insight","kind":"topic","match":["insights","insight"],"term":"insight","def":"A new or deeper understanding."},{"id":"exploration","kind":"topic","match":["exploration","explored"],"term":"exploration","def":"How a text looks closely at something and examines it from different sides."},{"id":"portrayal","kind":"topic","match":["portrayal"],"term":"portrayal","def":"How something or someone is shown."},{"id":"significant","kind":"topic","match":["significant"],"term":"significant","def":"Important: it changes something or tells us something."},{"id":"evident","kind":"topic","match":["evident"],"term":"evident","def":"Clear to see; shown."},{"id":"revealed","kind":"topic","match":["revealed","reveals","reveal"],"term":"reveal","def":"Show or uncover something that wasn't clear before."},{"id":"aspects","kind":"topic","match":["aspects","aspect","dimensions"],"term":"aspect","def":"A part or side of something."},{"id":"factors","kind":"topic","match":["factors","factor"],"term":"factor","def":"Something that causes or helps cause a result."},{"id":"influence","kind":"topic","match":["over-influential","influenced","influences","influence"],"term":"influence","def":"To affect or shape something. Over-influential means having too strong an effect."},{"id":"shape","kind":"topic","match":["shaped","shaping","shape"],"term":"shape","def":"To form something, or make it what it is."},{"id":"pivotal","kind":"topic","match":["pivotal moment","pivotal"],"term":"pivotal moment","def":"A turning point: the moment everything changes."},{"id":"climax","kind":"topic","match":["climax"],"term":"climax","def":"The point of highest tension, where everything comes to a head."},{"id":"resolved","kind":"topic","match":["resolved","resolution"],"term":"resolved","def":"Sorted out by the end, so we know how things stand."},{"id":"central","kind":"topic","match":["central characters","central character"],"term":"central character","def":"A main character, the one the story is most about."},{"id":"relevant","kind":"topic","match":["relevant"],"term":"relevant","def":"Connected to something, so it matters to it."},{"id":"emotional","kind":"topic","match":["emotional responses","emotionally","emotional"],"term":"emotional response","def":"How a text makes you feel, and why."},{"id":"unacceptable","kind":"topic","match":["unacceptable"],"term":"unacceptable","def":"Not allowed, or seen as wrong, in that society."}]};
